insert into public.courses
    (code, name, hours, description, exclusions, breadth, prereq_tree)
values
    ('POL378H1', 'Topics in Comparative Politics II', '24L', 'An introduction to the field of comparative politics. Content in any given year depends on instructor.', null, 3, '{"operator": "OR", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL379H1', 'Topics in Comparative Politics III', '24L', 'An introduction to the field of comparative politics. Content in any given year depends on instructor.', null, 3, '{"operator": "OR", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL380H1', 'Topics in International Politics', '24L', 'Content in any given year depends on instructor.', null, 3, '{"operator": "OR", "items": ["POL208H1", "POL208Y1", "POL209H5", "POLB80H3"]}'::jsonb),
    ('POL381H1', 'Topics in Political Theory', '24L', 'A detailed examination of particular authors or topics in political theory. Content in any given year depends on instructor.', null, 2, '{"operator": "OR", "items": ["POL200Y1", "POL200Y5", {"operator": "AND", "items": ["POLC70H3", "POLC71H3"]}]}'::jsonb),
    ('POL382H1', 'Topics in Canadian Politics', '24L', 'Examines in depth enduring and emerging issues in Canadian politics. Content in any given year depends on instructor.', null, 3, '{"operator": "OR", "items": ["POL214H1", "POL214Y1", "POL214Y5", "POL215H5", "POL216H5", "POL224H1", "POL224Y1", "POLB50Y3"]}'::jsonb),
    ('POL384H1', 'Global Environmental Governance from the Ground Up', '24L', 'This course focuses on non-state actors in global environmental governance, considering the motivations, actions, and strategies of non-governmental organizations, grassroots communities, and corporations. The course uses analytic tools from international relations and comparative politics to understand patterns of environmental protest, resistance, and change over time.', null, 3, '{"operator": "OR", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL385H1', 'Issues in Contemporary Greece', '24L', 'This course is designed to comprehensively explore the theoretical, conceptual and empirical dimensions through the political history of the Greek state from the 19th c. to the present, and, to provide students with the critical skills to follow, understand and systematically analyze contemporary Greek politics. The class will alternate between highlights of Greek political history, theoretical foundations of major themes in Comparative Politics, and their empirical application to the politics of the Modern Greek state.', null, 3, '{"operator": "OR", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL386H1', 'U.S. Government and Politics', '24L', 'Who rules the United State of America? This course will investigate this question by examining how power is attained and how power is exercised in American elections, the legislative process, the bureaucracy, and the federal courts. Particular attention will be paid to the role of national interest groups, regional economic interests, and new modes of political mobilization.', 'POL203Y1/  POL203Y5/  POL386Y1/  POLC92H3/  POLC93H3', 3, '{"operator": "OR", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL387H1', 'Politics in Europe', '24L', 'This course applies the basic concepts in comparative politics to the political systems of Europe. We will cover theories of transitions to democracy, formation and development of the nation-state, political institutions and their effects, parties and party systems and elections and electoral behaviour. We will use these theories to gain a better understanding of politics in Europe. We will also address some of the major challenges that Europe and the EU have recently faced such as the eurozone crisis, Brexit, the rise of populism and extreme right parties and the challenges of immigration and incorporation of minorities. The goal is for students to become familiar with the politics and governments of contemporary Europe through the lens of current and classic themes in comparative politics.', 'POL207Y1/ POL302Y5', 3, '{"operator": "OR", "items": [{"credits": 1.0, "department": null}, "EUR200Y1"]}'::jsonb),
    ('POL388H1', 'Politics and Government of Southeast Asia', '24L', 'This course provides an overview of political regimes in Southeast Asia, as well as some of the main issues that shape its political life. It includes legacies of colonial rule, nationalist struggles, democratization, ethnic and secessionist conflict, as well as social movement.', null, 3, '{"operator": "OR", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL395H1', 'Research Participation', null, 'Credit course for supervised participation in a faculty research project. Offered only when a faculty member is willing and available to supervise. Interested faculty review plans with the Undergraduate Director, and then make the opportunity known to students as appropriate. Check with Undergraduate Office for more details and faculty proposal form. Not eligible for CR/NCR option.', 'POL299Y1', null, null::jsonb),
    ('POL396H1', 'Research Participation', null, 'Credit course for supervised participation in a faculty research project. Offered only when a faculty member is willing and available to supervise. Interested faculty review plans with the Undergraduate Director, and then make the opportunity known to students as appropriate. Check with Undergraduate Office for more details and faculty proposal form. Not eligible for CR/NCR option.', 'POL299Y1', null, null::jsonb),
    ('POL398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('POL398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('POL399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('POL399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('POL402H1', 'Problems in the Political Thought of the Socratic School', '24S', 'Study of a small number of texts illuminating the origins and/or legacy of Socratic political philosophy.', null, 2, '{"operator": "OR", "items": ["POL200Y1", "POL200Y5", {"operator": "AND", "items": ["POLC70H3", "POLC71H3"]}]}'::jsonb),
    ('POL405H1', 'The Military Instrument of Foreign Policy: Concepts and Approaches', '24S', 'In light of endemic international threats and conflicts, the seminar analyses the use of the military instrument of foreign policy. We meld theoretical and pragmatic approaches. Among the subjects covered are civil-military relations, the development of nuclear weapons, deterrence and nuclear deterrence, arms control and war termination strategies.', 'POL459Y1', 3, '{"operator": "OR", "items": ["POL208H1", "POL208Y1", "POL209H5", "POLB80H3"]}'::jsonb),
    ('POL410H1', 'Topics in Comparative Politics III', '24S', 'Selected issues in comparative politics. Vary from year to year.', null, 3, '{"operator": "OR", "items": [{"credits": 2.0, "department": null}]}'::jsonb),
    ('POL412H1', 'Human Rights and International Relations', '24S', 'Human rights have become dominant in international politics since the end of World War II. The process of creating and implementing human rights is political. We explore historical, philosophical, and empirical explanations of the roots, effects, and implications of human rights today through a variety of topics.', null, 3, '{"operator": "OR", "items": ["POL201H1", "POL201Y1", "POL208H1", "POL208Y1", "POL209H5", "POLB80H3", "POLB90H3", "POLB91H3"]}'::jsonb),
    ('POL413H1', 'Global Environmental Politics', '24S', 'Examines the challenges faced by humanity in dealing with global environmental problems and the politics of addressing them. Focuses on both the underlying factors that shape the politics of global environmental problems such as scientific uncertainty, North-South conflict, and globalization and explores attempts at the governance of specific environmental issues.', 'POLD89H3', 3, '{"operator": "OR", "items": ["POL208H1", "POL208Y1", "POL209H5", "POLB80H3"]}'::jsonb),
    ('POL416H1', 'Civil War and Counterinsurgency', '24S', 'This course overviews the origins, dynamics, and outcomes of civil war and counterinsurgency. It provides a theoretical, empirical, and methodological foundation for understanding these forms of conflict, the logic of their violence, and the determinants of their duration and outcomes.', 'POL487H1 (Topics in International Politics II: Civil War and Counterinsurgency), offered in Winter 2018 and Winter 2019;  POL487H5 (Topics in International Relations: Insurgents, Criminals, Warlords: Understanding Violent Non-State Actors in International Politics), offered in Fall 2020', 3, '{"operator": "OR", "items": ["POL208H1", "POL208Y1", "POL209H5", "POL210H5", "POLB80H3"]}'::jsonb),
    ('POL417H1', 'Politics of North-South Relations', '24S', 'This course explores the complex relations between the developed world and Global South in historical and contemporary settings. It engages critical scholarship within International Politics and International Political Economy to examine salient factors in North-South relations such as dependency and interdependence, trade, development aid, global governance architecture, and South-South cooperation.', 'POL417Y1', 3, '{"operator": "OR", "items": ["POL201H1", "POL201Y1", "POL208H1", "POL208Y1", "POL209H5", "POLB80H3", "POLB90H3"]}'::jsonb),
    ('POL418H1', 'Human Security and Intra-state Conflicts in the Global South', '24S', 'What are the underlying causes of insecurity and instability, and what factors support or undermine attainment of durable peace after episodes of violent conflict in the Global South? This course explores these questions by focusing on identity-based conflicts and through comparative case studies and theoretical perspectives from political science and related disciplines.', 'POL417Y1', 3, '{"operator": "OR", "items": ["POL201H1", "POL201Y1", "POL208H1", "POL208Y1", "POL209H5", "POLB80H3", "POLB90H3"]}'::jsonb),
    ('POL420H1', 'Globalization, Democracy and Growth', '24S', 'This course introduces students to recent work in the rational choice institutionalist tradition in comparative political economy. It focuses on the link between institutions and economic policy, starting with an examination of the effect on economic outcomes of specific democratic institutions, such as the separation of powers or delegation to unelected officials like central bankers. In so doing it also asks whether globalization has altered the relationship between democratic institutions and economic policy choices. Most of the readings rely on either formal models or quantitative empirics; students will therefore also acquire proficiency in the interpretation of such work.', 'POL443H1 (Globalization, Democracy and Growth), offered in Winter 2017, 2018, 2019, 2024, and 2025', 3, '{"operator": "OR", "items": [{"credits": 2.0, "department": null}]}'::jsonb),
    ('POL421H1', 'Maimonides and His Modern Interpreters', '24S', 'The course offers an introduction to the seminal work of Jewish philosophy, ''The Guide of the Perplexed'' by Moses Maimonides. We will delve into some of the basic themes of Jewish philosophical theology and religion as they are treated by Maimonides.', 'RLG433H1', 2, '{"operator": "OR", "items": ["POL200Y1", "POL200Y5", {"operator": "AND", "items": ["POLC70H3", "POLC71H3"]}]}'::jsonb),
    ('POL422H1', 'Judicial Politics', '24S', 'This course provides an in-depth understanding of the social and political origins of judicial power and the growing role that courts play in democracies and autocracies. Adopting a comparative perspective, we will probe when and why citizens, social movements, and policymakers turn to the courts and support judicial power, what factors shape how judges make decisions, when judicial decisions beget compliance and defiance, and how courts shape regime politics like democratization, democratic backsliding, and autocratic consolidation. Throughout we will bring cutting-edge research to life with concrete examples: from domestic courts like the US Supreme Court to international courts like the European Court of Justice; from judicial politics in liberal democracies like Canada, to backsliding regimes like Hungary, to consolidated autocracies like Egypt.', 'POL438H1 (Judicial Politics), offered in Fall 2023 and Winter 2025', 3, '{"operator": "OR", "items": [{"credits": 2.0, "department": null}]}'::jsonb),
    ('POL425H1', 'State and Development in Historical Perspective', '24S', 'What is the state''s role in economic development? What caused the Industrial Revolution, and why was Britain at its forefront? This course examines a variety of competing, and complementary, explanations for historical (and present-day) variation in patterns of economic development, focusing on the state''s role in each.', 'POL443H1 (Topic: State and Development in Historical Perspective) offered in Winter 2023 and 2024.', 3, '{"operator": "OR", "items": ["POL222H1", "POL352H1"]}'::jsonb),
    ('POL426H1', 'Democracy and Dictatorship', '24S', 'The course provides an in-depth introduction to theories of the origins of democracy and dictatorship. In the first part of the course, we examine and compare theories rooted in economic development, voluntarism, institutional design, and historical institutionalism. The latter half of the course applies these different approaches to debates over the origins of Nazi rule in Germany in the 1930s, military dictatorship in Chile in the 1970s, and non-democratic rule in contemporary Russia.', null, 3, '{"operator": "OR", "items": [{"credits": 2.0, "department": null}]}'::jsonb),
    ('POL427H1', 'American Political Development', '24S', 'This course explores both the substance and the theory of APD, using the second as a lens through which the first can be analyzed and interpreted. We begin by examining the methodologies, mechanisms, and patterns of APD, before turning to synoptic accounts of political development and then working through broad eras of political development. Throughout we will focus on questions of race, democracy, and inclusion/exclusion that both animate the American past and structure its present.', 'POL492H1 (American Political Development), offered in Winter 2022, 2023, 2024, and 2025.', 3, '{"operator": "OR", "items": [{"credits": 2.0, "department": null}]}'::jsonb),
    ('POL428H1', 'Federalism and Diversity in Canada (and Beyond)', '24S', 'Canada as a key case in comparative federalism studies, with a particular focus on the management of diversity and conflict. Federal theory is applied to analyze federal institutions and dynamics in Canada (and other cases). Topics include the distribution of power, the judiciary''s role and group representation.', null, 3, '{"operator": "AND", "items": ["POL214H1", "POL316H1"]}'::jsonb),
    ('POL431H1', 'Dynamics of Political Change in Contemporary China', '24S', 'This course will explore processes of political change in post-Mao China through an examination of selected systemic challenges and regime responses. The primary focus will be on processes of institutional development and decay as the Party-State regime evolves from hard to soft authoritarianism.', 'POL431Y1', 3, null::jsonb),
    ('POL432H1', 'Feminist Political Thought', '24S', 'Feminist theory offers basic challenges to the foundations of modern political and legal thought. It suggests a different conception of human nature and a different model of epistemology and of appropriate forms of argument about the traditional issues of legal and political theory: justice, power, equality and freedom. Introduction to the foundations of feminist theory, an analysis of its implications for traditional liberal theory, and an application of feminist theory to law.', null, 2, '{"operator": "OR", "items": ["POL200Y1", "POL200Y5", {"operator": "AND", "items": ["POLC70H3", "POLC71H3"]}]}'::jsonb),
    ('POL433H1', 'Topics in United States Government and Politics', '24S', 'Selected issues and topics in U.S. politics. Vary from year to year.', null, 3, '{"operator": "OR", "items": [{"credits": 2.0, "department": null}]}'::jsonb),
    ('POL435H1', 'Business and Politics: Power in a Global World', '24S', 'This seminar course examines the political power of business from an international and comparative perspective. Topics include the role of public authority in governing business behavior, the formation of business interests, corporate lobbying, structural and ideational business power, corporate social responsibility, and transnational private governance.', null, 3, '{"operator": "OR", "items": [{"credits": 2.0, "department": null}]}'::jsonb),
    ('POL438H1', 'Topics in Comparative Politics I', '24S', 'Selected issues in comparative politics. Vary from year to year.', null, 3, '{"operator": "OR", "items": [{"credits": 2.0, "department": null}]}'::jsonb),
    ('POL439H1', 'The Canadian Welfare State in Comparative Perspective', '24S', 'The course examines contemporary Canadian social policy in light of the scholarly literature on the welfare states of advanced industrial societies. Topics include the variety of welfare state regimes in rich nations, and their comparative performance in reducing inequality and poverty, in labour market and economic outcomes, and in addressing the specific circumstances of women. Specific Canadian policy fields examined will include pensions, social assistance, child care and health insurance.', null, 3, '{"operator": "OR", "items": ["POL214H1", "POL214Y1", "POL215H5", "POL216H5", "POL224H1", "POL224Y1", "POLB50Y3"]}'::jsonb),
    ('POL440H1', 'Topics in Methods II', '24S', 'Content depends on instructor. This course will be used for a new or short-term 400-level methods course, which requires only  POL222H1, Introduction to Quantitative Reasoning I as its prerequisite.', null, 3, '{"operator": "OR", "items": ["POL222H1"]}'::jsonb),
    ('POL441H1', 'Topics in Asian Politics', '24S', 'Selected issues in Asian politics. Content in any given year depends on instructor.', null, 3, '{"operator": "OR", "items": ["POL201H1", "POL201Y1", "POLB90H3", "POLB91H3"]}'::jsonb),
    ('POL442H1', 'Topics in Latin American Politics', '24S', 'This course explores Latin American protests and social movements since the late 20th century to the present. It focuses on subaltern mobilizing experiences shaping the region from the ground up. Course content emphasizes collective actors'' political agency and intellectual work, as well as intersections of coloniality, race, gender, and class.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["POL201H1", "POL201Y1", "POLB90H3", "POLB91H3"]}, {"operator": "OR", "items": ["POL305H1", "POL305Y1"]}]}'::jsonb),
    ('POL443H1', 'Topics in Comparative Politics II', '24S', 'Selected issues in comparative politics. Vary from year to year.', null, 3, '{"operator": "OR", "items": [{"credits": 2.0, "department": null}]}'::jsonb),
    ('POL444H1', 'Land and Indigenous Politics', '24S', 'This seminar examines Indigenous politics through land. We explore transnational Indigenous politics by focusing on global struggles over land. The course considers how Indigenous land-based movements, connected across territories and oceans, are constituted through and cultivate relations between Indigenous peoples and their social ecologies and more-than-human existents.', 'POL443H1 (Topics in Comparative Politics II: Land and Indigenous Politics) taken in Winter 2020 (LEC0101), Winter 2021 (LEC0101), Winter 2022 (LEC0101), Winter 2023 (LEC0101)', 2, '{"operator": "OR", "items": [{"credits": 2.0, "department": null}]}'::jsonb),
    ('POL445H1', 'Politics of Growth in Developing Countries', '24S', 'The course examines the politics of economic growth in developing countries. It focuses on political factors to analyze why some developing countries have done better in terms of growth than others. Conceptual frameworks of growth and related themes such as regime type, institutions, inequality and ethnicity will be addressed.', null, 3, '{"operator": "OR", "items": ["POL201H1", "POL201Y1", "POLB90H3", "POLB91H3"]}'::jsonb),
    ('POL447H1', 'Political Economy of Development', '24S', 'The course explores the rise, evolution, and performance of the dominant neoliberal approach to development and poverty reduction. It also assesses the feasibility and efficacy of alternative development strategies. Case studies are drawn from Latin America, Asia, and Africa.', null, 3, '{"operator": "OR", "items": ["POL201H1", "POL201Y1", "POL218H1", "POL301H1", "POL301Y1", "POL305H1", "POL305Y1", "POL309H1", "POL325H1", "POLB90H3", "POLB91H3"]}'::jsonb),
    ('POL452H1', 'Political Representation', '24S', 'This course explores questions of political representation in Canadian politics. While the overwhelming focus will be on the Canadian case, the course often draws upon examples and readings from other countries/institutional contexts to highlight important differences and similarities. The course considers where political representatives come from, how representative our legislatures are, and what representatives do. Weekly topics include political ambition, recruitment, electoral systems and quotas, and substantive representation.', 'POL491H1 (Women and Representation: Who Gets Elected), offered in Fall 2023; (Political Participation: Who Gets Elected), offered in Fall 2024.', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["POL214H1", "POL215H5", "POL216H5", "POL224H1", "POLB50Y3"]}, {"credits": 1.0, "department": null}]}'::jsonb),
    ('POL454H1', 'Innovation and Knowledge Transfer in City Regions', '24S', 'This course surveys two of the key themes related to the process of innovation in a knowledge-based economy: the process by which new knowledge is generated and effectively transferred to those organizations with the potential to commercialize it; and secondly, the paradoxical relationship between knowledge creation and proximity in a modern global economy. (Offered in alternate years)', null, 3, '{"operator": "OR", "items": ["CSC300H1", "GGR431H1", "HPS202H1", "HPS431H1", "POL218Y5", "POL409H1", "SOC356Y1"]}'::jsonb),
    ('POL455H1', 'Twentieth Century Ukraine', '24S', 'This course will focus on the evolution of Ukraine as a state from its failed struggle for independence after World War I, its existence as a Soviet Ukrainian state, to its full independence after the collapse of Communist rule and the Soviet Union.', 'JHP454Y1', 3, '{"operator": "OR", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('POL456H1', 'Global Summit Governance and Diplomacy', '24S', 'The development, participants and performance of global summit governance, focusing on the Group of Seven and Group of Twenty as "soft law" plurilateral summit institutions and their relationship with the "hard law" multilateral organizations of the United Nations and Bretton Woods bodies in a globalizing world.', 'POL456Y1', 3, '{"operator": "OR", "items": ["POL208H1", "POL208Y1", "POL209H5", "POLB80H3"]}'::jsonb),
    ('POL459H1', 'Military Instruments and Foreign Policy', '24S', 'This seminar assesses the efficacy of the military instrument of foreign policy through the prism of various case studies that range geographically and historically. It examines the motivations and policy formulations of key states. The case studies focus on power projection, limited war, nuclear threats, and war termination strategies.', 'POL459Y1', 3, '{"operator": "OR", "items": ["POL208H1", "POL208Y1", "POL209H5", "POLB80H3"]}'::jsonb),
    ('POL466H1', 'Topics in International Politics III', '24S', 'For advanced students of international relations. Various topics are taken up each year, the content of which depends on the instructor.', null, 3, '{"operator": "OR", "items": ["POL208H1", "POL208Y1", "POL209H5", "POLB80H3"]}'::jsonb),
    ('POL467H1', 'The Politics of Immigration and Multiculturalism in Canada', '24S', 'This course examines Canadian immigration and multiculturalism from theoretical, empirical and applied perspectives. It includes a discussion of normative foundations, an analysis of the components of the policy framework, and an assessment of the impact of immigration and multiculturalism on other aspects of social, cultural and political life.', null, 3, '{"operator": "OR", "items": ["POL214H1", "POL214Y1", "POL215H5", "POL216H5", "POL224H1", "POL224Y1", "POLB50Y3"]}'::jsonb),
    ('POL469H1', 'Ethics and International Relations', '24S', 'The course aims to explore the requirements of justice and fairness in international affairs. It is common to theorize international relations in terms of interests and power. But even the most cursory look at what important actors actually do in their international interactions reveals that they use normative language all the time. This has not gone unnoticed, with investigations of ethics in the international arena multiplying in recent years. Drawing on readings from political philosophy, legal theory, and normative international relations theory, the course will take up practical ethical dilemmas encountered in world affairs. The main focus of the course will be on institutions. Examples will be drawn from the issue areas of trade, health, and the environment, among others.', null, 2, '{"operator": "OR", "items": ["POL200Y1", "POL200Y5", "POL208H1", "POL208Y1", "POL209H5", "POLB80H3", {"operator": "AND", "items": ["POLC70H3", "POLC71H3"]}]}'::jsonb),
    ('POL470H1', 'Media & Politics', '24S', 'Technological change transformed the way politics is reported by journalists. This course introduces students to debates at the intersection of media and politics in Western democracies. Topics include the changing information environment, framing and priming effects, agenda setting, media bias, and the rise of social and partisan media, and misinformation.', 'POL410H1 (Topics in Comparative Politics III - Media and Politics) Taken in Fall 2021 (LEC0101), Fall 2022 (LEC0101),  POL369Y5', 3, '{"operator": "AND", "items": [{"credits": 2.0, "department": "POL"}, {"operator": "OR", "items": ["POL222H1", "POL242Y5", "POLC78H3"]}]}'::jsonb),
    ('POL474H1', 'Politics and Policy Analysis', '24S', 'Major theories of public policy-making and related approaches to policy analysis are examined from the perspective of political science. Key contributions to the theoretical literature pertaining to leading models are read and discussed. Models of public policy-making are successively applied to analysis of cases of Canadian and comparative policy development.', null, 3, '{"operator": "OR", "items": ["POL214H1", "POL214Y1", "POL215H5", "POL216H5", "POL224H1", "POL224Y1", "POLB50Y3"]}'::jsonb),
    ('POL475H1', 'Postmodern and Contemporary Thought', '24S', 'Study of postmodern and contemporary themes. Beginning with political economy, then the effect of technology on politics, a discussion of Western colonialism leading to a revised concept of social relations. Social contract theory will be analyzed through a natural contract as well as examination of individualism and the posthuman.', 'POL475Y1', 2, null::jsonb),
    ('POL476H1', 'Topics in Public Policy', '24S', 'The course is designed for advanced students with serious interests in the public policy field. Specific topics covered will vary from year to year.', null, 3, '{"operator": "OR", "items": ["POL214H1", "POL214Y1", "POL215H5", "POL216H5", "POL224H1", "POL224Y1", "POLB50Y3"]}'::jsonb),
    ('POL477H1', 'Advanced Topics in International Political Economy', '24S', 'The course is designed for advanced students with serious interests in the subfield of international political economy. Specific topics covered will vary, but all involve the deep interplay between politics and economics in the contemporary world.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["POL208H1", "POL208Y1", "POL209H5", "POLB80H3", "POLB81H3"]}, "ECO101H1", "ECO102H1"]}'::jsonb),
    ('POL478H1', 'Topics in Methods', '24S', 'Various topics are taken up each year, the content of which depends on the instructor.', null, null, '{"operator": "AND", "items": ["POL232H1"]}'::jsonb),
    ('POL479H1', 'Topics in Middle East Politics', '24S', 'This class undertakes an in-depth examination of various themes relating to politics and society in the Middle East and North Africa. Past topics include "Contesting Authoritarianisms in the Middle East" and Protest Politics in the Middle East."', null, 3, '{"operator": "OR", "items": ["POL201H1", "POL201Y1", "POLB90H3", "POLB91H3"]}'::jsonb),
    ('POL480H1', 'Studies in Comparative Political Theory', '24S', 'We will critically examine what “comparative political theory” is and what it would mean to genuinely “deparochialize” political theory, that is, to de-center Euro-American thought in the study of political ideas. The course neither presupposes background knowledge of any non-Western thought tradition, nor does it aspire to provide students with sufficient knowledge of particular traditions to ground serious scholarly contributions to this emerging field. To provide that background would require a series of specialized courses in, e.g., East Asian political thought, Indian political thought, Latin American political thought, Indigenous political thought, African political thought, and so on. Rather, the course aims at sharpening our understanding of (a) the purposes served by “deparochializing” political theory; and (b) the various methods by which we can seek to serve these purposes.', null, 2, '{"operator": "OR", "items": ["POL200Y1", "POL200Y5", {"operator": "AND", "items": ["POLC70H3", "POLC71H3"]}]}'::jsonb),
    ('POL483H1', 'Data Visualization for Political Science', '24S', 'This course provides the fundamental computational tools for managing, analyzing, and presenting political data in R. The material will enable students to become proficient enough to actively implement the methods and tools in their own research and professional lives.', 'POL 478H1 (Data Management and Visualization for Political Scientists), offered in Fall 2022 and 2023, and Winter 2025', 3, '{"operator": "AND", "items": ["POL232H1"]}'::jsonb),
    ('POL484H1', 'Topics in Political Thought I', '24S', 'A seminar on a central problem in political thought. It proceeds through the reading of a small number of major texts. Content in any given year depends on instructor.', null, 2, '{"operator": "OR", "items": ["POL200Y1", "POL200Y5", {"operator": "AND", "items": ["POLC70H3", "POLC71H3"]}]}'::jsonb),
    ('POL485H1', 'Topics in Political Thought II', '24S', 'A seminar on a central problem in political thought. It proceeds through the reading of a small number of major texts. Content in any given year depends on instructor.', null, 2, '{"operator": "OR", "items": ["POL200Y1", "POL200Y5", {"operator": "AND", "items": ["POLC70H3", "POLC71H3"]}]}'::jsonb),
    ('POL486H1', 'Topics in International Politics I', '24S', 'For advanced students of international relations. Various topics are taken up each year, the content of which depends on the instructor.', null, 3, '{"operator": "OR", "items": ["POL208H1", "POL208Y1", "POL209H5", "POLB80H3"]}'::jsonb),
    ('POL487H1', 'Topics in International Politics II', '24S', 'For advanced students of international relations. Various topics are taken up each year, the content of which depends on the instructor.', null, 3, '{"operator": "OR", "items": ["POL208H1", "POL208Y1", "POL209H5", "POLB80H3"]}'::jsonb),
    ('POL488H1', 'Topics in African Politics I', '24S', 'In depth examination of specific themes relating to contemporary African politics. Content in any given year depends on instructor.', null, 3, '{"operator": "OR", "items": ["POL201H1", "POL201Y1", "POLB90H3", "POLB91H3"]}'::jsonb),
    ('POL489H1', 'Topics in African Politics II', '24S', 'In depth examination of specific themes relating to contemporary African politics. Content in any given year depends on instructor.', null, 3, '{"operator": "OR", "items": ["POL201H1", "POL201Y1", "POLB90H3", "POLB91H3"]}'::jsonb),
    ('POL490H1', 'Topics in Canadian Politics I', '24S', 'Examines in depth enduring and emerging issues in Canadian politics. Content in any given year depends on instructor.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["POL214H1", "POL214Y1", "POL215H5", "POL216H5", "POL224H1", "POL224Y1", "POLB50Y3"]}, {"credits": 1.0, "department": "POL"}]}'::jsonb),
    ('POL491H1', 'Topics in Canadian Politics II', '24S', 'Examines in depth enduring and emerging issues in Canadian politics. Content in any given year depends on instructor.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["POL214H1", "POL214Y1", "POL215H5", "POL216H5", "POL224H1", "POL224Y1", "POLB50Y3"]}, {"credits": 1.0, "department": "POL"}]}'::jsonb),
    ('POL492H1', 'Topics in Comparative Politics IV', '24S', 'Selected issues in comparative politics. Vary from year to year.', null, 3, '{"operator": "AND", "items": [{"credits": 2.0, "department": "POL"}]}'::jsonb),
    ('POL493H1', 'Topics in Politics I', '24S', 'An in-depth examination of a "big issue" in Political Science. Content in any given year depends on instructor.', null, 3, '{"operator": "AND", "items": [{"credits": 3.0, "department": "POL"}]}'::jsonb),
    ('POL494H1', 'Topics in Politics II', '36S', 'An in-depth examination of a "big issue" in Political Science. Content in any given year depends on instructor.', null, 3, '{"operator": "AND", "items": [{"credits": 3.0, "department": "POL"}]}'::jsonb),
    ('POL496H1', 'Independent Studies', null, 'Open only when a Political Science full-time faculty member is willing and available to supervise. Students must find an appropriate supervisor in the Department of Political Science and obtain the approval of the Director of Undergraduate Studies before enrolling. Obtain details and an application form from the Department Undergraduate Office. Application forms can also be downloaded from the Department''s website at www.politics.utoronto.ca. Not eligible for CR/NCR option.', 'POL495Y1', null, null::jsonb),
    ('POL497H1', 'Independent Studies', null, 'Open only when a Political Science full-time faculty member is willing and available to supervise. Students must find an appropriate supervisor in the Department of Political Science and obtain the approval of the Director of Undergraduate Studies before enrolling. Obtain details and an application form from the Department Undergraduate Office. Application forms can also be downloaded from the Department''s website at www.politics.utoronto.ca. Not eligible for CR/NCR option.', 'POL495Y1', null, null::jsonb),
    ('POL498H1', 'Intensive Course', null, 'Content in any given year depends on instructor. Intensive courses are offered by distinguished visitors from around the world. Students in their 4th year are strongly encouraged to take advantage of this unique opportunity to study with one or more outstanding visiting international scholars that the Department brings from time to time. The intensive course usually runs for approximately 3-4 weeks.', null, null, null::jsonb),
    ('POL499Y1', 'Senior Thesis and Thesis Seminar', null, 'A 40 to 60-page (15,000 to 20,000 word) research paper (75% of the final mark) written under the supervision of a political science faculty member and a companion thesis seminar (25% of final mark). The seminar provides a forum for students to periodically present and discuss their on-going research and to examine issues and approaches related to the structure, organization and presentation of the thesis. Not eligible for CR/NCR option.', 'POL495Y1/ POL496H1/ POL497H1 (taken in the same session)', null, null::jsonb),
    ('PPG200H1', 'Microeconomics for Policy Analysis', '24L', 'The objectives are: (1) To provide students with a foundation in microeconomic analysis and; (2) To demonstrate how this foundation can be applied to design, predict the effects of and evaluate public policies. Students will be equipped to understand the main issues on a range of policy topics such as taxation, social insurance, welfare and income support programs.', 'ECO200Y1,  ECO204Y1,  ECO206Y1', 3, '{"operator": "OR", "items": [{"operator": "AND", "items": ["ECO101H1", "ECO102H1"]}, "ECO105Y1"]}'::jsonb),
    ('PPG301H1', 'Introduction to Public Policy', '24L', 'The course introduces students to the study of public policy, the policy process and our policy institutions in Canada. The course examines how issues emerge, how important ideas are framed, priorities are established, and agendas are set and managed. It explores how institutions – formal and informal rules which enable and constrain actors – shape policy-making in Canada.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ECO200Y1", "ECO204Y1", "ECO206Y1", "PPG200H1"]}, {"operator": "OR", "items": ["ECO220Y1", {"operator": "AND", "items": ["POL222H1", "POL232H1"]}, "SOC202H1", "STA220H1", "STA221H1", "STA248H1", "STA255H1", "STA261H1"]}, {"operator": "OR", "items": ["POL214Y1", {"operator": "AND", "items": ["POL218H1", "POL219H1"]}]}]}'::jsonb),
    ('PPG310H1', 'Special Topics in Public Policy', '24L', 'This course examines a selected topic in public policy, based on the research interests of an individual instructor. Both the topics and the instructor may change each time the course is offered.', null, 3, '{"operator": "AND", "items": ["PPG200H1"]}'::jsonb),
    ('PPG401H1', 'The Role of Government', '30L', 'This course explores the government''s role in promoting efficiency and equity in both the financing and delivery of public policy goals. It explores the conditions when government involvement is important, the policy levers available to government in promoting social policy, market failures, and conditions for efficiency. It examines the role of government in many of the major areas of social policy such as health care, education, redistribution, the environment, financial regulations and other important issues.', null, 3, '{"operator": "AND", "items": ["PPG301H1"]}'::jsonb),
    ('PPG410H1', 'Advanced Topics in Public Policy', '24L', 'This course examines a selected advanced topic in public policy, based on the research interests of an individual instructor. Both the topics and the instructor may change each time the course is offered.', null, 3, '{"operator": "AND", "items": ["PPG200H1", "PPG301H1"]}'::jsonb),
    ('PRT101H1', 'Portuguese for Beginners I', '48L', 'Introductory course to Portuguese for students with no previous knowledge of this language or advanced proficiency in Spanish. Students develop basic knowledge and reading, listening, speaking and writing skills, within a communicative approach. Students are introduced to cultural aspects of the Portuguese-speaking world. Taught in English and Portuguese.', 'PRT100Y1,  PRT102H1,  PRT120Y1,  PRT120H1,  PRT201H1,  PRT202H1,  PRT205H1,  PRT219Y1,  PRT220Y1,  PRT301H1,  PRT302H1,  PRT320Y1,  PRT420H1,  PRT420Y1', 1, null::jsonb),
    ('PRT102H1', 'Portuguese for Beginners II', '48L', 'A continuation of introductory Portuguese for non-native speakers. Students will expand their basic knowledge of cultural aspects of the Portuguese-speaking world and their reading, listening, speaking and writing skills in the target language. Taught in English and Portuguese.', 'PRT100Y1,  PRT120Y1,  PRT120H1,  PRT201H1,  PRT202H1,  PRT205H1,  PRT219Y1,  PRT220Y1,  PRT301H1,  PRT302H1,  PRT320Y1,  PRT420H1,  PRT420Y1', 1, '{"operator": "AND", "items": ["PRT101H1"]}'::jsonb),
    ('PRT120H1', 'Portuguese for Spanish Speakers', '36L', 'Introduction to the Portuguese language for speakers of Spanish. Development of listening, speaking, reading, and writing skills with an emphasis on communication, and an overview of basic grammatical structures and building of vocabulary. Presentation of cultural aspects of the Portuguese-speaking world.', 'PRT100Y1,  PRT120Y1,  PRT201H1,  PRT202H1,  PRT205H1,  PRT219Y1,  PRT219H1,  PRT220Y1,  PRT301H1,  PRT302H1,  PRT320Y1,  PRT420Y1,  PRT420H1', 1, '{"operator": "OR", "items": ["SPA320Y1", "SPA302H1"]}'::jsonb),
    ('PRT201H1', 'Intermediate Portuguese I', '36L', 'This course expands the linguistic repertoire of learners beyond basic structures by offering a review of grammar at an intermediate level. Introduction to authentic cultural materials from the Portuguese-speaking world with practice designed to build vocabulary, and to improve oral and written expression. Taught in Portuguese with occasional English.', 'PRT202H1,  PRT205H1,  PRT219Y1,  PRT219H1,  PRT220Y1,  PRT301H1,  PRT302H1,  PRT320Y1,  PRT420Y1,  PRT420H1', 1, '{"operator": "OR", "items": ["PRT100Y1", "PRT102H1", "PRT120Y1", "PRT120H1"]}'::jsonb),
    ('PRT202H1', 'Intermediate Portuguese II', '36L', 'This course continues to expand the linguistic repertiture of learners to a high intermediate level, expanding the use of authentic cultural materials from the Portuguese-speaking world and promoting increased development of vocabulary, and oral and written expression. Taught in Portuguese with occasional English.', 'PRT205H1,  PRT219Y1,  PRT219H1,  PRT220Y1,  PRT301H1,  PRT302H1,  PRT320Y1,  PRT420Y1,  PRT420H1', 1, '{"operator": "AND", "items": ["PRT201H1"]}'::jsonb),
    ('PRT205H1', 'Portuguese for Heritage Speakers', '36L', 'For students who have had exposure to spoken Portuguese in an informal context (living in a Portuguese speaking country, or in a Portuguese speaking family) but little to no exposure to written Portuguese. Besides reviewing English/Portuguese spelling differences, written and spoken registers of Portuguese, and basic aspects of the grammatical system, the course (1) provides students with the essential understanding of Portuguese grammatical system; (2) builds their vocabulary; and (3) trains them to express themselves formally in both spoken and written Portuguese. Taught in English and Portuguese.', 'PRT100Y1,  PRT101H1,  PRT102H1,  PRT120Y1,  PRT120H1,  PRT201H1,  PRT202H1,  PRT219Y1,  PRT219H1,  PRT220Y1,  PRT301H1,  PRT302H1,  PRT320Y1,  PRT420H1,  PRT420Y1', 1, null::jsonb),
    ('PRT221H1', 'Portuguese Pronunciation', '24L', 'Overview of Portuguese speech sounds (articulation and transcription). The course provides perception and pronunciation training of Portuguese vowels, consonants, stress, intonation, and co-articulation phenomena in connected speech. The main focus will be on European Portuguese and Brazilian Portuguese, but differences between these two and other Portuguese accents will be discussed as well.', 'PRT219Y1,  PRT219H1,  PRT205H1, native speakers of Portuguese', 2, '{"operator": "OR", "items": ["PRT102H1", "PRT100Y1"]}'::jsonb),
    ('PRT250H1', 'Introduction to the Cultures of the Portuguese-Speaking World', '24L', 'A survey of historical and cultural trends in the Portuguese-speaking world, from colonial past to the present. (Offered in alternate years; taught in English)', null, 1, null::jsonb),
    ('PRT258H1', 'Introduction to the Literatures of the Portuguese-Speaking World', '24L', 'Students expand their reading, writing, and critical skills through the study of a representative selection of short stories and poetry from Portugal, Brazil, and Lusophone Africa. Required for a program degree. Taught in Portuguese.', 'PRT258Y1', 1, '{"operator": "OR", "items": ["PRT120H1", "PRT201H1"]}'::jsonb),
    ('PRT299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PRT299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PRT301H1', 'Advanced Portuguese I', '36L', 'Intensive practice in written and oral Portuguese for the student with advanced proficiency in the language. Selective review of grammar with emphasis on complex language structures. Taught in Portuguese.', 'PRT302H1,  PRT320Y1,  PRT420Y1,  PRT420H1', 1, '{"operator": "OR", "items": ["PRT202H1", "PRT205H1", "PRT219Y1", "PRT219H1", "PRT220Y1"]}'::jsonb),
    ('PRT302H1', 'Advanced Portuguese II', '36L', 'This course continues to improve written and oral proficiency for the student with advanced proficiency in Portuguese, offering a selective review of grammar with emphasis on the complex sentence. Taught in Portuguese.', 'PRT320Y1,  PRT420Y1,  PRT420H1', 1, '{"operator": "OR", "items": ["PRT301H1", "PRT220Y1"]}'::jsonb),
    ('PRT322H1', 'Introduction to Portuguese Linguistics', '24L', 'An overview of theoretical and methodological aspects of Portuguese linguistics: phonology, morphology, syntax, and semantics. Analysis of structural similarities and differences between the two worldwide main Portuguese varieties - Brazilian and European Portuguese.', null, 2, '{"operator": "OR", "items": ["PRT120Y1", "PRT120H1", "PRT202H1", "PRT205H1", "PRT219H1", "PRT219Y1", "PRT220Y1"]}'::jsonb),
    ('PRT323H1', 'Business Portuguese', '36L', 'An advanced level business Portuguese course covering topics on international relations, politics, legal and culture. This course aims to enhance written and oral expressions in Portuguese through content focusing on the language that is used in official, diplomatic, and financial situations. Through the analysis of case studies, newspapers and videos, students will be introduced to the business cultures and intercultural communication of the Portuguese-speaking world. Taught in Portuguese.', null, 1, '{"operator": "OR", "items": ["PRT120Y1", "PRT120H1", "PRT202H1", "PRT205H1", "PRT220Y1"]}'::jsonb),
    ('PRT342H1', 'History of Portuguese Language', '24L', 'This interdisciplinary course provides an overview of the evolution of Portuguese language from 15th century to the present. It discusses linguistic change by analyzing texts from a variety of genres in different historical periods and geographical contexts. Taught in Portuguese. (Offered every three years)', null, 2, '{"operator": "OR", "items": ["PRT202H1", "PRT205H1", "PRT120Y1", "PRT219Y1", "PRT219H1", "PRT220Y1"]}'::jsonb),
    ('PRT350H1', 'Portuguese Language and Society', '24L', 'Explores how factors such as ethnicity, gender, social class and age affect the use of Portuguese language and determine its characteristics. The course overviews mostly the aspects of Brazilian and European Portuguese. (Offered in alternate years.)', null, 2, '{"operator": "OR", "items": ["PRT202H1", "PRT205H1", "PRT219Y1", "PRT219H1", "PRT220Y1", "PRT120Y1"]}'::jsonb),
    ('PRT356H1', 'Topics in Portuguese Linguistics', '24S', 'A course on a specific topic in Portuguese linguistics, designed for advanced students. Course content and instructor are established on a yearly basis.', null, 2, '{"operator": "OR", "items": ["PRT202H1", "PRT205H1", "PRT219Y1", "PRT219H1", "PRT220Y1", "PRT120Y1"]}'::jsonb),
    ('PRT358H1', 'Topics in Portuguese Studies', '24L', 'Exploration of cultural topics relevant to the Portuguese-speaking world. Examples include: Brazilian Popular Music, Soccer and Society, Luso-Afro-Brazilian Environmental Narratives, and Lusophone Women Writers. Students can enroll in this course multiple times, as long as the topic of the course is different. For any questions, please reach out to the Associate Chairs of Undergraduate Studies or Portuguese Studies. Taught in Portuguese.', null, 1, '{"operator": "AND", "items": ["PRT258H1", {"operator": "OR", "items": ["PRT120H1", "PRT205H1", "PRT219Y1", "PRT219H1"]}]}'::jsonb),
    ('PRT364H1', 'Portuguese Language in the World', '24L', 'An overview of the varieties of Portuguese spoken in four continents (Europe, South America, Africa, Asia) and a discussion of the structural similarities and differences between the two most extensively studied varieties: European and Brazilian Portuguese. Analysis of linguistic variation in contemporary Portuguese in terms of phonetics, syntax and lexicon. (Offered in alternate years.)', null, 2, '{"operator": "OR", "items": ["PRT202H1", "PRT205H1", "PRT219Y1", "PRT219H1", "PRT120Y1", "PRT220Y1"]}'::jsonb),
    ('PRT375H1', 'Contemporary Brazilian Cinema', '36L/12T', 'This course covers aesthetic, cultural, and social aspects of contemporary Brazilian cinema. The course examines both works of fiction and documentaries from emerging voices as well as world renowned filmmakers, spanning from Cinema Novo to the present. Topics include: music and urban culture, violence, inequality, environmental justice, and gender and sexuality. Lecture time is divided between film screening and class discussion held in English. Students choose tutorials in Portuguese (necessary for this course to be considered towards credit in Portuguese programs) or English.', 'PRT275H1', 1, null::jsonb),
    ('PRT398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PRT398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PRT399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PRT399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PRT420H1', 'Advanced Academic Portuguese', '24L', 'A study of advanced aspects of formal Portuguese through reading and extensive writing practice, with an aim at developing skills necessary for academic and professional writing and oral presentations.', 'PRT420Y1', 1, '{"operator": "OR", "items": ["PRT302H1", "PRT320Y1"]}'::jsonb),
    ('PRT423H1', 'Community Engaged Learning of Portuguese in Toronto and the GTA', '24L/12P', 'This course combines advanced language instruction with the richness and complexity of the Lusophone work experience in Toronto, promoting Community Engaged Learning (CEL) as a vehicle for greater linguistic fluency and cultural understanding. Students are placed with community organizations within the Greater Toronto Area and volunteer for 2 hours per week, furthering their language skills and their cultural knowledge. Class work focuses on developing students'' communication skills through exposure to a range of topics, from financial, legal, medical to educational, and to an extensive variety of styles and registers in Portuguese. Therefore, students meet real needs in the community by applying knowledge from their Portuguese courses. Taught in Portuguese.', null, 3, '{"operator": "OR", "items": ["PRT302H1", "PRT320Y1"]}'::jsonb),
    ('PRT458H1', 'The Lusophone Short Story', '24S', 'Overview of the short story in the particular context of Portuguese-speaking countries. Examination of theories of the genre as they relate to short stories of Portuguese-speaking writers. (Offered in alternate years)', null, 1, '{"operator": "AND", "items": ["PRT258H1"]}'::jsonb),
    ('PRT470H1', 'Acquisition of Portuguese as a Second Language', '24S', 'Invites critical reflection about the acquisition of Portuguese as a second language. Analyzes phonological, morphosyntactic, semantic and lexical aspects in the linguistic performance of bilingual speakers, and of learners of Portuguese as a second language. (Offered in alternate years)', null, 2, '{"operator": "OR", "items": ["PRT202H1", "PRT205H1", "PRT219Y1", "PRT219H1", "PRT220Y1"]}'::jsonb),
    ('PRT490H1', 'Independent Study', null, 'Individual study with a member of staff on a topic of common interest including readings, discussion and written assignments. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": ["PRT320Y1"]}'::jsonb),
    ('PSL190H1', 'Biomedical Research at the Cutting Edge', '24L/6S', 'Explore the thought processes, logic, motivation, techniques, analysis and impact of recent high-profile publications to gain insight into the enterprise of science. Outstanding scientists present recent high-impact papers, and students will examine the research in depth, focusing on the underlying questions, experimental approach, results and significance. Restricted to first-year students. Not eligible for CR/NCR option.', null, 4, null::jsonb),
    ('PSL201Y1', 'Basic Human Physiology', '44L/24P', 'A survey course covering all organ systems intended for students who are not proceeding further in Physiology.', 'Any 300-level PSL course taken previously or concurrently', 4, null::jsonb),
    ('PSL280H1', 'Introduction to Physiologic Adaptations of Marine Mammals', '24L/14P', 'Systems approach to physiology of marine mammals in their aquatic environment. Highlights unique features of cardiovascular, respiratory, renal, urinary, and reproductive systems. Introduces relevant physiology, and makes comparisons to human condition and disease.', null, 4, '{"operator": "AND", "items": ["BIO120H1", "BIO130H1", {"operator": "OR", "items": ["CHM136H1", "CHM151Y1"]}]}'::jsonb),
    ('PSL299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PSL299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PSL300H1', 'Human Physiology I', '36L/5T', 'Principles of neurophysiology, endocrinology and reproductive physiology for students enrolled in Life Science programs.', 'PSL201Y1,  PSL302Y1', 4, null::jsonb),
    ('PSL301H1', 'Human Physiology II', '36L/4T', 'Principles of respiratory, cardiovascular, gastrointestinal, and renal physiology for students enrolled in Life Science programs.', 'PSL201Y1,  PSL302Y1', 4, null::jsonb),
    ('PSL304H1', 'Topics in Cellular, Molecular and Organismic Physiology I', '32L/16T', 'Focus on two topics: (1) The regulation of body weight/composition including the hormonal, neural and metabolic interactions between adipose tissue, the brain, the pancreas, and muscle. (2) Cardiovascular and respiratory control systems in adults and neonates in terms of feedback control systems, mechanisms, and clinical disorders.', null, 4, '{"operator": "AND", "items": ["BCH210H1", "PSL300H1", "PSL301H1"]}'::jsonb),
    ('PSL305H1', 'Topics in Cellular, Molecular and Organismic Physiology II', '32L/16T', 'Focus on two topics: the brain and pregnancy. Delve into the physiology of the central nervous system along with associated diseases as model systems. Learn about fetal and maternal adaptations during pregnancy and the consequences of maladaptation. The course is designed for Physiology Specialist students, although permission is granted to other students upon Departmental approval.', 'PSL303Y1', 4, '{"operator": "AND", "items": ["BCH210H1", "PSL300H1", "PSL301H1"]}'::jsonb),
    ('PSL310H1', 'Clinical Reasoning', '24L/12S', 'Improved clinical reasoning will reduce the current likelihood that most people will suffer at least one medical diagnostic error, errors that contribute to ~10% of patient deaths. Learn to apply strategies of critical thinking and principles of physiology to solve clinical cases. Shadow a healthcare professional. Not eligible for CR/NCR option.', 'HMB322H1', 4, '{"operator": "AND", "items": ["BCH210H1", {"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, "PSL300H1", "PSL372H1", "PSL301H1"]}'::jsonb),
    ('PSL350H1', 'Mammalian Molecular Biology', '18L/12T/6S', 'Extend molecular biology concepts to current scientific literature in mammalian physiology. Apply these principles to disease and complex behaviours. Discuss bioethical issues raised by these techniques and their application. Benefit from three weeks in small group seminars lead by research professors focusing on current advances in mammalian molecular biology.', 'BCH311H1/ BIO349H1/ CSB349H1/ MGY311Y1', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, "PSL300H1", "BCH210H1"]}'::jsonb),
    ('PSL372H1', 'Mammalian Physiology Laboratory', '12L/36P', 'A laboratory course covering selected topics in physiology. An ancillary fee of $53 will be charged for lab materials.', 'CSB348H1', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO230H1", {"operator": "AND", "items": ["BIO240H1", "BIO241H1"]}, "BIO255H1"]}, {"operator": "OR", "items": ["BCH210H1", "BCH242Y1"]}, "PSL300H1"]}'::jsonb),
    ('PSL374H1', 'Advanced Physiology Laboratory', '12L/36P/12S', 'A problem-based laboratory course focused on the integration and control of organ systems to understand body functions. Enrollment in this course is restricted to students in the Physiology Specialist and Major Programs although permission is granted to students in other programs upon approval by the Department. An ancillary fee of $53 will be charged for lab materials.', 'CSB348H1', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO230H1", {"operator": "AND", "items": ["BIO240H1", "BIO241H1"]}, "BIO255H1"]}, "PSL300H1", "PSL301H1", "PSL372H1"]}'::jsonb),
    ('PSL378H1', 'Field Physiology: Marine Mammal Autopsy', '12L/24T/36P', 'An opportunity to go outside of the traditional university classroom and actively participate in a marine mammal autopsy. Learn the diversity and adaptive nature of marine mammalian physiology/anatomy as it compares to human. The course is 2 weeks (in May), one week of hands-on tissue dissection, and one week of group discussions of the findings and draft report preparation. Not eligible for CR/NCR option. An additional fee is required to help cover the cost of delivery for this course. Please see https://physiology.utoronto.ca/psl378h1f for details.', null, 4, '{"operator": "AND", "items": ["BIO270H1", {"operator": "OR", "items": ["BIO271H1", "PSL201Y1", "PSL280H1", "PSL300H1"]}, "PSL301H1"]}'::jsonb),
    ('PSL379H0', 'Comparative Marine Mammal Physiology in the Field', '24T/36P', 'Hands-on monitoring of physiological measures with live dolphins, manatee and sea lions; field observations and applied learning to a physiology project. Two-weeks at the end of April early May: 1st week is spent at the marine research center in Mexico, 2nd week of wrap-up discussion and integration of data at U of T. Not eligible for CR/NCR option. An additional fee is required to help cover the cost of delivery for the course. See https://physiology.utoronto.ca/psl379h for details.', null, 4, '{"operator": "OR", "items": ["BIO220H1", "BIO230H1", "BIO270H1", "BIO271H1", "CSB343H1", "PSL280H1", "PSL201Y1", "PSL300H1", "PSL301H1", "PSY362H1"]}'::jsonb),
    ('PSL398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PSL399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PSL399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PSL404H1', 'Regenerative Medicine', '24L/12T', 'Regenerative medicine promises to restore body function that has been lost due to disease, damage or age. Students will explore selected molecular, stem cell and tissue engineering developments to better understand how the body normally functions and how cells, tissues, and organs can be repaired or replaced.', null, 4, '{"operator": "AND", "items": ["PSL300H1", "PSL301H1"]}'::jsonb),
    ('PSL420H1', 'Reproduction: Development and Function', '24L', 'This course provides an in-depth review of the development and function of the male and female reproductive systems. Topics include sex determination and differentiation, steroidogenesis, gametogenesis, hormonal control of the reproductive axis, the female ovulatory cycle, fertilization and implantation, infertility and assisted reproduction approaches. Joint undergraduate/graduate course -  PSL420H1/LMP2100H', null, 4, '{"operator": "AND", "items": ["PSL300H1", "PSL301H1"]}'::jsonb),
    ('PSL421H1', 'Pregnancy and Birth: From Implantation to Newborn Life', '24L', 'General overview of the integrated physiological events associated with fetal development, pregnancy and birth. The approach emphasizes physiological processes using insights gained from studies of humans, animals, cells and genes. Where appropriate the clinical consequences of aberrant development are reviewed. Joint undergraduate/graduate course -  PSL421H1/PSL1421H', null, 4, '{"operator": "AND", "items": ["PSL300H1", "PSL301H1"]}'::jsonb),
    ('PSL424H1', 'Cellular and Molecular Basis of Endocrine Disorders', '24S', 'Explore how researchers uncover the molecular and cellular basis of endocrine disorders. Learn about experimental design, state-of-the-art research tools, and data interpretation. Topics include disorders in: hormone regulation, secretion and action; circadian rhythms; and sexual development and reproduction. Each week students engage in class discussion related to research seminars delivered by faculty.', null, 4, '{"operator": "AND", "items": ["PSL300H1", "PSL301H1", {"operator": "OR", "items": ["PSL350H1", "BCH311H1", "CSB349H1", "MGY311Y1"]}]}'::jsonb),
    ('PSL425H1', 'Integrative Metabolism and its Endocrine Regulation', '24L', 'This course integrates the newest findings and experimental approaches from cellular and molecular biology into metabolic function at the tissue, organ and whole body level.', null, 4, '{"operator": "AND", "items": ["BCH210H1", "PSL300H1", "PSL301H1"]}'::jsonb),
    ('PSL432H1', 'Theoretical Physiology', '24L', 'Theoretical treatment of neurophysiology. Mathematical modeling and analysis of neurophysiological systems. Joint undergraduate/graduate course -  PSL432H1/PSL1432H', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT235Y1", "MAT237Y1"]}, {"operator": "OR", "items": ["APM346H1", "MAT244H1"]}]}'::jsonb),
    ('PSL441H1', 'Systems Neuroscience I: Neuroanatomy, Neurophysiology and Higher Cognition', '36L', 'Introduction to systems neuroscience including neuroanatomy, neuroimaging and human neurophysiology (EEG, MEG), neural support for higher cognitive functions (e.g., memory, language), network neuroscience, and computational modeling.', 'PSL440Y1', 4, '{"operator": "AND", "items": ["PSL300H1"]}'::jsonb),
    ('PSL442H1', 'Systems Neuroscience II: Sensory and Motor', '36L', 'In depth study of the sensory and motor systems, including clinical concerns/applications, neuromodulation, and brain-computer interfaces.', 'PSL440Y1', 4, '{"operator": "AND", "items": ["PSL300H1", {"operator": "OR", "items": ["PSL441H1", "HMB320H1"]}]}'::jsonb),
    ('PSL445H1', 'Neuroscience: Cellular and Molecular', '36L', 'Overview of the fundamentals of cellular and molecular aspects of brain function. Course material is updated yearly to reflect the rapid evolution of ideas in Neuroscience. Joint undergraduate/graduate course -  PSL445H1/PSL1445H/JNR1444Y', 'PSL444Y1', 4, '{"operator": "AND", "items": ["PSL300H1", "PSL301H1", "CJH332H1"]}'::jsonb),
    ('PSL446H1', 'Neural Disorders', '36L', 'Explore topics in neurological disorders and treatments to reinforce and expand your knowledge of cellular and molecular neurophysiology. Course material is updated yearly to reflect the rapid evolution of ideas in this area. Joint undergraduate/graduate course -  PSL446H1/PSL1446H/JNR1444Y', 'PSL444Y1', 4, '{"operator": "AND", "items": ["PSL300H1", "PSL301H1", "CJH332H1"]}'::jsonb),
    ('PSL450H1', 'Mechanisms of Neural and Endocrinal Secretion', '24L', 'Exocytosis and other aspects of secretion mainly in neurons and neuroendocrine cells, but also in pancreatic cells. Topics include synapse anatomy and physiology, synaptic plasma membrane and vesicle proteins, membrane fusion, genetic tools, endocrine secretion, plasticity in neurotransmitter release, diseases arising from secretion defects.', null, 4, '{"operator": "AND", "items": ["BCH210H1", {"operator": "OR", "items": ["PSL300H1", {"operator": "AND", "items": ["BIO240H1", "BIO241H1"]}]}, {"operator": "OR", "items": ["PSL350H1", "CSB349H1", "BCH311H1", "MGY311Y1"]}]}'::jsonb),
    ('PSL452H1', 'Membrane Physiology', '24L', 'Biophysics and molecular biology of ion channels. Topics include equivalent circuits for cells, molecular structure of voltage-gated channels, distribution of channels, relationship between single-channel and whole-cell recording, and regulation of channel function by voltage, phosphorylation, G-proteins and metabolites. Joint undergraduate/graduate course -  PSL452H1/PSL1452H', null, 4, '{"operator": "AND", "items": ["PSL300H1", "PSL301H1"]}'::jsonb),
    ('PSL462H1', 'Molecular Aspects of Cardiovascular Function', '36L', 'Heart anatomy and development, ion channels and contractile proteins involved in cardiac and smooth muscle contraction are studied. Emphasis is on regulation of electrical and contractile function of kinases, metabolism, volume and ions. Joint undergraduate/graduate course -  PSL462H1/PSL1462H', null, 4, '{"operator": "AND", "items": ["PSL300H1", "PSL301H1"]}'::jsonb),
    ('PSL470H1', 'Cardiovascular Physiology', '24L', 'Development of the cardiovascular system from conception to adulthood with particular emphasis on maturational changes, age-related differences and developmental problems from cellular/molecular to whole organ/system.', null, 4, '{"operator": "AND", "items": ["PSL300H1", "PSL301H1"]}'::jsonb),
    ('PSL472H1', 'Sleep Physiology and Chronobiology', '24L', 'This course covers the physiology underlying sleep and circadian rhythms, and their impact on important physiological processes and health. The integrative nature of the basic physiological processes is emphasized via discussions and clinical presentations. Overall, the aim is to present the full spectrum of integrative physiology from molecules and cells to understanding the sick patient.', null, 4, '{"operator": "AND", "items": ["PSL300H1", "PSL301H1"]}'::jsonb),
    ('PSL480H1', 'Diving Physiology of Marine Mammals', '24L/6T', 'This course compares and contrasts the physiological and anatomical adaptations exhibited by the different species of marine mammals in relationship to humans, with respect to diving.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["BIO270H1", "BIO271H1"]}, "PSL201Y1", "PSL300H1"]}, "PSL301H1", "PSL280H1"]}'::jsonb),
    ('PSL496Y1', 'Translational Physiology Research Project', '144P', 'Engage in supervised original science research, either basic or clinical, combined with a healthcare placement. Develop skills in defining scientific questions, designing experiments, analyzing data, and communicating your results. Gain insight into the power of translational bench-to-bedside research. Discover your interest in becoming a science researcher. Not eligible for CR/NCR option.', 'PSL497H1', 4, '{"operator": "AND", "items": ["PSL300H1", "PSL301H1", "PSL310H1", "PSL372H1"]}'::jsonb),
    ('PSL497H1', 'Translational Physiology Research Project', '72P', 'Engage in original science research, either basic or clinical, combined with a healthcare placement. Develop skills in defining scientific questions, designing experiments, analyzing data, and communicating your results. Gain insight into the power of translational "bench-to-bedside" research. Discover your interest in becoming a science researcher. Not eligible for CR/NCR option.', 'PSL496Y1', 4, '{"operator": "AND", "items": ["PSL300H1", "PSL301H1", "PSL310H1", "PSL372H1"]}'::jsonb),
    ('PSL498Y1', 'Project in Physiology', '144P', 'Laboratory research project with reading assignments leading to a final report. By special arrangement with a Physiology staff member after admission to course.  PSL498Y1 is recommended for students applying to the Physiology graduate program. Enrollment in this course is restricted to students in the Physiology Specialist and Major Programs, although permission is granted to students in other programs upon approval by the Department. Not eligible for CR/NCR option.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["PSL304H1", "PSL305H1"]}, "PSL303Y1"]}, "PSL372H1", "PSL374H1"]}'::jsonb),
    ('PSL499H1', 'Project in Physiology', '72P', 'Laboratory research project with reading assignments leading to a final report. By special arrangement with a Physiology staff member after admission to course.  PSL499H1 is recommended for students applying to the Physiology graduate program. Enrollment in this course is restricted to students in the Physiology Specialist and Major Programs, although permission is granted to students in other programs upon approval by the Department. Not eligible for CR/NCR option.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["PSL304H1", "PSL305H1"]}, "PSL303Y1"]}, "PSL372H1", "PSL374H1"]}'::jsonb),
    ('PSY100H1', 'Introductory Psychology', '36L', 'A brief introductory survey of psychology as both a biological and social science. Topics will include behavioural neuroscience, learning, perceptual, motivational, cognitive, developmental, personality, abnormal, and social psychology.', 'PSY100Y5/ ( PSYA01H3 and  PSYA02H3)', 2, null::jsonb),
    ('PSY194H1', 'The Psychology of Student Success', '24S', 'University life presents students with all sorts of challenges as well as amazing opportunities for learning and growth. While there are many different ways to define a “successful student”, the goal of this seminar is for everyone to develop the knowledge, skills, and mindset needed to make the most of out of the university experience. Students will discover what research in psychological science has to say about facing and overcoming common academic, intrapersonal, and interpersonal challenges, as we cover topics including deliberate practice, imposter syndrome, and belongingness. Students will also learn evidence-based strategies for better managing their attention, energy, and emotions so that they may thrive (rather than just survive) in university. In addition to learning about psychology, students will develop useful skills in scientific literacy, critical thinking, self-reflection, written and oral communication, and teamwork. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('PSY195H1', 'The Science of Babies and Children', '24S', 'This course will use an interdisciplinary perspective to explore how the infant mind emerges and grows. Topics could include how brain plasticity influences “critical” or “sensitive” periods for learning, or how studying infants'' perception, cognition and behaviour can offer us critical insights into long-standing philosophical questions. Note that specific content will depend on the instructor and will be posted on the Department of Psychology''s Undergraduate Course Information webpage. During the course, students will (1) engage in lively discussion and present their perspectives; (2) use exploratory writing to develop arguments and their understanding of subject matter; and (3) begin to read and summarize scientific research papers in Developmental Psychology. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('PSY197H1', 'Rethinking the Human Mind', '24S', 'This course will use an interdisciplinary perspective to explore the quirks, achievements, and puzzles of the human mind. Topics could include how technology and tools extend our minds, or the light that our ability (and inability) to reason sheds on human nature. Note that specific content will depend on the instructor and will be posted on the Department of Psychology''s Undergraduate Course Information webpage. During the course, students will: (1) engage in lively discussion and present their perspectives; and (2) use exploratory writing to develop arguments and their understanding of the subject matter. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('PSY198H1', 'The Psychology of Magic', '24S', 'Magicians entertain us with their tricks. What appears as “Magic” is based on fundamental aspects of human psychology: visual and auditory perception, decision making, logic, memory, and verbal abilities. In this class, we will consider and discuss the psychological basis of magic tricks and use magic to explore aspects of psychology. The class will require reading of scientific articles and book chapters as well as watching and analyzing magical tricks. The only prerequisite is a curious and critical mind. The course puts great emphasis on writing and on starting to read primary scientific literature. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('PSY199H1', 'Psychology and History of Drug Use', '24S', 'This seminar will examine the historical and contemporary use of drugs. Students will be introduced to the general psychological and neuroscientific mechanisms by which drugs affect human behavior, and explore highlights of current research on drug effects in animals and humans. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('PSY201H1', 'Statistics I', '36L', 'Fundamentals of descriptive and inferential statistics, including population and sampling distributions, simple association, probability, estimation, and hypothesis testing.', 'ECO220Y1/  EEB225H1/  GGR270H1/  IRW220H1/  POL222H1/  SOC202H1/  STA220H1/  STA238H1/  STA248H1/  STA288H1/  ECO220Y5/  PSY201H5/  STA215H5/  STA220H5/  PSYB07H3/  STAB22H3/  STAB23H3/  STAB57H3', 5, '{"operator": "OR", "items": ["PSY100H1", "PSY100Y5", {"operator": "AND", "items": ["PSYA01H3", "PSYA02H3"]}, "COG250Y1"]}'::jsonb),
    ('PSY202H1', 'Statistics II', '36L', 'Fundamentals of statistical analysis of experimental and observational data including linear models, the analysis of variance, a priori contrasts, post-hoc tests, power analysis and effect size calculations.', 'ECO220Y1/  SOC252H1/  STA221H1/  PSY202H5/  ECO220Y5/  STA221H5/  PSYC08H3/  STAB27H3/  STAC32H3', 5, '{"operator": "OR", "items": ["PSY201H1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3"]}'::jsonb),
    ('PSY203H1', 'Psychological Research', '36P', 'This course provides an introduction to conceiving, designing, and conducting research in psychology. It prepares students to be both consumers and producers of scientific research, and also addresses basic issues related to the work of psychological scientists such as theory development, research ethics, and scientific writing. Students in this course will gain insight into the scientific process as a whole – its advantages, difficulties, and limitations. As such, students will be able to better evaluate the knowledge that psychological science can provide, and integrate that knowledge into a broader worldview.', 'PSYB70H3', 2, '{"operator": "OR", "items": ["PSY100H1", "PSY100Y5", {"operator": "AND", "items": ["PSYA01H3", "PSYA02H3"]}, "COG250Y1"]}'::jsonb),
    ('PSY204H1', 'Psychology Careers and Applications', '36L', 'Psychology has been identified as a hub science, a discipline whose research influences the work of scientists in many other fields. This course will provide students with a broad introduction to the application of the psychological sciences across various clinical, academic, and industry contexts. Students will gain valuable insight into the broad range of careers that are relevant to psychology, while also investigating barriers to rigorous application of psychological science in applied settings. Students will also learn how the skills and knowledge gained in an undergraduate psychology program can be applied to a broad range of careers and fields/sectors. Students will gain significant exposure to career and education planning considerations within the psychological sciences and will participate in at least one experiential career exploration activity. Enrolment in this course is completely restricted to current PSY program students.', null, 3, '{"operator": "OR", "items": ["PSY100H1", "PSY100Y5", {"operator": "AND", "items": ["PSYA01H3", "PSYA02H3"]}]}'::jsonb),
    ('PSY210H1', 'Introduction to Developmental Psychology', '36L', 'The developmental approach to the study of behaviour with a focus on infancy through childhood.  Topics include sensorimotor skills, cognition, socialization, personality, and emotional behaviour.', 'PSY210H5/  PSYB20H3', 2, '{"operator": "OR", "items": ["PSY100H1", "PSY100Y5", "PSYA02H3", "COG250Y1"]}'::jsonb),
    ('PSY220H1', 'Introduction to Social Psychology', '36L', 'Contemporary areas of research in social psychology: social perception, attitudes, inter-personal relations, and group processes.', 'PSY220H5/ PSYB10H3/ SOC213H1', 2, '{"operator": "OR", "items": ["PSY100H1", "PSY100Y5", "PSYA02H3", "COG250Y1"]}'::jsonb),
    ('PSY230H1', 'Personality and Its Transformations', '36L', 'Theory and research in personality structure and dynamics: the interaction of cultural and biological factors in the development and expression of individual differences.', 'PSY230H5/  PSYB30H3', 2, '{"operator": "OR", "items": ["PSY100H1", "PSY100Y5", "PSYA02H3", "COG250Y1"]}'::jsonb),
    ('PSY240H1', 'Introduction to Psychopathology and Clinical Science', '36L', 'A critical survey of concepts, theories, and the state of research in the area of psychopathology and therapeutic methods.', 'PSY240H5/  PSYB32H3', 2, '{"operator": "OR", "items": ["PSY100H1", "PSY100Y5", "PSYA02H3", "COG250Y1"]}'::jsonb),
    ('PSY260H1', 'Introduction to Learning and Plasticity', '36L', 'Concepts, theories, and applications of classical and contemporary learning theories, including classical and operant conditioning. Current theories of the physiological and anatomical basis of learning and memory, including synaptic plasticity, the role of the hippocampus, amygdala, frontal cortex and other brain regions. Theories will be related to a practical understanding and applications such as drug addiction, phobias and other disorders.', 'PSYB38H3', 4, '{"operator": "OR", "items": ["PSY100H1", "PSY100Y5", "PSYA01H3", "COG250Y1"]}'::jsonb),
    ('PSY270H1', 'Introduction to Cognitive Psychology', '36L', 'An introduction to research and theory on the neural and cognitive architecture of attention, memory, language, thinking and reasoning.', 'PSY270H5/ PSYB57H3', 2, '{"operator": "OR", "items": ["PSY100H1", "PSY100Y5", "PSYA01H3", "COG250Y1"]}'::jsonb),
    ('PSY280H1', 'Introduction to Sensation and Perception', '36L', 'An introduction to the physiological and psychological basis of perception across the different sensory modalities in humans and lower animals, with an emphasis on vision. Exploring visual perception such as shape and objects, scenes, colour, space, and motion as well as auditory perception of simple and complex sounds, and location. Further topics may include touch, including perception of temperature, pain and body posture, the chemical senses, and cross-modal influences of the senses on one another. In-class demonstrations may supplement the lectures.', 'PSY280H5/  PSYB51H3', 4, '{"operator": "OR", "items": ["PSY100H1", "PSY100Y5", "PSYA01H3", "COG250Y1"]}'::jsonb),
    ('PSY290H1', 'Behavioural Neuroscience', '36L', 'Provides students with a solid background in the biological basis of behaviour. Animal and human research topics will include functional neuroanatomy and neural signalling. Further topics may include sensory and motor control, motivational systems, hormones, and emotions, among other topics.', 'HMB200H1/  PSY290H5/  PSYB64H3', 4, '{"operator": "OR", "items": ["PSY100H1", "PSY100Y5", "PSYA01H3", "COG250Y1"]}'::jsonb),
    ('PSY299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PSY299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PSY305H1', 'The Treatment of Psychological Data', '36L', 'This course provides a practical yet intensive introduction to the research pipeline, with a focus on research data management and advanced statistical analysis and inference. Students learn how to find, organize, and analyze data sets in a transparent and reproducible way. Students also learn more about statistical inference, focusing on how the design and analysis of data shape the interpretation of results.', 'EEB313H1', 5, '{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}'::jsonb),
    ('PSY306Y0', 'Special Topics in Psychology Abroad', '48L', 'Special Topics in Psychology for the Summer Abroad Program. Course topics, content, and instructor may vary from one year to another. More information about Psychology and other course offerings can be obtained from the Summer Abroad website at https://summerabroad.utoronto.ca/. For students in any Psychology and/or Social Science Major or Specialist.', null, null, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}]}'::jsonb),
    ('PSY307H1', 'Special Topics in Psychology', '36L', 'A lecture course providing in-depth examination of specific topics/themes relating to Psychology. Content in any given year depends on instructor. Priority is given to PSY Major program students during the first enrolment period.', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY100H1", "PSY100Y5", {"operator": "AND", "items": ["PSYA01H3", "PSYA02H3"]}]}, {"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"credits": 0.5, "department": "PSY"}]}'::jsonb),
    ('PSY308H1', 'Special Topics in Psychology', '36L', 'A lecture course providing in-depth examination of specific topics/themes relating to Psychology. Content in any given year depends on instructor. Priority is given to PSY Major program students during the first enrolment period.', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY100H1", "PSY100Y5", {"operator": "AND", "items": ["PSYA01H3", "PSYA02H3"]}]}, {"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"credits": 0.5, "department": "PSY"}]}'::jsonb),
    ('PSY309H1', 'Research Specialization: Practicum', '36P', 'Research Specialists learn about the research opportunities within our department, and develop skills in the areas of critical thinking, writing, and oral presentation. Students also conduct a pre-thesis research project under the supervision of a faculty member. Students should ideally complete a PSY lab course (PSY3*9H1) during the same year this course is taken; however, permission to take the lab course in subsequent years may be granted in consultation with the Undergraduate Administrator (psy.undergrad@utoronto.ca). Enrolment is restricted to PSY Research Specialists.', 'PSY309H5', null, '{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}'::jsonb),
    ('PSY311H1', 'Social Development', '36L', 'Theory and research in social attachment, aggression, morality, imitation and identification, altruism, and parental discipline, with discussion of methodological issues.', 'PSY311H5/  PSYC21H3/  PSYC27H3/  PSYD22H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY210H1", "PSY210H5", "PSYB20H3"]}]}'::jsonb),
    ('PSY312H1', 'Cognitive Development', '36L', 'This course examines the developmental of knowledge in fundamental domains such as spatial perception, navigation, object perception, number, language, and theory of mind. Emphasis is on current experimental findings and how they address centuries-old debates surrounding the origin and nature of human knowledge.', 'PSY312H5', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY210H1", "PSY210H5", "PSYB20H3"]}]}'::jsonb),
    ('PSY313H1', 'Psychology of Aging', '36L', 'Age changes in sensory and perceptual processes, motor skill, learning, memory, and personality. Theory, methodological problems, social, cultural, and environmental influences that shape behaviour and attitudes towards and among the elderly.', 'PSY313H5/  PSYC21H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY210H1", "PSY210H5", "PSYB20H3"]}]}'::jsonb),
    ('PSY316H1', 'Perceptual Development', '36L', 'The course examines human perceptual development during the first 2-3 years of life. Vision and audition are emphasized. Some topics are: pattern and colour vision, depth perception, infant speech perception.', 'PSY316H5/  PSYC22H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY280H1", "PSY280H5", "PSYB51H3"]}]}'::jsonb),
    ('PSY319H1', 'Developmental Laboratory', '36P', 'This laboratory course provides an overview of developmental psychology methods. The class conducts an original research project, including design, data collection, data analysis, and a written report. Course capacity is limited to 15 students and priority is given to PSY Specialists and Research Specialists during the first enrolment period.', 'PSY319H5/  PSYC72H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}, {"operator": "OR", "items": ["PSY210H1", "PSY210H5", "PSYB20H3"]}]}'::jsonb),
    ('PSY320H1', 'Social Psychology: Attitudes', '36L', 'An intensive study of social attitude development, description, measurement, modification, and organization.', 'PSY320H5', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY220H1", "PSY220H5", "PSYB10H3", "SOC213H1"]}]}'::jsonb),
    ('PSY321H1', 'Cross-Cultural Psychology', '36L', 'One of the hallmarks of human behaviour is its diversity. Some of the ways in which we differ are thought to be relatively idiosyncratic (e.g., specific aspects of personality), whereas others are fairly systematic. Cultural psychology is one area of research in human behaviour that examines systematic differences resulting from individuals'' cultural backgrounds. This course will introduce you to the consideration of cultural variation in the study of human thought and behaviour.', 'PSY321H5/  PSYC14H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY220H1", "PSY220H5", "PSYB10H3", "SOC213H1"]}]}'::jsonb),
    ('PSY322H1', 'Intergroup Relations', '36L', 'An in-depth examination of theories and research in intergroup relations; focuses on stereotyping, prejudice, discrimination, and stigma.', 'PSYC12H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY220H1", "PSY220H5", "PSYB10H3", "SOC213H1"]}]}'::jsonb),
    ('PSY323H1', 'Sex Roles and Behaviour', '36L', 'The effect of sex-role expectations on how men and women behave and perceive the world: theories of sex-role development, physiological and cultural determinants of sex differences, power relationships between men and women.', 'PSY317H5/  PSYD18H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY210H1", "PSY210H5", "PSYB20H3", "PSY220H1", "PSY220H5", "PSYB10H3", "SOC213H1", "PSY230H1", "PSY230H5", "PSYB30H3", "PSY240H1", "PSY240H5", "PSYB32H3"]}]}'::jsonb),
    ('PSY324H1', 'Moral Thought and Behaviour', '36L', 'Moral values vary considerably across individuals, groups, countries, and cultures. What explains the emergence of these differential moral systems? What psychological processes are involved in moral decisions and actions? How might insights from psychological research shed light on contemporary, ''hot-button'' moral issues? How are moral decisions similar to – and different from – other types of everyday decisions? What is the role of emotion in moral decision making? As an introduction to the field of moral psychology, this 300-level course will cover research from a range of sub-disciplines within psychology including social-personality psychology, cognitive neuroscience, and developmental psychology. In addition, students will gain exposure to related material in other fields including philosophy, ethology, and economics. Students will gain a firm understanding of the key debates and issues in the study of the moral mind and will gain skills in critical thinking and writing.', 'PSYD14H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY220H1", "PSY220H5", "PSYB10H3", "SOC213H1"]}]}'::jsonb),
    ('PSY326H1', 'Social Cognition', '36L', 'An examination of theory and research on how we make sense of ourselves and our social world. Topics covered include the self, decision-making, attitudes, attribution processes and impression formation, and social categorization.', 'PSYC13H3/  PSYD15H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY220H1", "PSY220H5", "PSYB10H3", "SOC213H1"]}]}'::jsonb),
    ('PSY328H1', 'Psychology and the Law', '36L', 'This course deals with psychological issues in the law, with particular reference to criminal law. It focuses mainly on research that has been done on pretrial publicity, eyewitness testimony, rules of evidence, and other factors that might affect jury decisions.', 'PSY328H5/  PSYC39H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY220H1", "PSY220H5", "PSYB10H3", "SOC213H1"]}]}'::jsonb),
    ('PSY329H1', 'Social Psychology Laboratory', '36P', 'This laboratory course illustrates major methodologies within social psychology, such as attitude measurement, observation of small groups, and experiments. Course capacity is limited to 15 students and priority is given to PSY Specialists and Research Specialists during the first enrolment period.', 'PSY329H5/  PSYC71H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}, {"operator": "OR", "items": ["PSY220H1", "PSY220H5", "PSYB10H3", "SOC213H1"]}]}'::jsonb),
    ('PSY330H1', 'Psychological Measurement', '36L', 'This course focuses on the development and evaluation of psychological measures, including the measurement of knowledge, abilities, attitudes, and personality traits. We will discuss theoretical and methodological issues in psychological measurement, covering important concepts such as reliability and validity and how these affect the interpretation of test scores and research findings. There will be some discussion of the application of psychological measures to various settings and the ethics of psychological assessment.', 'PSY330H5/  PSYC37H3', null, '{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}'::jsonb),
    ('PSY331H1', 'Social Psychology of Emotion', '36L', 'An in-depth review of the role of emotion in human psychology, with an emphasis on the links between emotion and cognition. Topics include theories of emotion, emotion regulation, emotional expression, and emotional experience, the role of emotion in decision-making, and the relationships between emotion, motivation and behaviour.', 'PSY331H5/  PSYC18H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY220H1", "PSY220H5", "PSYB10H3", "SOC213H1"]}]}'::jsonb),
    ('PSY332H1', 'Organizational Behaviour', '36L', 'An analysis of the individual, group, and institutional structures and processes that influence behaviour within organizations. Topics may include motivation, leadership, communication, group processes and teamwork, and organizational culture.', 'IRE260H1/  RSM260H1', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY220H1", "PSY220H5", "PSYB10H3", "SOC213H1", "PSY230H1", "PSY230H5", "PSYB30H3"]}]}'::jsonb),
    ('PSY333H1', 'Health Psychology', '36L', 'This course examines research evidence concerning the impact of psychological factors on physical health and illness.', 'PSY333H5', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY230H1", "PSY230H5", "PSYB30H3", "PSY240H1", "PSY240H5", "PSYB32H3"]}]}'::jsonb),
    ('PSY336H1', 'Positive Psychology', '36L', 'A review of the field of positive psychology, which is the study of happiness and fulfillment. Topics include personal growth, meaning, hedonic and eudaimonic approaches to well-being, gratitude, awe, flow states, mindfulness and meditation.', 'PSY324H5/  PSYC34H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY220H1", "PSY220H5", "PSYB10H3", "SOC213H1", "PSY230H1", "PSY230H5", "PSYB30H3", "PSY240H1", "PSY240H5", "PSYB32H3"]}]}'::jsonb),
    ('PSY337H1', 'Advanced Personality Psychology', '36L', 'This course covers major topics in personality psychology including prominent theories and current research in the area. Theoretical frameworks are integrated with specific applications in primary sources. Specific topics may include personality structure, personality development, psychodynamic approaches, genetic methodology, and emotion regulation.', 'PSYC30H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY230H1", "PSY230H5", "PSYB30H3", "PSY240H1", "PSY240H5", "PSYB32H3"]}]}'::jsonb),
    ('PSY339H1', 'Individual Differences Laboratory', '36P', 'This laboratory course will introduce research methods and statistical techniques involved in individual differences research. You will learn by doing, with the opportunity to complete an individual research project from start to finish. Course capacity is limited to 15 students and priority is given to PSY Specialists and Research Specialists.', 'PSY329H5', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}, {"operator": "OR", "items": ["PSY220H1", "PSY220H5", "PSYB10H3", "SOC213H1", "PSY230H1", "PSY230H5", "PSYB30H3"]}]}'::jsonb),
    ('PSY341H1', 'Psychopathologies of Childhood', '36L', 'This course focuses on cognitive and neuropsychological aspects of neurodevelopmental and psychiatric disorders in children from clinical and theoretical perspectives.', 'PSY341H5', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY210H1", "PSY210H5", "PSYB20H3", "PSY230H1", "PSY230H5", "PSYB30H3", "PSY240H1", "PSY240H5", "PSYB32H3"]}]}'::jsonb),
    ('PSY342H1', 'Cognition and Psychopathology', '36L', 'Work in psychological disorders has increasingly used the theories and methodologies of cognitive psychology to guide research. This course will examine accounts of clinical disorders informed by cognitive experimental psychology, with emphasis on recent work in affective disorders.', 'PSY340H5', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY230H1", "PSY230H5", "PSYB30H3", "PSY240H1", "PSY240H5", "PSYB32H3", "PSY270H1", "COG250Y1", "PSY270H5", "PSYB57H3"]}]}'::jsonb),
    ('PSY343H1', 'Theories of Psychopathology and Psychotherapy', '36L', 'This course examines various theories of how personality functioning may become impaired and corresponding psychotherapeutic interventions. Emphasis on empirical assessment of personality dysfunction and therapy effectiveness.', 'PSY343H5/  PSYC36H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY230H1", "PSY230H5", "PSYB30H3", "PSY240H1", "PSY240H5", "PSYB32H3"]}]}'::jsonb),
    ('PSY349H1', 'Laboratory in Social Psychological Field Methods', '36P', 'This laboratory class introduces students to field methods in social psychology used to study social processes as they unfold in daily life and public spaces. Students will get hands on experience to collecting, managing, storing, and communicating data collected through observational and longitudinal methods, including data collection in public spaces around Toronto and online. Course capacity is limited to 15 students and priority is given to PSY Specialists and Research Specialists during the first enrolment period.', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}, {"operator": "OR", "items": ["PSY220H1", "PSY220H5", "PSYB10H3", "SOC213H1"]}]}'::jsonb),
    ('PSY359H1', 'Human Neuroimaging Laboratory', '24L/24P', 'Introduction to brain imaging methods used in cognitive, developmental, and social neuroscience. Course projects will cover experimental design, imaging techniques, and data analysis. Course capacity is limited to 30 students and priority is given to PSY Specialists and Research Specialists during the first enrolment period.', 'HMB310H1/  PSY368H5/  PSYC76H3/  PSYD55H3', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}, {"operator": "OR", "items": ["PSY210H1", "PSY210H5", "PSYB20H3", "PSY220H1", "PSY220H5", "PSYB10H3", "SOC213H1", "PSY230H1", "PSY230H5", "PSYB30H3", "PSY240H1", "PSY240H5", "PSYB32H3"]}, {"operator": "OR", "items": ["PSY270H1", "PSY270H5", "PSYB57H3", "COG250Y1", "PSY280H1", "PSY280H5", "PSYB51H3"]}]}'::jsonb),
    ('PSY360H1', 'Associative Learning', '36L', 'Learning allows our experiences to shape what we know, what we can do and how we interact with our environments. This course addresses the fundamental concepts and more important research findings related to contemporary theories of associative learning in animals and humans. It examines the application of such fundamental research to issues such as the neural substrates of behaviour, drug use, and anxiety disorders. It is designed to foster skills in critical thinking, experimental design and reading primary sources in this area.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY260H1", "PSYB38H3"]}]}'::jsonb),
    ('PSY362H1', 'Animal Cognition', '36L', 'The study of memory, representation, concept learning, and other cognitive processes in non-human animals.', 'PSY362H5', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY260H1", "PSYB38H3", {"operator": "AND", "items": [{"operator": "OR", "items": ["PSY270H1", "PSY270H5", "PSYB57H3"]}, {"operator": "OR", "items": ["PSY290H1", "PSY290H5", "PSYB55H3", "PSYB64H3", "HMB200H1", "PSL300H1"]}]}]}]}'::jsonb),
    ('PSY369H1', 'Psychobiology Laboratory', '36P', 'This lab is an introduction to experimental methods in behavioural neuroscience, including neuroanatomical and psychopharmacological methods in rodents. Course projects will cover experimental design, laboratory techniques, data analysis, and scientific writing. Class data will be analyzed using analysis of variance (ANOVA) and related statistical methods, so familiarity with these methods is recommended preparation. Course capacity is limited to 12 students, and priority is given to PSY Specialists and Research Specialists during the first enrolment period.', 'HMB310H1/  PSY369H5', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}, {"operator": "OR", "items": ["PSY290H1", "PSY290H5", "PSYB55H3", "PSYB64H3", "HMB200H1"]}]}'::jsonb),
    ('PSY370H1', 'Thinking and Reasoning', '36L', 'Problem-solving as a model of directed thinking; conceptual behaviour and mental representation; induction, deduction and learning; probabilistic reasoning; creative thinking and complex problem solving.', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY270H1", "PSY270H5", "PSYB57H3", "COG250Y1"]}]}'::jsonb),
    ('PSY371H1', 'Higher Cognitive Processes', '36L', 'This course covers selected topics pertaining to higher cognitive processes including rationality, consciousness, creativity, and human and artificial intelligence.', 'PSY371H5', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY270H1", "PSY270H5", "PSYB57H3", "PSY370H1", "COG250Y1"]}]}'::jsonb),
    ('PSY372H1', 'Human Memory', '36L', 'Current theories and data on human memory: processes involved in encoding, storage, and retrieval.', 'PSY372H5/ PSYC53H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY260H1", "PSYB38H3", "PSY270H1", "PSY270H5", "PSYB57H3", "COG250Y1"]}]}'::jsonb),
    ('PSY378H1', 'Engineering Psychology', '36L', 'The application of our knowledge of human information processing capabilities to improve human-machine systems design in a number of engineering environments including aviation, computer software, human-computer interaction, and nuclear power plants.', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY270H1", "PSY270H5", "PSYB57H3", "COG250Y1", "PSY280H1", "PSY280H5", "PSYB51H3"]}]}'::jsonb),
    ('PSY379H1', 'Human Memory and Learning Laboratory', '36P', 'Examination of issues and methods in human memory research. Students conduct supervised research projects, and read, critique, and write research articles. Course capacity is limited to 15 students and priority is given to PSY Specialists and Research Specialists during the first enrolment period.', 'PSY379H5/ PSYC75H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}, {"operator": "OR", "items": ["PSY260H1", "PSYB38H3", "PSY270H1", "PSY270H5", "PSYB57H3", "COG250Y1"]}]}'::jsonb),
    ('PSY380H1', 'Vision Science', '36L', 'Integrates psychology, neuroscience, and computer science approaches to the study of vision science. Topics include: history and philosophy of vision science, low-level vision, motion perception, spatial vision, perception of objects and scenes, colour perception, attention and consciousness, and multisensory integration. Demonstrations/in-class experiments supplement lectures and readings. Emphasis on reading and writing scientific articles in vision science.', 'PSYC51H3', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY280H1", "PSY280H5", "PSYB51H3", "PSY270H1", "PSY270H5", "PSYB57H3", "COG250Y1", "PSY290H1", "PSY290H5", "PSYB64H3", "HMB200H1", "PSL300H1", "COG341H1"]}]}'::jsonb),
    ('PSY389H1', 'Perception Laboratory', '36P', 'Examination of issues and methods in perception research. Students conduct supervised research projects, and read, critique, and write research articles. Course capacity is limited to 15 students and priority is given to PSY Specialists and Research Specialists during the first enrolment period.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}, {"operator": "OR", "items": ["PSY280H1", "PSY280H5", "PSYB51H3"]}]}'::jsonb),
    ('PSY390H1', 'Behavioural Genetics', '36L', 'An examination of how genes contribute to the production of behaviour, either as structural elements or direct participants in behavioural regulation. Covers molecular genetics, natural selection, and genetic methods followed by specific examples of congenic disorders that affect behaviour and studies of normal behaviours in human and animal models.', 'PSY355H5', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY260H1", "PSYB38H3", "PSY290H1", "PSY290H5", "PSYB64H3", "BIO260H1", "HMB200H1", "HMB265H1", "PSL300H1"]}]}'::jsonb),
    ('PSY395H1', 'Neuroethics', '36L', 'An examination of how developments in neurology and neuroscience can be used to inform ethical and legal issues related to free will, responsibility, competence, education, morality, and empathy in healthy people and in people with confirmed or suspected neurological disorders.', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY260H1", "PSYB38H3", "PSY270H1", "PSY270H5", "PSYB57H3", "COG250Y1", "PSY280H1", "PSY280H5", "PSYB51H3", "PSY290H1", "PSY290H5", "PSYB55H3", "PSYB64H3", "HMB200H1"]}]}'::jsonb),
    ('PSY396H1', 'Neurochemical Basis of Behaviour', '36L', 'The functional relevance of neurotransmitters, with particular emphasis on their role in mediating behaviour.', 'PCL200H1/  PCL476H1/  PSYC62H3', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY260H1", "PSYB38H3", "PSY290H1", "PSY290H5", "PSYB64H3", "HMB200H1", "PSL300H1"]}]}'::jsonb),
    ('PSY397H1', 'Biological Rhythms', '36L', 'Daily, monthly, annual and other rhythms and methods of measuring them. Behavioural and physiological aspects of biological clocks. The importance of rhythms in experimental design, in research on brain function, in affective disorders, and the use animals make of rhythms in migration and other behaviours.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY260H1", "PSYB38H3", "PSY290H1", "PSY290H5", "PSYB64H3", "HMB200H1", "PSL300H1"]}]}'::jsonb),
    ('PSY399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PSY399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PSY400Y1', 'Research Specialization: Thesis', null, 'An individual thesis done under the direction of a faculty member. Lecture and seminar presentations of proposals in the Fall session. Enrolment is restricted to PSY Research Specialists. Not eligible for CR/NCR option.', 'PSY400Y5/  PSYC98Y3', null, '{"operator": "AND", "items": ["PSY309H1", {"operator": "OR", "items": ["PSY319H1", "PSY329H1", "PSY339H1", "PSY349H1", "PSY359H1", "PSY369H1", "PSY379H1", "PSY389H1"]}]}'::jsonb),
    ('PSY402H1', 'Psychology Seminar', '24S', 'Undergraduate students who are given permission to take a seminar at the graduate level offered through the Dept. of Psychology''s Graduate Program will be enrolled into this course code. Permission to take a graduate seminar for undergraduate credit must be obtained through three channels. First, the instructor of the grad course must give the student permission. It is ultimately up to instructor to decide whether the course is appropriate for undergraduate students, as well as if the specific student has the appropriate academic background to succeed in the course. Accordingly, the student may be asked to provide details about their relevant academic and/or research experience to assess their qualifications. Second, the Graduate Administrator (psy.graduate@utoronto.ca) must confirm if there is space in the course after graduate students have enrolled. Finally, the Undergraduate Administrator (psy.undergrad@utoronto.ca) must receive an email from the Graduate Administrator confirming that the student has permission to enrol. The following information must be included in the email: Student name, student number, graduate course code and term (F or S), and the course subtitle. The student will then be enrolled into this undergraduate course code by the Department. It is the student''s responsibility to contact the graduate instructor to initiate this process and to follow-up with both the Graduate and Undergraduate Administrators to ensure their enrolment.', null, null, null::jsonb),
    ('PSY403H1', 'Psychology Seminar', '24S', 'Undergraduate students who are given permission to take a seminar at the graduate level offered through the Dept. of Psychology''s Graduate Program will be enrolled into this course code.  Permission to take a graduate seminar for undergraduate credit must be obtained through three channels. First, the instructor of the grad course must give the student permission. It is ultimately up to instructor to decide whether the course is appropriate for undergraduate students, as well as if the specific student has the appropriate academic background to succeed in the course. Accordingly, the student may be asked to provide details about their relevant academic and/or research experience to assess their qualifications. Second, the Graduate Administrator (psy.graduate@utoronto.ca) must confirm if there is space in the course after graduate students have enrolled. Finally, the Undergraduate Administrator (psy.undergrad@utoronto.ca) must receive an email from the Graduate Administrator confirming that the student has permission to enrol. The following information must be included in the email: Student name, student number, graduate course code and term (F or S), and the course subtitle. The student will then be enrolled into this undergraduate course code by the Department. It is the student''s responsibility to contact the graduate instructor to initiate this process and to follow-up with both the graduate and undergraduate administrators to ensure their enrolment.', null, null, null::jsonb),
    ('PSY404H1', 'Psychology Seminar', '24S', 'Undergraduate students who are given permission to take a seminar at the graduate level offered through the Dept. of Psychology''s Graduate Program will be enrolled into this course code. Permission to take a graduate seminar for undergraduate credit must be obtained through three channels. First, the instructor of the grad course must give the student permission. It is ultimately up to instructor to decide whether the course is appropriate for undergraduate students, as well as if the specific student has the appropriate academic background to succeed in the course. Accordingly, the student may be asked to provide details about their relevant academic and/or research experience to assess their qualifications. Second, the Graduate Administrator (psy.graduate@utoronto.ca) must confirm if there is space in the course after graduate students have enrolled. Finally, the Undergraduate Administrator (psy.undergrad@utoronto.ca) must receive an email from the Graduate Administrator confirming that the student has permission to enrol. The following information must be included in the email: Student name, student number, graduate course code and term (F or S), and the course subtitle. The student will then be enrolled into this undergraduate course code by the Department. It is the student''s responsibility to contact the graduate instructor to initiate this process and to follow-up with both the graduate and undergraduate administrators to ensure their enrolment.', null, null, null::jsonb),
    ('PSY405H1', 'Individual Projects', null, 'A single semester intensive laboratory or applied research project for students who seek hands-on research experience to complement our regular course offerings. Each project culminates in a scholarly paper and oral presentation. Students must secure a faculty supervisor from the Dept. of Psychology and submit a completed application form that includes details about the project before the start of the semester. Application forms are available on the Department''s website (https://psych.utoronto.ca/programs-and-courses/undergraduate-course-information) and must be emailed to the undergraduate office (psy.undergrad@utoronto.ca) by the end of the second week of September for fall projects, or by the end of the second week in January for winter projects. If you''re registering for a summer project, please submit it by the end of the second week in May. This course is open to all students.', null, null, '{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}'::jsonb),
    ('PSY405Y1', 'Individual Projects', null, 'A full academic year intensive laboratory or applied research project for students who seek hands-on research experience to complement our regular course offerings. Each project culminates in a scholarly paper and oral presentation. Students must secure a faculty supervisor from the Dept. of Psychology and submit a completed application form that includes details about the project before the start of the academic year. Application forms are available on the Department''s website (https://psych.utoronto.ca/programs-and-courses/undergraduate-course-information) and must be emailed to the undergraduate office (psy.undergrad@utoronto.ca) by the end of the second week of September. This course is open to all students.', null, null, '{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}'::jsonb),
