    ('PSY407H1', 'Special Topics in Psychology', '36L', 'A lecture course providing in-depth examination of specific topics/themes relating to Psychology. Content in any given year depends on instructor. Priority is given to PSY Major program students during the first enrolment period.', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY100H1", "PSY100Y5", {"operator": "AND", "items": ["PSYA01H3", "PSYA02H3"]}]}, {"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"credits": 0.5, "department": "PSY"}]}'::jsonb),
    ('PSY408H1', 'Special Topics in Psychology', '36L', 'A lecture course providing in-depth examination of specific topics/themes relating to Psychology. Content in any given year depends on instructor. Priority is given to PSY Major program students during the first enrolment period.', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY100H1", "PSY100Y5", {"operator": "AND", "items": ["PSYA01H3", "PSYA02H3"]}]}, {"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"credits": 0.5, "department": "PSY"}]}'::jsonb),
    ('PSY409H1', 'Research Specialization: Theoretical Foundations', '24S', 'Addresses the central theoretical issues that structure contemporary research in each of the major areas of psychology. The aim is to provide an informal overview of the field as a whole. Enrolment is restricted to PSY Research Specialists.', null, 2, '{"operator": "AND", "items": ["PSY309H1", {"operator": "OR", "items": ["PSY319H1", "PSY329H1", "PSY339H1", "PSY349H1", "PSY359H1", "PSY369H1", "PSY379H1", "PSY389H1"]}]}'::jsonb),
    ('PSY410H1', 'Developmental Psychology Seminar', '24S', 'Examination in depth of a limited topic within developmental psychology. Content in any given year depends on instructor. Course capacity is limited to 20 students and enrolment priority is given to PSY Specialists and Research Specialists.', 'PSY410H5/  PSYD20H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}, {"operator": "OR", "items": ["PSY210H1", "PSY210H5", "PSYB20H3"]}]}'::jsonb),
    ('PSY414H1', 'Moral Development', '36L', 'A lecture course examining cognitive-developmental, psychoanalytic, sociobiological, behaviouristic and cultural-anthropological approaches to moral development. Issues covered include definitions of morality, the relationship between moral judgement and action, gender differences and commonalities, and the role of culture in moral development.', 'PSYD14H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY210H1", "PSY210H5", "PSYB20H3"]}]}'::jsonb),
    ('PSY417H1', 'Aging and Social Cognition', '36L', 'A lecture course examining theory and research on the social cognitive aspect of aging. Topics range from impression formation and causal attributions to perceptions of control and emotions.', 'PSY415H5/  PSYC13H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY210H1", "PSY210H5", "PSYB20H3"]}]}'::jsonb),
    ('PSY420H1', 'Social Psychology Seminar', '24S', 'Examination in depth of a limited topic within social psychology. Content in any given year depends on instructor. Course capacity is limited to 20 students and enrolment priority is given to PSY Specialists and Research Specialists.', 'PSY420H5/  PSYD15H3/  PSYD16H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}, {"operator": "OR", "items": ["PSY220H1", "PSY220H5", "PSYB10H3", "SOC213H1"]}]}'::jsonb),
    ('PSY421H1', 'Person Perception', '36L', 'This lecture course discusses how we perceive, categorize, and form impressions of other people, relying on readings from primary sources in the scientific literature.', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY220H1", "PSY220H5", "PSYB10H3", "SOC213H1"]}, {"operator": "OR", "items": ["PSY270H1", "PSY270H5", "PSYB57H3", "COG250Y1", "PSY280H1", "PSY280H5", "PSYB51H3"]}]}'::jsonb),
    ('PSY422H1', 'Community Psychology & Advocacy', '24L', 'This course is designed for students who are eager to apply their knowledge of psychological science to social problems. Students will be introduced to the fundamentals of community psychology while also examining how social psychological theory and research can be applied to understand and address issues that affect communities. This course will help students develop the skills and confidence necessary to advocate successfully on public interest issues relevant to psychology. Students will also work in partners/teams with a community advocacy group to collaboratively address a specific problem or need of the organization. Through a guided process of practice and reflection, students will increase their self-efficacy and come to recognize their ability to use their psychological knowledge and skills to make change in the world. Classroom discussions will integrate community experiences with lecture material. Enrolment is by application (see psychology department website or contact the department for more information at psy.undergrad@utoronto.ca). Not eligible for CR/NCR option.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3", "SOC204H1", "POL352H1", "GGR271H1"]}, {"operator": "OR", "items": ["PSY220H1", "PSY220H5", "PSYB10H3", "SOC213H1"]}, {"operator": "OR", "items": ["PSY320H1", "PSY320H5", "PSY321H1", "PSY321H5", "PSYC14H3", "PSY322H1", "PSYC12H3", "PSY333H1", "PSY333H5", "PSY336H1", "PSY324H5"]}]}'::jsonb),
    ('PSY424H1', 'Social Psychology of Interpersonal Relationships', '36L', 'This lecture course focuses on the social psychology of interpersonal relationships between individuals, especially romantic or close relationships and friendships. It surveys what social psychologists have learned about the development, maintenance, disruption or dissolution of personal relationships, as well as current social psychological theories of interpersonal relationships.', 'PSY327H5/  PSYD11H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY220H1", "PSY220H5", "PSYB10H3", "SOC213H1"]}]}'::jsonb),
    ('PSY425H1', 'Self and Identity', '36L', 'The distinguishing feature of human consciousness is self-consciousness -- our ability to be aware of and interpret ourselves and our experiences. All our higher capabilities as a species rest upon this foundation. Self-consciousness allows us to develop an understanding of who we are as individuals and in relation to others. This lecture course brings together ideas and perspectives from across the social sciences to explore the nature of self-consciousness. The institutional relations and cultural practices that give shape to contemporary forms of identity and self-experience are also examined.', 'PSY325H5', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY220H1", "PSY220H5", "PSYB10H3", "SOC213H1"]}]}'::jsonb),
    ('PSY426H1', 'Motivational Theories in Social Psychology', '36L', 'With intensive reading and discussion of ''classic'' and contemporary articles, this advanced lecture course in social psychology focuses on the central issues, methods, and findings in the study of motivation. Topics include self-regulation, achievement, and reward/punishment.', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY220H1", "PSY220H5", "PSYB10H3", "SOC213H1"]}]}'::jsonb),
    ('PSY427H1', 'Media Psychology', '36L', 'This course in critical media literacy examines how we come to understand ourselves and our world, and learn to feel, evaluate, and act, through the simulative mediation of information and communication technologies. The aim is to provide students with a deeper understanding of the dynamic symbolic environment that surrounds them and in which they participate as both audience and producer. The approach is multidisciplinary, drawing not only from psychology but a broad range of influential perspectives in the social sciences and humanities. The topics explored reveal how developments in the world of media are central to understanding changing forms of public and private life in the 21st century.', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY220H1", "PSY220H5", "PSYB10H3", "SOC213H1"]}]}'::jsonb),
    ('PSY428H1', 'Critical Psychology', '36L', 'This course examines the place of psychology in broader society and culture. What are the consequences of our research and professional practices for how we understand and govern ourselves and others? What is the basis and extent of our authority and power to describe, define, and explain human behaviour and experience? How do our values direct our activities and interpretations as psychologists? How can we critically evaluate the assumptions, commitments, and achievements of our discipline in relation to real or imagined alternatives?', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY220H1", "PSY220H5", "PSYB10H3", "SOC213H1"]}]}'::jsonb),
    ('PSY430H1', 'Personality Seminar', '24S', 'Examination in depth of a limited topic within the area of personality. Content in any given year depends on instructor. Course capacity is limited to 20 students and enrolment priority is given to PSY Specialists and Research Specialists.', 'PSY430H5/  PSYD30H3/  PSYD32H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}, {"operator": "OR", "items": ["PSY230H1", "PSY230H5", "PSYB30H3", "PSY240H1", "PSY240H5", "PSYB32H3"]}]}'::jsonb),
    ('PSY435H1', 'Environmental Psychology', '36L', 'This lecture course explores how psychologists can contribute to finding solutions to today''s pressing environmental challenges. Topics include persuasion, community-based social marketing, social influence, social capital, and the many ways in which the physical environment affects psychological processes. The course takes a multi-scalar approach to the human-environment relationship, covering individual, community, cultural and global levels of scale, through the lens of complex dynamic systems theories.', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY100H1", "PSY100Y5", {"operator": "AND", "items": ["PSYA01H3", "PSYA02H3"]}]}, {"operator": "OR", "items": ["PSY220H1", "PSY220H5", "PSYB10H3", "SOC213H1"]}]}'::jsonb),
    ('PSY440H1', 'Seminar in Psychopathology and Clinical Science', '24S', 'Examination in depth of a limited topic within the field of psychopathology and clinical science. Content in any given year depends on instructor. Course capacity is limited to 20 students and enrolment priority is given to PSY Specialists and Research Specialists.', 'PSY440H5/  PSYD33H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}, {"operator": "OR", "items": ["PSY230H1", "PSY230H5", "PSYB30H3", "PSY240H1", "PSY240H5", "PSYB32H3"]}]}'::jsonb),
    ('PSY450H1', 'History of Psychology', '36L', 'This lecture course discusses the philosophical predecessors and early development of modern psychology, schools of thought, and shifts in areas of theory and research, as well as history and philosophy of science, in general.', 'PSYC01H3/  PSYC85H3 (prior to 2025)', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "PSY"}]}'::jsonb),
    ('PSY455H1', 'Psychological Research Now and Then', '36L', 'This course delves into some of the most influential experiments across psychology subfields by discussing how they were conceived, designed, and conducted. Students will learn how these classic findings shaped theory, how to reinterpret them with the benefit of the current knowledge in the field, as well as how and if their experimental designs can be modified to meet current scientific standards and address still open questions. Students will leave this course equipped to be both critical consumers and producers of scientific research. This course will combine lectures with student presentations.', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}, {"operator": "OR", "items": ["PSY203H1", "PSYB70H3"]}]}'::jsonb),
    ('PSY460H1', 'Seminar in Learning', '24S', 'Examination in depth of a limited topic in human or animal learning. Content in any given year depends on the instructor. Course capacity is limited to 20 students and enrolment priority is given to PSY Specialists and Research Specialists.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}, {"operator": "OR", "items": ["PSY260H1", "PSYB38H3"]}]}'::jsonb),
    ('PSY470H1', 'Seminar in Human Memory', '24S', 'Examination in depth of a limited topic within the area of memory. Content in any given year depends on instructor. Course capacity is limited to 20 students and enrolment priority is given to PSY Specialists and Research Specialists.', 'PSYD50H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}, {"operator": "OR", "items": ["PSY270H1", "PSY270H5", "PSYB57H3", "COG250Y1"]}]}'::jsonb),
    ('PSY471H1', 'Seminar in Cognition', '24S', 'An in-depth examination of current research and selected topics in cognitive psychology. Content in any given year depends on the instructor. Course capacity is limited to 20 students and enrolment priority is given to PSY Specialists and Research Specialists. There may be additional prerequisites based on the seminar topic given.', 'PSY471H5/  PSYD50H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}, {"operator": "OR", "items": ["PSY270H1", "PSY270H5", "PSYB57H3", "COG250Y1"]}]}'::jsonb),
    ('PSY473H1', 'Social Cognitive Neuroscience', '36L', 'Social cognitive neuroscience is an emerging interdisciplinary field that seeks to integrate theories of social psychology and cognitive neuroscience to understand behaviour at three fundamentally interrelated levels of analysis (social, cognitive, and neural). Topics such as self-regulation, cooperation, decision-making, emotion, morality, and prejudice will be examined in this lecture course.', 'PSY353H5/  PSYD17H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY270H1", "PSY270H5", "PSYB57H3", "COG250Y1", "PSY290H1", "PSY290H5", "PSYB64H3", "HMB200H1", "PSL300H1"]}]}'::jsonb),
    ('PSY474H1', 'Computation in Psychology', '36L', 'This lecture course surveys computational perspectives on the mind and brain and introduces computational tools for connecting psychological and neural data to theory. Topics may include neural networks, probabilistic models, pattern recognition, and other techniques applicable to psychological research and general analysis. Basic familiarity with programming is recommended but not required.', null, 5, '{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}'::jsonb),
    ('PSY475H1', 'Attention and Performance', '36L', 'This lecture course discusses a range of topics in visual cognition and human performance. Topics covered may include attention, working memory, spatial cognition, the processing of features and objects, and cognitive motor control in eye and limb movements.', 'PSYC52H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY270H1", "PSY270H5", "PSYB57H3", "COG250Y1", "PSY280H1", "PSY280H5", "PSYB51H3"]}]}'::jsonb),
    ('PSY480H1', 'Seminar in Perception', '24S', 'An in-depth examination of current issues in perception (e.g. perceptual organization, object and face recognition, motion perception). Emphasis is on the psychological perspective, but integrates physiological and computational perspectives as well. Content in any given year depends on instructor. Course capacity is limited to 20 students and enrolment priority is given to PSY Specialists and Research Specialists.', 'PSY480H5/  PSYD51H3', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}, {"operator": "OR", "items": ["PSY280H1", "PSY280H5", "PSYB51H3"]}]}'::jsonb),
    ('PSY490H1', 'Seminar in Behavioural Neuroscience', '24S', 'An in-depth examination of current issues in behavioural neuroscience (e.g. activity of neurons, sensory, motor, motivational, and higher cortical systems.). Content in any given year depends on instructor. Course capacity is limited to 20 students and enrolment priority is given to PSY Specialists and Research Specialists.', 'PSY490H5/  PSYD66H3', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}, {"operator": "OR", "items": ["PSY290H1", "PSY290H5", "PSYB64H3", "HMB200H1", "PSL300H1"]}]}'::jsonb),
    ('PSY492H1', 'Neurobiology of Learning and Memory', '36L', 'Understanding the complexities of how the mammalian nervous system acquires and stores information and how it transforms this information into appropriate behavior is fundamentally important to our understanding of both animal and human behavior. This lecture course explores empirical and theoretical contributions to our understanding of the neural basis of learning and memory.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY260H1", "PSYB38H3", "PSY290H1", "PSY290H5", "PSYB64H3", "HMB200H1", "PSL300H1"]}]}'::jsonb),
    ('PSY493H1', 'Cognitive Neuroscience', '36L', 'This is a capstone lecture course surveying research on how the mind arises from the brain. The first objective of the course is to understand how processes in human brains (ranging from the firing of a single neuron to the dynamics of billions) support cognitive abilities (such as recognizing a face, remembering a birthday from childhood, understanding the words in a spoken lecture, or planning a route home from class). The second objective of the course is to understand the methods of contemporary cognitive neuroscience research, to enable students to read primary literature and to understand ongoing debates.', 'PSY393H5/  PSYB55H3/  PSYC31H3', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY260H1", "PSYB38H3", "PSY270H1", "PSY270H5", "PSYB57H3", "COG250Y1", "PSY290H1", "PSY290H5", "PSYB64H3", "HMB200H1", "PSL300H1"]}]}'::jsonb),
    ('PSY494H1', 'Physiology and Psychology of Emotion', '36L', 'This lecture course discusses the role of brain and body in the expression and experience of emotion in humans considered through the experimental, physiological, theoretical, and clinical literatures.', 'PSYC18H3', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY260H1", "PSYB38H3", "PSY270H1", "PSY270H5", "PSYB57H3", "COG250Y1", "PSY290H1", "PSY290H5", "PSYB64H3", "HMB200H1", "PSL300H1"]}]}'::jsonb),
    ('PSY495H1', 'Sex and the Brain', '36L', 'This lecture course explores the scientific literature underlying the concept that female/male, gay/straight, and transgendered behaviours are based on brain differences. Original scientific papers will be read in close detail for design and interpretation of the experiments. The goal is to gain an understanding of the science and psychology underlying sex/gender, popular conceptions of sex, and the sexual brain. Topics include: the making of sex, hormone action, brain-based sexual behaviours, sex and cognition, and sex and sexuality/gender identification.', 'PSY354H5/  PSY395H5', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY290H1", "PSY290H5", "PSYB64H3", "HMB200H1", "PSL300H1"]}]}'::jsonb),
    ('PSY496H1', 'Cognitive Dysfunction in Neurological Disorders', '36L', 'This lecture course provides an in-depth examination of the cognitive dysfunction found in neurological disorders, including Alzheimer''s Disease, Parkinson''s Disease, and Schizophrenia. The course focuses on how cognitive impairments relate to neuropsychological models of the specific disease (specifically how these models provide insights into the biological mechanisms underlying the cognitive symptoms) and cognition, more broadly.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY201H1", "ECO220Y1", "EEB225H1", "GGR270H1", "IRW220H1", "POL222H1", "SOC202H1", "STA220H1", "STA238H1", "STA248H1", "STA288H1", "ECO220Y5", "PSY201H5", "STA215H5", "STA220H5", "PSYB07H3", "STAB22H3", "STAB23H3", "STAB57H3"]}, {"operator": "OR", "items": ["PSY270H1", "PSY270H5", "PSYB57H3", "COG250Y1", "PSY290H1", "PSY290H5", "PSYB64H3", "HMB200H1", "PSL300H1"]}]}'::jsonb),
    ('PSY497H1', 'Seminar in Biological Timing', '24S', 'This is an advanced seminar course that examines the mechanisms and significance of timing and timekeeping at several levels of organization in living organisms. Topics include the roles of clocks and oscillations in physiology and behaviour, and the importance of timing in sensorimotor integration, memory, decision making, and health. Course capacity is limited to 20 students and enrolment priority is given to PSY Specialists and Research Specialists.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSY202H1", "ECO220Y1", "SOC252H1", "STA221H1", "ECO220Y5", "PSY202H5", "STA221H5", "PSYC08H3", "STAB27H3", "STAC32H3"]}, {"operator": "OR", "items": ["PSY290H1", "PSY290H5", "PSYB64H3", "HMB200H1", "PSL300H1"]}]}'::jsonb),
    ('REN240H1', 'The Renaissance in Italy', '24S', 'An interdisciplinary introduction to the Renaissance in Italy illustrated by a study of the institutions, thought, politics, art, and culture that emerged in the period. Considering key sites of power and creativity like Florence, Venice, Milan, and Rome, this course will examine the dynamic new ways Renaissance Italians understood themselves, others, and the world. Taking into account the full spectrum of Renaissance culture, including constructions of gender and other emerging forms of identity, this course will address broad historical developments and explore the creative works and impact of artists like Michelangelo and Sofonisba Anguissola; architects like Brunelleschi; cultural patrons like the Medici family and Isabella d''Este; and writers like Laura Cereta and Niccolò Machiavelli.', 'REN240Y1', 1, null::jsonb),
    ('REN240Y0', 'The Civilization of Renaissance Europe', null, 'An interdisciplinary introduction to the civilization of the Renaissance illustrated by a study of the institutions, thought, politics, society and culture of both Italy and Northern Europe. Italian city states such as Florence, Urbino and Venice, Papal Rome and despotic Milan are compared with the northern dynastic monarchies of France and England. (Offered as part of the Summer Abroad program)', 'VIC240Y0', 3, null::jsonb),
    ('REN241H1', 'Renaissance Masterworks and Remixes', '24S', 'Focusing on one or more iconic works in literature, music, and the visual arts, this course explores the most celebrated cultural productions of the Renaissance and their subsequent adaptations and appropriations in later and modern popular culture.', 'VIC241H1,  VIC241Y1', 1, null::jsonb),
    ('REN242H1', 'Scientific Worldviews of the Renaissance', '24L', 'An in-depth study of late medieval and early modern scientific worldviews, with a focus on interconnections between natural philosophy, cosmology, theology, astronomy, optics, medicine, natural history, and ethics. Through a consideration of early modern ideas including free will and determinism, the finite and infinite universe, teleology and mechanism, theism and deism, and deduction and intuition, this course investigates some of the period''s key metaphysical and methodological assumptions, and reveals how an evolving scientific understanding informed the Renaissance worldview.', 'VIC242H1,  HPS309H1', 3, null::jsonb),
    ('REN244H1', 'The Renaissance in Europe and the World', '24S', 'An interdisciplinary introduction to the Renaissance as it spread beyond Italy, both as it took root in Northern Europe and made an impact around the globe. This class will examine how the cultural forms of the Renaissance – art, architecture, philosophy, politics, music, drama, and literature – developed through engagement with ancient Roman and Greek models and expanded across Europe (in such places as the Iberian Peninsula, France, England, Scotland, Germany, the Low Countries, and Poland). It will also explore how Renaissance culture shaped and was shaped by interactions between Europeans and peoples in Africa, the Americas, and Asia. Taking into account the contexts of religious conflict, technological change, colonization, gender dynamics, and cross-cultural exchanges brought about by warfare and global networks of trade, this class will use a variety of disciplinary frameworks to examine the Renaissance as an expansive cultural phenomenon.', 'REN240Y1', 1, null::jsonb),
    ('REN245H1', 'Race and Power in the Renaissance', '24S', 'This course explores the relationship between race, imperialism, and culture in the Renaissance world. Students investigate the intellectual frameworks through which early modern Europeans made sense of human diversity, with a focus on the enduring influence of these ideologies in the perception and representation of difference today. Course materials may include such examples as portraits of a Black duke in Renaissance Florence, trial records of falsely accused Jewish men, clothes to disguise oneself as an Ottoman princess, and plays featuring Roma fortune-tellers.', null, 1, null::jsonb),
    ('REN338H1', 'Renaissance in the City', '24S', 'An interdisciplinary course exploring the history, art, architecture, literature, and music of the Renaissance in one or more cities from ca. 1400-1650. The course will investigate how local political and social-historical contexts shape ideas and cultural forms, and so illustrate the process and effects of cross-fertilization in the Renaissance period.', 'VIC338H1', 3, null::jsonb),
    ('REN340H1', 'Travel, Trade, and Difference in the Renaissance World', '24S', 'The Renaissance is when the world became truly global. In this course, we examine how the production of stories, knowledge, and ideas was affected by early globalization. In particular, we explore cross-cultural encounters and exchanges established between early modern Asia, Africa, the Americas, and Europe along networks of trade, imperialistic expansion, and oppression. We will pay particular attention to how early globalization was shaped by power structures and by the intersection of race, class, religion, and gender.', null, 2, null::jsonb),
    ('REN341H1', 'The Self and Society: Women, Men and Children', '24S', 'A study of the changing conception of the human self in the Renaissance, and of its representation by major authors: Erasmus, Rabelais, Marguerite de Navarre, Castiglione, Machiavelli and others.', 'VIC341H1', 2, null::jsonb),
    ('REN342H1', 'Women and Writing in the Renaissance', '24S', 'Focusing on writers from various geographical areas, the course examines a variety of texts by early modern women (for example, treatises, letters, and poetry) so as to explore the female experience in a literate society, with particular attention to how women constructed a gendered identity for themselves against the backdrop of the cultural debates of the time.', 'VIC342H1', 1, null::jsonb),
    ('REN343H1', 'Sex and Gender', '24S', 'An interdisciplinary approach to questions of gender and sexuality in early modern Europe, with special focus on the representations of the sexual drive, the gender roles of men and women, and varieties of sexual experience in the literature and art of the period.', 'VIC343H1,  VIC343Y1', 3, null::jsonb),
    ('REN343Y0', 'Sex and Gender', null, 'An interdisciplinary approach to questions of gender and sexuality in early modern Europe, with special focus on the representations of the sexual drive, the gender roles of men and women, and varieties of sexual experience in the literature and art of the period. (Offered as part of the Summer Abroad program)', 'VIC343Y0', 2, null::jsonb),
    ('REN344H1', 'Renaissance Narrative', '24S', 'Focuses on analysis of short stories and longer prose works including, in English translation: Boccaccio''s stories of love, fortune and human intelligence in the Decameron; Rabelais'' humorous parody of high culture in Gargantua; the tragic tale of Romeo and Juliet; and the adventures of picaresque rogues in Lazarillo de Tormes and Nashe''s Unfortunate Traveler.', 'VIC344H1', 1, null::jsonb),
    ('REN345H1', 'Media and Communications in the Early Modern Era', '24S', 'This course examines the various media (printing press, representational art, music, preaching) and social and political forces (family and political networks, censorship, education, etc.) that conditioned the communication of ideas in early modern society.', 'VIC345H1', 1, null::jsonb),
    ('REN346H1', 'The Idea of the Renaissance', '24S', 'This course examines the changing views of the Renaissance, from the earliest definitions by poets and painters to the different understandings of contemporary historians. We will pay attention to the interests and biases that have informed the idea of the Renaissance as an aesthetic, social, political, gendered, and Eurocentric phenomenon.', 'VIC346H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('REN347H1', 'Studies in Renaissance Performance', '24L', 'Studies in the development of new forms in music, drama and dance in the Renaissance. The course will consist of seminars and lectures, and may incorporate live performances taking place in Toronto in addition to recordings.', 'VIC347H1', 1, null::jsonb),
    ('REN348Y0', 'The Renaissance City', null, 'This course will study four Renaissance Italian urban environments, beginning with the medieval city of Siena followed by the construction of Renaissance urban space in republics, principalities, and papal Rome. Field trips and illustrated lectures will introduce students to Renaissance urban, cultural, and political history. (Offered in Siena only)', 'VIC348Y0', 3, null::jsonb),
    ('REN349H1', 'Special Topics in the Renaissance', '24L/12P', 'Studies in an aspect of the Renaissance based around lectures, seminars, and readings. Content varies by instructor and topics are listed on the Victoria College programs website: https://vic.utoronto.ca/academic-programs/special-topics-courses/ren349h. Not offered every year.', null, null, null::jsonb),
    ('REN349Y1', 'Special Topics in the Renaissance', '48L/24P', 'Studies in an aspect of the Renaissance based around lectures, seminars, and readings. Content varies by instructor and topics are listed on the Victoria College programs website: https://vic.utoronto.ca/academic-programs/special-topics-courses/ren349y. Not offered every year.', null, null, null::jsonb),
    ('REN392H1', 'Renaissance Studies Independent Study', null, 'This course provides an opportunity to design an interdisciplinary course of study, not otherwise available within the Faculty, with the intent of addressing specific topics in Renaissance studies. Written application (detailed proposal, reading list and a letter of support from a Victoria College faculty member who is prepared to supervise) must be submitted for approval on behalf of Victoria College. For application procedures visit the Victoria College website. Not eligible for CR/NCR option.', 'VIC392H1', null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('REN392Y1', 'Renaissance Studies Independent Study', null, 'This course provides an opportunity to design an interdisciplinary course of study, not otherwise available within the Faculty, with the intent of addressing specific topics in Renaissance studies. Written application (detailed proposal, reading list and a letter of support from a Victoria College faculty member who is prepared to supervise) must be submitted for approval on behalf of Victoria College. For application procedures visit the Victoria College website. Not eligible for CR/NCR option.', 'VIC392Y1', null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('REN440H1', 'Florence and the Renaissance', '24L', 'An interdisciplinary seminar on Florence in the 15th and 16th centuries: humanism, culture and society in the republican period, the rise of the Medici, Florentine Neoplatonism, the establishment of the Medici principate, culture, society and religion.', 'VIC440H1,  VIC440Y1', 1, '{"operator": "OR", "items": ["REN240Y1"]}'::jsonb),
    ('REN440Y0', 'Florence and the Renaissance', null, 'An interdisciplinary seminar on Florence in the 15th and 16th centuries: humanism, culture and society in the republican period, the rise of the Medici, Florentine Neoplatonism, the establishment of the Medici principate, culture, society and religion. (Offered as part of the Summer Abroad program)', 'VIC440Y0', 1, '{"operator": "OR", "items": ["REN240Y1"]}'::jsonb),
    ('REN442H1', 'The Renaissance Book', '24L', 'This course explores the intellectual and historical contexts of the Renaissance book and applies a digital humanities approach to its study, focusing on books printed in Western Europe between 1500 and 1700. Through a close examination of early and rare books, students explore three major areas in Renaissance intellectual history: 1) humanist rhetoric, politics, and literature, 2) Reformation studies, and 3) natural history, science, and medicine. Regular guest lectures sponsored by the Centre for Reformation and Renaissance Studies will introduce students to scholars from beyond the UofT; the course also involves experiential learning with digital exhibitions and rare books.', 'VIC442H1;  VIC449H1 (Advanced Seminar in the Renaissance: Exhibiting the Renaissance Book), offered in Winter 2018 and Winter 2019', 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('REN449H1', 'Advanced Seminar in the Renaissance', '12P/24S', 'An in-depth study in an aspect of the Renaissance based around lectures, seminars, and readings. Content in any given year depends on the instructor. Please refer to course website for more information: https://vic.utoronto.ca/academic-programs/special-topics-courses/ren449h', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('REN449Y1', 'Advanced Seminar in the Renaissance', '24P/48S', 'An in-depth study in an aspect of the Renaissance based around lectures, seminars, and readings. Content in any given year depends on the instructor. Please refer to course website for more information: https://vic.utoronto.ca/academic-programs/special-topics-courses/ren449y', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('REN492H1', 'Renaissance Studies Independent Study', null, 'This course provides an opportunity to design an interdisciplinary course of study, not otherwise available within the Faculty, with the intent of addressing specific topics in Renaissance studies. Written application (detailed proposal, reading list and a letter of support from a Victoria College faculty member who is prepared to supervise) must be submitted for approval on behalf of Victoria College. For application procedures visit the Victoria College website. Not eligible for CR/NCR option.', 'VIC492H1', null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('REN492Y1', 'Renaissance Studies Independent Study', null, 'This course provides an opportunity to design an interdisciplinary course of study, not otherwise available within the Faculty, with the intent of addressing specific topics in Renaissance studies. Written application (detailed proposal, reading list and a letter of support from a Victoria College faculty member who is prepared to supervise) must be submitted for approval on behalf of Victoria College. For application procedures visit the Victoria College website. Not eligible for CR/NCR option.', 'VIC492Y1', null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('RLG100H1', 'World Religions', '24L/12T', 'An introduction to the history, philosophy, and practice of the major religions of the world, including Judaism, Christianity, Islam, Hinduism, Buddhism, Confucianism and Taoism.', 'RLG100Y1/  RLG280Y1/ ( RLGA01H3,  RLGA02H3). Note:  RLG101H5 is not equivalent to  RLG100H1.', 3, null::jsonb),
    ('RLG101H1', 'Reason and Religion in the Modern Age', '24L/12T', 'An introduction to critical thinking about religion as it took shape in modern European thought. We examine major thinkers such as Baruch Spinoza, David Hume, Immanuel Kant, Friedrich Nietzsche, Hannah Arendt, and others. Issues covered include freedom of thought, the relationship between religion and politics, belief and truth, rational ethics in relation to religious ethics. We explore how issues addressed by these classical authors remain relevant in today''s world.', null, 2, null::jsonb),
    ('RLG102H1', 'Blood, Sex and Drugs', '24L/12T', 'Religion can be understood as a set of aspirations that manages and moralizes the most intimate matters of social life, including sexual intercourse, bodily fluids, and mind altering substances. This course engages fundamental theories of religion to consider an eclectic set of case studies that troubles a clean divide between purity and danger.', 'RLG101H1 (Introducing Religion: Blood, Sex and Drugs), offered in Winter 2019 and Winter 2020', 2, null::jsonb),
    ('RLG103H1', 'Sports and/as Religion', '24L/12T', 'A first-year course looking at the historical and contemporary relationship between religion and sport. We start with the Ancient Greek Olympics (a funeral ritual) and end with the ever-hopeful gathering of Toronto Maple Leafs fans, Leaf Nation. In between, we look at examples of those sports around the world, in which religion plays a significant role or where sports serves as a religion-like pastime.', null, 2, null::jsonb),
    ('RLG104H1', 'Conspiracies, Social Media, and the Rise of New Religious Movements', '24L/12T', 'Conspiracy theories are nothing new, but in the past few years we have all witnessed the meteoric rise of conspiracies such as QAnon via social media, which have taken on the elements of New Religious Movements. This course examines recent examples of new religious movements that might be thought of as "conspiritualities," that is, conspiracies with strong cult and religious overtones.', null, 2, null::jsonb),
    ('RLG105H1', 'Spirituality, Religion, and the Environment', '24L/12T', 'In diverse cultures and throughout history, people have felt a deep connection to their environments. This search for a feeling of connection, or oneness, with nature has led humans into canyons and caves, up mountains and rock faces, and across deserts and oceans. Sometimes nature spirituality occurs within religious traditions, sometimes outside of them, and sometimes even in opposition to ''religion.'' This course explores the phenomenon of nature spirituality, and the wonder often associated with it. Readings will engage mystics and mountaineers, poets and painters, and farmers and foresters, all exploring the human-nature connection, often in the context of environmental crisis.', 'RLG239H1 (Spirituality and Nature) taken in Winter 2023', 2, null::jsonb),
    ('RLG106H1', 'Happiness', '24L/12T', 'Are you happy? Today happiness is a metric by which a growing number of people assess the quality of their lives, with a range of experts offering innumerable life hacks and opportunities to optimize life. But what does it mean to be happy? And how have people tried to achieve this ever-elusive state? Situated squarely within the study of religion, this course considers how different traditions from around the world and for thousands of years have raised similar questions about happiness—not simply for the sake of reflection but also to do something about it. And their answers have varied: fast, meditate, pray, go to the desert, come together, get high, suffer, renounce God, and/or make lots of money. Readings will include selections from social theory and religious texts as well as a few authors who seem to be (against all odds) kind of happy.', null, 2, null::jsonb),
    ('RLG107H1', '"It''s the End of the World as We Know It"', '24L/12T', 'Throughout history, many religious movements have envisioned the end of the world. This course will explore the ways in which different religious movements have prepared for and expected an end time, from fears, symbols, and rituals to failed prophecies and social violence. By examining traditions such as Jewish and Christian apocalyptic texts through to fears of nuclear apocalypse and zombies, the course seeks to understand the ways in which ancient and modern claims of "the end" reflect the aspirations, anxieties, and religious concerns of communities.', 'RLG101H1 ("It''s the End of the World as we Know It") offered in Fall 2017 and Fall 2018', 2, null::jsonb),
    ('RLG108H1', 'The Question of God', '24L/12T', 'What is God? Who is God? Is Yahweh the same as the Christian God? What about Allah? How do people come to see, hear, or feel God? Belief in God is a core tenet of all monotheistic religions, yet the figure of God is elusive and contested. This course offers an introduction to the study of religion and to how the discipline has engaged with the figure of God. Issues covered include histories of God (including proclamations of the "death of God"); psychological and anthropological views on prayer, divine interventions, and God-human relations; God and empire/colonialism; feminist (and other subversive) re-imaginings of God; and atheism. Regardless of their own belief, students will learn to grapple with an inescapable figure, will learn about lived Islam and Christianity (and to a lesser extent Judaism), and will gain insights into a range of thinking tools offered by the study of religion.', 'RLG239H1 (Special Topics: The Question of God), offered in Fall 2021', 2, null::jsonb),
    ('RLG109H1', 'Heroes and Villains: Religion, Role Models & Cautionary Tales from Marvel and DC', '24L/12T', 'What differentiates a hero from a villain? How are ethical issues addressed in the stories of such characters? Are Batman and Spiderman understood as role models? This course analyzes exemplary narratives from Pop Culture. We will consider examples from the Marvel Cinematic Universe as well as other forms of popular media. Students will compare these popular narratives with those produced by religious communities.', null, 2, null::jsonb),
    ('RLG195H1', 'Alt-Bible: What Could Have Been', '24S', 'Why does our contemporary Bible not include any daughters for Adam and Eve or any stories of Jesus as a young boy? What if Enoch was more prominent than Moses or Thomas more prominent than Paul? "The Bible" that we have is not a single book or a simple collection, but something that has grown over time, been the object of contention and argument, and has sometimes been a common ground across traditions. We examine side-by-side writings that have become canonical and writings that once held authority but have not found widespread canonical status, and strive to understand the processes by which we ended up with "the Bible" we have today. Restricted to first-year students. Not eligible for CR/CNR option.', null, 1, null::jsonb),
    ('RLG196H1', 'Goddess Lessons: Gender, Religion and Pop', '24S', 'Is God a woman? How can we get to heaven without losing a piece of ourselves? What does it mean to follow Lesbian Jesus? Pop music provides us with some important – if often surprising – opportunities to think through deep questions. Increasingly, these questions tie together two of our most powerful human categories: gender and religion. This course will consider the diverse interactions between pop, gender, and religion. Examples might include Beyonce''s self-representation as the Yoruba goddess Oshun and Lil Nas X''s reinterpretation of the Garden of Eden in Montero. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('RLG197H1', 'Enchantment, Disenchantment, Re-Enchantment', '24S', 'Modernity is associated with disenchantment, secularisation and progress, and has traditionally been understood as the successor to the enchanted, spiritual, and transcendent worldviews of antiquity and the middle ages. Re-enchantment, a term increasingly encountered in popular and academic contexts alike, demonstrates nostalgia for an enchanted past, a discomfort with the modern narrative, and a desire to recover wonder. This course will examine the history of enchantment through a series of readings taken from literature, philosophy, theology, ranging from Plato to contemporary magical realism. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('RLG198H1', 'Dystopia: Religion & Gender in Science Fiction', '24S', 'This course will examine the "what ifs" and imagined worlds of ideal utopias and oppressive dystopias through the lens of religion and gender in Margaret Atwood''s The Handmaid''s Tale and Charlotte Perkins Gilman''s Herland. Because science fiction and utopian/dystopian literature expresses what an author sees as possible or hopes is possible, but also fears is possible, we will consider science fiction as a political and social critique. Themes to be covered include fundamentalism, totalitarianism, the relationship between technology and religion, religion and reproductive rights, and the potential relationship between religion, gender and oppression. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('RLG199H1', 'Contagions', '24S', 'It is obvious that infections spread through social networks; what is less well known is that forms of human behaviour, including religious affiliation, have network characteristics. This course examines a variety of historical and contemporary contagions to introduce essential concepts in network analysis and the factors that account for the spread of innovation and other forms of human behaviour. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('RLG200H1', 'The Study of Religion', '24L/12T', 'An introduction to the discipline of the study of religion. This course surveys methods in the study of religion and the history of the discipline in order to prepare students to be majors or specialists in the study of religion.', null, 2, null::jsonb),
    ('RLG201H1', 'Indigenous Spiritualities and Religions', '24L/12T', 'This course examines how Indigenous communities saw the world before contact—primarily exploring early creation narratives and ways of engaging with the natural world through ceremonials of reciprocity and acknowledgements. It engages with how early colonial societies and Western-based religions evaluated and understood Indigenous spiritualities and practices. We consider Indigenous critiques of Western religion as it has actually been practiced as opposed to what has been taught as constituting the ideals of civilization. Finally, we analyze how Indigenous communities and culture begin to create "New Religions" that blend Indigenous values and thinking with aspects of Western culture or emerge in direct response to re-imagining spirituality in attempts to prove humanness and civility in contexts where little of Indigenous culture and values has been seen as acceptable.', null, 1, null::jsonb),
    ('RLG202H1', 'Judaism', '24L/12T', 'An introduction to the religious tradition of the Jews that explores key themes as they change from ancient times to today. The set of themes will include: the Sabbath, Study, Place, Household, Power. Each year will focus on one theme. We will read holy texts, modern literature, history, ethnography, and philosophy, covering each theme in a range of genres and across the diverse span of Jewish experience.', 'RLG202H5,  RLG202Y1', 2, null::jsonb),
    ('RLG203H1', 'Christianity', '24L/12T', 'We explore the multiple religious traditions of Christianity and follow key themes as they have changed throughout the last two millennia. The themes might include: the Bible and its translation; missionizing and colonial practices; belief and conversion; authority and power; capitalism and Christianity. The course will equip students to understand how and why Christianity has come to exert such influence around the globe. No familiarity with the Bible, Christianity, or the academic study of religion is assumed.', 'RLG203H5,  RLG203Y1', 2, null::jsonb),
    ('RLG204H1', 'Islam', '24L/12T', 'An introduction to the Islamic religious tradition that explores its diversity and development, from its inception to the modern period. Themes include Pre-Islamic Arabia, the life of Muhammad and the Qur''an, the development of the notion of Sunna and Hadith, Islamic religious communities (Sunni, Shiite and Ismaili traditions), Sufism, and religious practices. The course will emphasize the complexity of the Islamic tradition both in its classical phase and in modernity including Islam in the diaspora.', 'RLG204H5,  RLG204Y1', 2, null::jsonb),
    ('RLG205H1', 'Hinduism', '24L/12T', 'This course explores themes relating to the religion of Hindus, called Hinduism since modernity. Topics include the canonical literatures, philosophies, and doctrines of Hinduism, along with the debates surrounding them; lived Hinduism, and the texts that inform its practice and experience; activities considered quintessential to Hinduism, such as temple visits, yoga, and venerating a guru; and the vibrant spectrum of Hindu expression one encounters in the diaspora. The course will equip students with fluency in core concepts and practices of Hinduism, as well as an understanding of Hindu history as one of dynamism and transformation.', 'RLG205H5,  RLG205Y1', 2, null::jsonb),
    ('RLG206H1', 'Buddhism', '24L/12T', 'This course traces the socio-historical development of Buddhist traditions across the diverse regions of South, Southeast, Central, and East Asia from their foundations in early India to their transmission in the contemporary West. Although much of our time will be spent reading, grappling with, and discussing Buddhist literary works (premodern, modern), we will also consider the institutional and practical dimensions of Buddhism as a lived tradition. To that end, weekly readings and lectures will be supplemented with maps, images, and videos to highlight the vast geographical range and significance of Buddhist traditions over time, as well as their rich visual and material cultures. By the end of the course students are expected to have a solid understanding of the basic timeline of Buddhist history in Asia, together with the major figures, key concepts, central texts, and ritual practices comprising Buddhist traditions.', 'RLG206H5,  RLG206Y1', 2, null::jsonb),
    ('RLG208H1', 'Sikhism', '24L', 'A historical and thematic introduction to the Sikh religious tradition as embedded in the socio-cultural structures of India.', 'RLG207H5', 1, null::jsonb),
    ('RLG209H1', 'Justifying Religious Belief', '24L/12T', 'Beliefs typically characterized as "religious" concern such things as the existence and nature of the deity, the afterlife, the soul, miracles, and the universe''s meaningfulness, ultimate purpose, or interest in the distribution and realization of justice. Common to these and other religious beliefs is that they lack empirical evidence to support them – at least so say religious skeptics. They insist that rational beliefs require justification and that justification comes from perceptions anyone could have or solid scientific reasoning. Anyone who harbors religious beliefs thus violates a basic epistemic responsibility. How might people who hold – and want to continue to hold – religious beliefs respond to these accusations and doubts?  The course examines these basic epistemological and moral challenges to religious belief as well as the various strategies available to religious believers who are confronted with such demands for justifications. By doing so, we will aim to understand better whether religious beliefs of various sorts could count as rational, whether reasonable people might disagree with each other about the very nature of reality and morality, and whether anyone who falls short of common intellectual and social ideals of rationality and reasonableness ought to be tolerated.', null, 2, null::jsonb),
    ('RLG211H1', 'Psychology of Religion', '24L/12T', 'This course focuses upon the psychology of religion from the perspectives of psychoanalysis, affective neuroscience, attachment theory and evolutionary psychology. We explore the nature of religious beliefs, experiences and practices as interactive creations of mind and culture. We will inquire into the relationship between belief and knowledge, subjective and objective experience/reality, phantasy, dreams and reality. How does the unconscious create and shape religious beliefs, experiences and practices? How have the insights of the founders of the field been updated by contemporary neuroscientific and evolutionary theories? We consider visionary, esoteric and paranormal experiences and consider the distinctions between mental health and pathology.', null, 2, null::jsonb),
    ('RLG212H1', 'Anthropology, Religion and Culture', '24L/12T', 'Is religion a matter of belief or a matter of practice? Do all religions share common features? Is one born into religion, or does one learn to be religious? This course is designed to introduce students to some of the ways in which anthropologists have studied and thought about religion. The emphasis is not on memorizing things people believe and do in different societies but on understanding how anthropologists have tried to explain religious phenomena. The themes covered in the course include: magic and religion; the (ir)rationality of belief; the body as a site of knowledge; ritual; ethical self-cultivation; and religion''s role in the secular age.', 'RLG212Y1', 2, null::jsonb),
    ('RLG213H1', 'Embarrassment of Scriptures', '24L', 'How do we interpret sacred texts? This course surveys interpretive approaches, methods, and traditions related to sacred texts. It covers a range of interpretive strategies such as scribal changes, commentary, visual interpretation, feminist retellings, and queer readings. The specific religious traditions, texts, and approaches will vary depending on the instructor. Students will increase their content knowledge of selected texts and their ability to critically engage texts. Prior exposure to the study of religion is not required. All readings will be in English.', null, 2, null::jsonb),
    ('RLG214H1', 'Mythologies and Religion', '24L', 'Myths and legends are narrative means for humans to make sense of their environment, the organization of their societies, and their social practices. This course introduces the principal myths and mythological figures of a selection of mythic systems (Near Eastern, Celtic, Nordic, Slavic and Indigenous North American) as way of modelling the world. Such topics as creation, chaos and order, love and death, coming of age, the monstrous, and explanations of evil and misfortune, and the survival and the transformation of mythic and folkloric elements.', null, 3, null::jsonb),
    ('RLG215H1', 'New Religious Movements', '24L/12T', 'The saying goes that "Cult + Time = Religion." In this course, we will examine this assertion, looking especially at the development of recent religions, such as Scientology. This course will probe the history of scholarship on new religious movements (once known as "cult studies") and explore the challenges inherent in studying controversial movements.', null, 2, null::jsonb),
    ('RLG217H1', 'Black Diaspora Religions', '24L/12T', 'This course critically examines the intersection of religion and cultural expressions in the African Diaspora, with a particular emphasis on the Canadian landscape. The importance of religion in the Black Diaspora''s experience of both oppression and liberation will be a key component of our analytic framework in explaining and understanding the Black/African experience and culture in the diaspora.', null, 3, null::jsonb),
    ('RLG218H1', 'Traditional Ecological Knowledge and Religion', '24L/12T', 'In modern history, sacred and sacramental understandings of nature have often been marginalised and criticized as primitive and superstitious. Today, these beliefs and practices increasingly present themselves as sources of overlooked ecological knowledge, and resources in our search for a sustainable human-nature relationship. This course focuses upon efforts to recover, reclaim and relegitimise alternative understandings of nature and traditional ecologies in the context of the contemporary environmental crisis. Students will deploy course readings as resources for considering a particular contemporary environmental challenge through field work culminating in a creative environmental project.', null, 2, null::jsonb),
    ('RLG222H1', 'Witchcraft, Religion and the Powers of the Occult', '24L/12T', 'Picture a witch in your mind''s eye. Do you see them as male, female, or somewhere between the two? Young or old? Good or evil? This course goes beyond common Western assumptions about the character and morality of witchcraft to show how its study, its representation and its practice contribute in vital ways to our understandings of religion, the occult, morality, gender, sexuality and science. We move across Europe, Africa, Melanesia and North America to shed light on a controversial figure in numerous societies and literary traditions, past and present. Depictions of witches, wiccans, sorcerers and magicians are analyzed and compared. At the same time, the course should make you ask yourself: What is rational, what is ethical—and ultimately, what is human?', 'RLG337H1', 3, null::jsonb),
    ('RLG230H1', 'Religion, Law and Society', '24L/12T', 'The course examines various issues, including: Canadian society and secularization; religious pluralism and legal pluralism; the role of religions in public contexts; land and property; marriage and women''s rights; and the place of minority religious communities.', null, 3, null::jsonb),
    ('RLG231H1', 'Music and Religion: From Bach to Leonard Cohen', '24L/12T', 'What is music to religion? This course is an exploration of religion and music from a global perspective. ''World'' music will be placed in comparative frameworks with various ''world'' religions in order to understand how music has been and continue to be at the core of religious narratives, rituals, beliefs, and cultural performances.', null, 2, null::jsonb),
    ('RLG232H1', 'Religion and Film', '24L', 'The role of film as a mediator of thought and experience concerning religious worldviews. The ways in which movies relate to humanity''s quest to understand itself and its place in the universe are considered in this regard, along with the challenge which modernity presents to this task. Of central concern is the capacity of film to address religious issues through visual symbolic forms.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG233H1', 'Religion and Popular Culture', '36L', 'A course on the interactions, both positive and negative, between religion and popular culture. We look at different media (television, advertising, print) as they represent and engage with different religious traditions, identities, and controversies.', null, 1, null::jsonb),
    ('RLG234H1', 'Language and Religion', '24L/12T', 'What is language to religion? And how is it used by humans and divine agents? This course moves across traditions, examining types of communications from speech to rhetoric to book to revelation; and types of communicators from hermit to evangelist to deity. We will see language used to clarify and to obscure; to exclude and to liberate. And we will think about miscommunication too: the message lost in transmission. All readings will be in English. No knowledge of other languages is required.', null, 1, null::jsonb),
    ('RLG235H1', 'Religion, Gender, and Sexuality', '24L/12T', 'This course equips students to understand how norms and practices of gender and sexuality are deeply entangled with religious imaginations and traditions. We will examine how ritual, scriptural, and legal traditions enable and constrain embodied and political power. Readings will draw from feminist, womanist, queer, and other perspectives. With a combination of in-class discussions, critical reading exercises, and short essay assignments, students will strengthen their awareness of transnational intersections of religion, gender, and "religio-racial" formations. You will develop skills in analyzing the role of popular culture and legal and religious texts in shaping norms and experiences of gender and embodiment.', 'RLG314H5', 2, null::jsonb),
    ('RLG236H1', 'Material Religion', '24L', 'Religions are more than beliefs or sacred texts. They are also formed through buildings, bodies, objects of devotion, images, websites. We examine how religion is embodied, circulated, built, played, displayed, and painted. We ask why religions are often constituted through feasting or fasting, excess or asceticism, abundance of objects or destruction of icons. Religious activity is explored through its connections with objects of wealth and consumption--not just great art, but items common within popular culture. The overall aim is to ''see'' religion in a new way—and to understand the role of the senses in the formation of religious experience.', null, 1, null::jsonb),
    ('RLG237H1', 'Religion, Medicine, and the Human Body', '24L/12T', 'Throughout much of human history, considerations of the wondrous workings and frightening frailty of the human body occupied a large role in religious thought and practice. This course examines how religion influenced the development of scientific thought about physiology and medicine, as well as how scientific knowledge was integrated into religious beliefs. Possible topics of discussion include attitudes towards the differences among the sexes, public health needs and the coercion of individuals, the significance of stages of life and aging, contraception and abortion, the relation between mental and physical health, and how to face the prospect of death and disease appropriately. We will also explore the role of pilgrimage sites in healthcare. Finally, we discuss the particular internal conflicts and religious experiences of medical care professionals. Regions and time periods under discussion will vary by instructor.', null, 2, null::jsonb),
    ('RLG239H1', 'Special Topics', '24L', 'This course offers an opportunity to explore a topic in the study of religion. Topics vary depending on the instructor. When offered, a detailed course description of the topic will be available on the Department for the Study of Religion website.', null, null, null::jsonb),
    ('RLG241H1', 'The Earliest Christians', '24L/12T', 'What can the earliest writings of Early Christianity tell us about the movement and its founding figure? We examine these writings critically and historically in order to understand the immense variety of early Christianity as it grew within Judaism and within the Greco-Roman World. No familiarity with Christianity or the New Testament is expected', 'RLG241H5,  HUMC14H3,  RLG241Y1', 2, null::jsonb),
    ('RLG242H1', 'Bible in America', '24L', 'This course offers a critical examination of the role of biblical texts (Hebrew Bible/Old Testament and New Testament) within the history, literature, and culture of the United States of America. It will employ a range of methodological perspectives to explore the use, influence, and impact of biblical interpretation especially regarding claims of American identity. All readings will be in English. No knowledge of Hebrew or Greek is required.', null, 1, null::jsonb),
    ('RLG243H1', 'Naked and Not Ashamed: The Book of Genesis', '24L', 'This course provides a critical introduction to the book of Genesis. It examines the historical and literary contexts of Genesis and engages diverse methods of contemporary biblical scholarship, such as narrative analysis, gender analysis, and history of interpretation. This course highlights the use of Genesis in various Jewish and Christian communities and in popular culture, including music, film, and visual arts. All readings will be in English. No knowledge of Hebrew or Greek is required.', null, 2, null::jsonb),
    ('RLG260H1', 'Introduction to Sanskrit I', '48L', 'The first semester of an introduction to Classical Sanskrit for beginners. Students build grammar and vocabulary, and begin to read texts in Sanskrit. Complete beginners are welcome. Two sections of the course will be offered: an on-campus class meeting and an online section via live webinar participation. The final exam will require attendance on the St. George campus, or in another authorized exam centre.', 'RLG260Y1', 1, null::jsonb),
    ('RLG261H1', 'Introduction to Tibetan I', '48L', 'An introduction to Classical Tibetan language for beginners. Development of basic grammar and vocabulary, with readings of simple texts. Two sections of the course may be offered: an on-campus class meeting and an online section. The final exam will require attendance on the St. George campus, or in another authorized exam centre.', 'RLG261Y1', 1, null::jsonb),
    ('RLG262H1', 'Introduction to Tibetan II', '48L', 'The second semester of an introduction to Classical Tibetan language course for beginners. Continued work on grammar and vocabulary, advancing to reading texts. Two sections of the course may be offered: an on-campus class meeting and an online section. The final exam will require attendance on the St. George campus, or in another authorized exam centre.', 'RLG261Y1', 1, '{"operator": "AND", "items": ["RLG261H1"]}'::jsonb),
    ('RLG263H1', 'Introduction to Sanskrit II', '48L', 'The second semester of an introduction to Classical Sanskrit for beginners. Students continue to build grammar and vocabulary, and use that knowledge to read texts in Sanskrit. The course will be offered online via live webinar participation.', 'RLG260Y1', 1, '{"operator": "AND", "items": ["RLG260H1"]}'::jsonb),
    ('RLG264H1', 'Introductory Pali I', '36L/12T', 'This course offers an opportunity to students interested in Buddhism to read, analyze, and discuss select simple passages from the scriptures of the Theravada canon in their original language. It will cover philosophical, psychological, and narrative texts and their interpretation, as well as provide a first exposure to the Pali Language.', null, 1, null::jsonb),
    ('RLG265H1', 'Introductory Pali II', '36L/12T', 'This course offers an opportunity to students interested in Buddhism and with basic knowledge of Pali to read, analyze, and discuss select simple passages from the scriptures of the Theravada canon in their original language. It will cover philosophical, psychological, and narrative texts and their interpretation.', null, 1, '{"operator": "AND", "items": ["RLG264H1"]}'::jsonb),
    ('RLG303H1', 'Evil and Suffering', '24L', 'The existence of evil poses a problem to theistic beliefs and raises the question as to whether a belief in a deity is incompatible with the existence of evil and human (or other) suffering. This course examines the variety of ways in which religions have dealt with the existence of evil.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG304H1', 'Language, Symbols, Self', '24L', 'Theories of the self that involve the constitutive role of language in its various forms. Problems of socially-conditioned worldviews and sense of self as related to discourse. Myth, symbol, metaphor, and literary arts as vehicles for personality development and self-transformation along religious lines.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG307H1', 'Museums and Material Religion', '24L', 'Museums have long collected and curated religious objects for public audiences, with missionaries as a primary collections source. Multiple visits to the Royal Ontario Museum and other museums will enable students to think critically about how museums received and presented these objects, while engaging with the challenges of museum curation.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG308H1', 'Migration, Religion and City Spaces', '24L', 'Immigrants have transformed cities through religious practices. Explore how transnational migration has affected religious diversity and vitality in metropolitan areas. Through discussion, site visits and analysis, students will examine the ways that immigrants use religion to make home, challenges around the establishment of new religious structures, and policy designed to accommodate new religious practices and communities.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG309H1', 'Religion and Human Rights', '24L', 'We will explore the dynamic inter-relations of women, ethnicities and minorities, among others, within the context of religion in this age of human rights, focusing on the contemporary global context. Our aim will be to include both theory and praxis. The approach will be intersectional, cross-cultural, inter-religious and inter-disciplinary. We will do this by drawing on both academic and non-academic resources, grassroots movements as well as global initiatives to approach these issues.', 'RLG309Y1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG310H1', 'Modern Atheism and the Critique of Religion: Hobbes to Kant', '24L', 'This course examines select modern thinkers and their critical approaches to the nature and significance of religious beliefs and practices. Hobbes, Spinoza, Hume, and Kant are among the major thinkers studied.', 'RLG310Y1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG311H1', 'Gender, Body and Sexuality in Asian Traditions', '24L', 'A study of women in the religious traditions of South and East Asia, including historical developments, topical issues, and contemporary women''s movements.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG312H1', 'Gender, Body and Sexuality in Islam', '24L', 'This course explores attitudes towards sexuality, gender, and women''s bodies in Islamic thought and history. We will read foundational religious texts, classic works of law and ethics, poetry, and historical documents, as well as contemporary reflections by Muslim feminist thinkers. Topics to be discussed include sexual ethics within and outside of marriage, consent to marriage and divorce, contraception and abortion, menstruation, modest dress, gender-based segregation, same-sex sexual attraction, and gender non-conformity.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG313H1', 'Love, Sex, Family', '24L', 'This course equips students to understand the religious roots of modern formations of gender, sexuality, and kinship, focusing in particular on Judaism, Christianity, and New Religious Movements. Topics we will cover include: the transformation of traditional religious structures into the modern "religion of romantic love," the reshaping of religious practices within the modern nuclear family and its gendered division of labour, the persistent religious entanglements within not only normative but also queer and transgressive gender performances and kinship structures, the political asymmetries within which different religious modernities emerge, and the role of literature in preserving religious enchantment in modernity.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG314H1', 'Pilgrimage as Idea and Practice', '24L', 'The study of pilgrimage has become increasingly prominent in anthropology and religious studies in recent decades. Why should this be? This course provides some answers while engaging in a cross cultural survey and analysis of pilgrimage practices. We also explore whether research into pilgrimage has wider theoretical significance.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG315H1', 'Rites of Passage', '24L', 'We examine rituals of transition from one social status to another (such as childbirth, coming of age, marriage) from theoretical, historical and ethnographic perspectives. We pay particular attention to the importance of rites of passage in the construction of gendered identities.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG317H1', 'Religion, Violence, and Non-Violence', '24L', 'People acting in the name of religion(s) have incited violence and worked for peace. How can we understand this tension both today and in the past? Through examination of the power of authoritative tradition, collective solidarity, charisma, and acts of resistance, this course addresses religious justifications of violence and non-violence across varied historical and geographical contexts.', 'RLG317H5', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG318H1', 'Sacred & Secular Nature in Christianity', '24L', 'How did we get to where we are now? How did humans come to be so alienated from nature? This course will examine how religion, particularly that of the Latin West, has shaped the understanding of, and interaction with, nature on a global level. It examines the complex shift from understanding nature as sacred and revelatory, to its conceptualisation as a commodity and resource. Students will explore the ethical and cultural consequences of this shift for the human-nature relationship, and contemporary attempts to recover sacred notions of nature in the context of the environmental crisis.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG319H1', 'Death, Dying and Afterlife', '24L', 'This course introduces students to various religious approaches to death, the dead, and afterlife. Through considering different ways in which death has been thought about and dealt with, we will also explore different understandings of life and answers to what it means to be human.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG320H1', 'Judaism and Christianity in the Second Century', '24L', 'Judaism and Christianity in the period from 70 C.E. to 200 C.E. The course focuses on the relationship between the two religious groups, stressing the importance of the setting within the Roman Empire.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG321H1', 'Women and the Hebrew Bible', '24L', 'This course provides a critical examination of the Hebrew Bible (sometimes called the Old Testament) with an emphasis on women characters. It examines the historical and literary contexts of Hebrew Bible texts and engages diverse methods of contemporary biblical scholarship with particular attention to issues of gender. All readings will be in English. No knowledge of Hebrew is required.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG322H1', 'Early Gospels', '24L', 'Careful examination of the earliest “lives of Jesus” (‘gospels’) shows that they offer very different portraits of Jesus of Nazareth. The course will compare ancient biographical accounts of famous ancient figures such as Alexander the Great, the Caesars, and wandering philosophers with early depictions of Jesus, both the gospels that eventually were included in the New Testament, and extra-canonical or “apocryphal” gospels such as the Gospels of Thomas, Peter, or Mary.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG323H1', 'Jesus of Nazareth', '24L', 'To what extent does Jesus who lived and taught in first-century Galilee and Judea align with the picture of Jesus in early Christian writings? We examine the methods for discerning the historical Jesus and the portraits that result from rigorous application of those methods', 'RLG323H5', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG324H1', 'The Apostle Paul and His Enemies', '24L', 'An examination of Paul''s life and thought as seen in the early Christian literature written by him (the seven undisputed letters), about him (the Acts of the Apostles, the Acts of Paul) and in his name (falsely authored compositions in early Christianity).', 'RLG324H5', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG325H1', 'The Uses and Abuses of the Bible', '24L', 'From politics to popular culture, the Bible has shaped people and nations for good and for ill. This course introduces the Jewish and Christian Bibles and considers case studies of how biblical texts have been interpreted. The Bible has been used to bolster slavery and white supremacy and to inspire political liberation movements. It has been used to justify annihilation of Indigenous people by Christian colonists yet given hope to Jews that next year in Jerusalem might be better. How can the same “book” be used for such different purposes? This course focuses on the cultural and political consequences of biblical interpretation. An underlying premise is that the Bible is not static but is rather a nomadic text as it is continuously interpreted in ways that sometimes contribute to human flourishing, but also can result in violence, human diminishment, or death.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG326H1', 'Roots of Christianity and Judaism', '24L', 'Judaism and Christianity are both considered “religions of the book” but how are they related to each other? This course considers the origins of that relationship by reading a range of Jewish texts from the 6th century BCE to the 1st century CE, including the Dead Sea Scrolls, in order to illuminate the diverse cultural matrix from which early Christianity and Judaism took shape. A major theme of the course is the formation of scriptures and scriptural interpretation as a factor in shaping distinctive Jewish cultures. Attention is also given to “lived religion” and practices that form individuals and communities.', 'RLG326H5', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG327H1', 'Hospitality and Ethics in Judaism, Christianity, and Islam', '24S', 'Refugee crises in modern times have raised questions concerning what degree of hospitality is owed the stranger or foreigner whose motivation is a new, safe, and secure home rather than being treated as a guest passing through on a time-limited visa. Jacques Derrida''s ideas of both conditional hospitality (e.g., tourists) and unconditional hospitality (e.g., strangers) need to be explored from the perspective of philosophical and ethical traditions including Jewish, Christian, and Muslim ethics.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG328H1', 'Religion, Race, and the Legacy of Cain and Abel', '24L', 'Cain''s killing of his brother Abel is one of the best known but least understood stories in the Bible. For thousands of years, interpreters have puzzled over the gaps and ambiguities of the story in order to piece together the how, what, where and why of this violent incident. This course explores the legacies of Cain and Abel across various religious traditions and in art, literature, and popular culture. It considers the surprising roles that this biblical story has played in modern ideas about religion, politics, and race. All readings will be in English. No knowledge of Hebrew is required.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG330H1', 'Visions and Revelation in Ancient Judaism and Christianity', '24L', 'What did ancient Jews and Christian see and know when they “saw” God or heavenly realms? Or when they toured hell or the infernal regions? This course examines the ancient imagination by treating the major elements of the apocalyptic literary corpus and accompanying visionary experiences in ancient Judaism and Christianity. Contemporary theories on the function and origin of apocalyptic literature inform our readings.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG331H1', 'Creation Narratives and Epistemologies', '24S', 'The course will examine the importance of Indigenous cultural knowledge and values as presented in various Indigenous Creation Narratives. Creation Narratives or Cosmological narratives have long been studied as mere mythology. Yet, it is in these very narratives that complex, layered, and nuanced epistemologies emerge. Often, these narratives not only lay the epistemological frameworks of cultural value systems, but they also contain what many refer to as original instructions and purpose for the “Original People”.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG332H1', 'Reasonable and Radical Hope', '24L', 'Human beings have a natural and necessary interest in the prospects of their happiness, their moral improvement, and a progressively more just world. When, to what extent, and on what basis our hope for these things could be reasonable have been central questions in philosophy of religion since the Enlightenment. But genocides and cultural devastation (e.g., the Holocaust or the fates of some Indigenous communities) have compelled more recent philosophers to ask not only about rational hope, but also radical hope. This course explores reasonable and radical hope, first by unpacking the well-established philosophical question of our what we may reasonably expect from ourselves and our world, and then turning to the issue of humans'' capacity to persist when their community and its culture face extinction, i.e., when they may no longer expect anything.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG333H1', 'Religion, Irreligion, and the Meaning of Life', '24L', 'Humans ask no more important question than: "what is the meaning of life?" Given its significance, the question should be asked as thoughtfully as possible. This requires us to understand not only the various religious and philosophical answers (to choose wisely you must know your options), but also the question''s terms ("what do ''meaning'' and ''life'' mean?") and historical conditions (is the question pressing perennially or only in secular societies where life has lost its meaning?). In this course students learn how to ask the question of life''s meaning well in the hopes that thereby they live better, more meaningful lives.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG334H1', 'Religion, Space and Diaspora', '24L', 'This course explores the transformation of religion, space and practices in diasporic settings. How is space adapted to the sensibilities of diasporic subjects, and how are the ritual practices that take place in those spaces transformed? The course examines historical and contemporary examples of the impact of diasporas, exile, and immigration on spatial practices in synagogues, churches, mosques, and temples, and ritual transformations in diaspora.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG335H1', 'How Religions Spread: Networks and Religion', '24S', 'Social networks are critical in the maintenance and spread of religions. This course offers an introduction to network concepts and, focusing on ancient Mediterranean religions, examines how religious ideas diffuse; networks and the creation of social capital; intersections of religious and trade or business networks; and the collapse of networks.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG336H1', 'Religion and its Monsters', '24L', 'A course looking at the theories about and responses to the monstrous in global religious traditions and practices.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG338H1', 'Religion and Religiosity in Israel/Palestine', '24L', 'Focusing on present-day Israel/Palestine, this interdisciplinary course is intended for students interested in exploring a wide range of theoretical questions and examining their applicability to the study of sites, texts, rituals, and politics in the region. We will address the history of the land''s consecration from Jewish, Christian, and Muslim perspectives. Students will analyze specific sites associated with religious congregations and ritual practices, and study them within their local and regional contexts. Looking at the complex relationships between religious-political movements and institutions within Jewish and Muslim societies, we will delve into various attempts to secularize (and theologize) Jewish and Palestinian communities and their discontents. Rather than providing the typical emphasis on conflict, the course is a journey into the history and present of the land and its diverse communities.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG339H1', 'Religious Ethics: The Jewish Tradition', '24L', 'A brief survey of the Jewish biblical and rabbinic traditions; the extension of these teachings and methods of interpretation into the modern period; common and divergent Jewish positions on pressing moral issues today.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG341H1', 'Dreaming of Zion: Exile and Return in Jewish Thought', '24L', 'An inquiry into the theme of exile and return in Judaism, often called the leading idea of Jewish religious consciousness. Starting from Egyptian slavery and the Babylonian exile, and culminating in the ideas of modern Zionism, the course will examine a cross-section of Jewish thinkers--ancient, medieval, and modern.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG342H1', 'Judaism in the Early Modern Era', '24L', 'The development and range of modern Jewish religious thought from Spinoza, Mendelssohn and Krochmal, to Cohen, Rosenzweig and Buber. Responses to the challenges of modernity and fundamental alternatives in modern Judaism.', 'RLG342Y1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG343H1', 'Kabbala: A History of Mystical Thought in Judaism', '24L', 'A historical study of the Kabbala and the mystical tradition in Judaism, with emphasis on the ideas of Jewish mystical thinkers and movements.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG344H1', 'Antisemitism', '24L', 'Explores how “Jews” have been viewed (often mistakenly and confusedly) in various contexts from pre-Christian antiquity to the contemporary world. Emphasis is on problems involved in defining and explaining antisemitism, especially concerning the difference between religious and racial forms of antisemitism.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG345H1', 'Social Ecology and Judaism', '24L', 'The environment and human society studied as systems of organization built for self-preservation. Such topics as vegetarianism and the humane treatment of animals, suicide and euthanasia, sustainability and recycling, explored from the perspective of Judaism.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG346H1', 'Time and Place in Judaism, Christianity, and Islam', '24L', 'Judaism, Christianity, and Islam each have their own sets of prayer times, frequency of prayers and their locations such as home, synagogue, temple, church or mosque. They have completely different calendrical systems. Holiness is also connected to geographical locations, which often serve as destinations of pilgrimage. This course will examine linear and cyclical times and the concepts of holiness in time and place by looking at primary sources in translation. We will investigate the persistence of holy places, how their names continue, and how gender issues are part of the jurisdictional politics of disputes over place and time.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG347H1', 'Judaism in the Late Modern Era', '24L', 'Continuing from, but not presupposing, "Judaism in the Early Modern Era," the course will trace the late modern stages in the development of Jewish thought, and will bring the history of modern Jewish thought to the present.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG348H1', 'Philosophical Responses to the Holocaust', '24L', 'This course deals with how the momentous experience of the Holocaust, the systematic state-sponsored murder of six million Jews as well as many others, has forced thinkers, both religious and secular, to rethink the human condition.', 'RLG220H1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG349H1', 'Special Topics in Judaism', '24S', 'This course offers an opportunity to explore a topic in Judaism. Topics vary depending on the instructor. When offered, a detailed course description of the topic will be available on the Department for the Study of Religion website.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG350H1', 'The Life of Muhammad', '24L', 'This course examines Muhammad''s life as reflected in the biographies and historical writings of the Muslims. Students will be introduced to the critical methods used by scholars to investigate Muhammad''s life. Issues include: relationship between Muhammad''s life and Quran teachings and the veneration of Muhammad.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG351H1', 'The Quran: An Introduction', '24L', 'The revelatory process and the textual formation of the Quran, its pre-eminent orality and its principal themes and linguistic forms; the classical exegetical tradition and some contemporary approaches to its interpretation.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG352H1', 'Post-Colonial Islam', '24L', 'This course will study Islam in a post-colonial framework. It will introduce students to the work of post-colonial studies, and how critical scholarship has transformed our understanding of monolithic concepts such as modernity, the nation and Islam. It will focus on the particular case of Islam in South Asia and the Middle East by exposing students to the transformative impact of colonialism. It will equip students with the tools to challenge the hegemonic notion of a singular ''tradition'' in Islam by tracing its lineages in the post-colony.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG353H1', 'The Politics of Charity', '24L', 'The course examines religious charitable giving, philanthropic foundations, and humanitarian aid and asks: Is charitable giving altruistic or is it always partly self-interested? Could aid perpetuate poverty? What kinds of "strings" come with receiving aid and is there such thing like a free gift?', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG354H1', 'Marriage and Divorce in Islamic Thought and Practice', '24S', 'This course begins with a survey of the Islamic intellectual tradition on the topics of how people get married, the age of marriage, the emotional and legal bond between spouses, procreation and contraception, divorce, widowhood, and child custody. It continues with an examination of the history of marriage and divorce documents and the relationship between religious theory and social practice. It concludes with an exploration of contemporary discussions within Muslim communities around the world surrounding issues of dowries, polygamy, and divorce.', 'RLG458H1 (Advanced Topics in Islam: Marriage and Divorce in Islamic Thought and Practice) offered in Winter 2024.', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG355H1', 'Living Islam', '24L', 'This course introduces students to studies of contemporary Islam that are based on extensive periods of research with Muslim communities in their own languages using anthropological methods. What do such studies teach us about the varied ways Muslims engage their religious tradition in the modern world? And how can such studies make us think differently about gender, economy, medicine, and secularism?', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG357H1', 'Blood and Babies: Women''s Reproductive Cycles and the Fetus in Christian, Islamic, and Jewish Thought and Law', '12L/12S', 'Reproductive experiences have often played a central role in women''s experience of religion -- spiritually, ritually, and legally. This course explores these themes in classical and medieval Jewish, Christian, and Islamic texts. We will study ritual purity laws and the religious significance of menstruation and other bodily fluids. We will explore attitudes towards contraception, struggles with infertility, and fear of the pain and dangers of childbirth. We will also delve into theological and legal debates about fetal development, the permissibility of abortion, and what happens to the bodies and souls of fetuses and babies who do not survive. Finally, we will explore rituals of the post-partum mother and the newborn child, including naming rituals, Christian baptism, Jewish circumcision and redemption, and Islamic aqiqah.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG358H1', 'Special Topics in Hinduism', '24L', 'This course offers an opportunity to explore a topic in Hinduism. Topics vary depending on the instructor. When offered, a detailed course description of the topic will be available on the Department for the Study of Religion website.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG359H1', 'Intermediate Sanskrit I', '24L', 'Review of grammar and the development of vocabulary with a focus on reading simple narrative prose and verse.', null, 1, '{"operator": "AND", "items": ["RLG260H1", "RLG263H1"]}'::jsonb),
    ('RLG360H1', 'Intermediate Sanskrit II', '24S', 'Review of grammar and the further development of vocabulary with a focus on reading simple narrative prose and verse.', null, 1, '{"operator": "AND", "items": ["RLG359H1"]}'::jsonb),
    ('RLG361H1', 'Hinduism: The Great Books', '24L', 'A study of the literatures of Hinduism in India and the diaspora, including issues of identity formation, nostalgic constructions of the "homeland", fictional representations, and the quest for authenticity.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG362H1', 'Rama of Ayodhya: From Literature to Politics', '24L', 'A study of the figure of Rama, from his genesis in the Valmiki Ramayana, to his historical evolution as a cultural and political icon through mediaeval and modern India.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG363H1', 'God and Love in Hinduism', '24L', 'A study of Hindu bhakti traditions through classical and vernacular texts, in conversation with colonial and post-colonial theoretical perspectives on the notion of "bhakti" in Hinduism.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG365H1', 'Hinduism Today', '24L', 'The development of modern Hindu religious thought in the contexts of colonialism, dialogue with the West and the secular Indian state.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG366H1', 'Hindu Philosophy', '24L', 'A study of different schools, texts, and issues of Hindu philosophy.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG368H1', 'Yoga, Ayurveda and Other Therapies', '24L', 'The course surveys the textual sources of the practices of Yoga, Ayurveda and Hindu traditions such as domestic rituals, rites of passage and community centered religious activity. It critically evaluates the assumption of an unbroken continuity of tradition of these practices from antiquity onwards and comes to consider what they have come to constitute as a result of modernity and globalization.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG369H1', 'The Mahabharata', '24L', 'A study of the great Sanskrit epic, the Mahabharata.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG371H1', 'Interdependence', '24L/12P', 'An exploration of the Buddhist concept of interdependence, or interdependent origination, from doctrinal and contemplative perspectives, as presented in classic Buddhist texts and as used in contemporary environmental and activist movements globally.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG372H1', 'Engaging Tibet', '24L', 'This course examines the history of global engagement with Tibetan religions, including contemporary adoptions of Tibetan religious identities outside the Tibetan plateau. The course begins in the Buddhist past by examining some of the earliest recorded Tibetan debates on religious identity and authority. It then moves to the modern period to compare non-Tibetan depictions of Tibetan religious traditions with indigenous Tibetan forms of self-representation. The course thus addresses questions regarding the plurality of Tibetan religious identities from Buddhist to Bön to Islamic and the ways that these identities interact with historical romanticizations of Tibet.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG373H1', 'Buddhist Ritual', '24L', 'Daily worship, the alms round, life-crisis celebrations, healing rituals, meditation, festivals, pilgrimage, the consecration of artefacts and taking care of the ancestors are among the forms of Buddhist ritual introduced and analyzed in this course. Liturgical manuals, ethnographic descriptions and audiovisual records form the basis for a discussion of the role of ritual as text and event.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG374H1', 'Buddhist Life Stories', '24L', 'This course explores the genres of autobiography and biography in Buddhist literature. The course will begin with theoretical studies on narrative and religious life-writing. We will then consider the development and distinctive features of auto/biographies and hagiographies in the literature of one or more Buddhist cultures, analyzing representative examples of these genres from a range of traditions and historical periods, and considering how these sources have been understood and used in secondary scholarship.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG375H1', 'Biohacking Breath', '24L', 'This course explores Buddhist practices of manipulating – or “biohacking” – the breath or “winds” (prāna) of the human body, covering relevant theories of human anatomy and physiology and the religious, philosophical, and medical teachings alongside which these practices developed. Intentional breathing practices in the history of European thought and the role of breathwork in contemporary global biohacking movements will also be studied for comparison and contrast. During experiential lab sessions, basic prānāyāma and other breathing practices will be learned and practiced with the guidance of qualified teacher-practitioners.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG376H1', 'Touching the Earth', '24L', 'A study of Buddhist relationships with the earth, including “earth touching” contemplative practices, ritual ceremonies for land spirits or sacred sites, geomantic and cosmographic traditions, the use of landscape imagery to depict enlightenment, contrasts between wilderness and urban spaces, and contemporary ecological movements in Buddhist communities and their responses to climate disruption. The course combines experiential learning approaches and outdoor excursions with reading and written work.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG377H1', 'Intermediate Tibetan I', '36S', 'This course provides a review of classical Tibetan grammar through the study and translation of texts from a variety of genres. These include selections from Tibetan philosophical works, canonical Buddhist discourses, Tibetan historical writings, autobiographies, and dream narratives.', 'RLG370Y1', 1, null::jsonb),
    ('RLG378H1', 'Intermediate Tibetan II', '36S', 'This course provides a review of classical Tibetan grammar through the study and translation of texts from a variety of genres. These include selections from Tibetan philosophical works, canonical Buddhist discourses, Tibetan historical writings, autobiographies, and dream narratives.', 'RLG370Y1', 1, null::jsonb),
    ('RLG379H1', 'Religions of the Silk Road', '24L', 'An historical introduction to the religious traditions that flourished along the Silk Road, including Zoroastrianism, Manichaeism, Nestorian Christianity, Judaism, Buddhism and Islam. Drawing on a variety of sources (textual, archaeological, works of art), the course will focus on the spread and development of these traditions through the medieval period. Issues include cross-cultural exchange, religious syncretism, ethnic identity formation and so on. Emphasis will also be placed on religious and political events in modern Central Asia.', 'RLG245H1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG380H1', 'Trauma, Healing & Transformation', '24L', 'This course focuses upon the psychology of religion from the perspectives of psychoanalysis, affective neuroscience, attachment theory and evolutionary psychology. We explore the role of entheogens, psycholytics and dreams in facilitating and shaping mystical experiences of unseen realms. We will explore relationships and boundaries between belief and knowledge, subjective and objective experiences, as well as phantasy, dreams and visions. How are the insights of the founders of the field being updated by contemporary neuroscientific and evolutionary theories? We consider visionary, esoteric and paranormal experiences along with the distinctions between mental health and pathology.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG381H1', 'Buddhism and Science', '24L/12P', 'An introduction to interdisciplinary research on Buddhism and science. Topics to be considered may include the rise of Contemplative Science as a field; contemporary methods for studying types of meditation; how research on contemplative practices is influenced by philosophical, feminist, and queer studies work on consciousness, self, and embodiment; the global commodification of “spiritual” practices; and the impact of Buddhist social justice movements on the field.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG382H1', 'God and Communism: State Policies and Religious Practices in the Soviet Union and Post-Soviet Space', '24L', 'The Russian Revolution of 1917 proclaimed the separation of Church and State in the newly created Soviet Russia and later, Soviet Union. How did it work in practice? This course will examine both policies that addressed Orthodox Christianity, Catholicism, Islam, Judaism, Buddhism and other religious practices and practices of how these policies were received and interpreted on the ground. We will read anti-religious propaganda materials created in the 1920s, memoirs and diaries of priests, rabbis and imams making sense of the 1930s, often when imprisoned in Gulag for their work, press materials and ego-documents of World War II, novels, poems and short stories addressing religious beliefs in the post-war Soviet Union. Finally, we will discuss the religious revival of the 1990s, when both indigenous religions and those brought in by Western missionaries have entered post-Soviet public sphere. All course materials will be provided in English translation.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG383H1', 'Interpretation and Dialogue', '24L', 'How do people negotiate across different religions? Can we understand the beliefs and behaviors of people whose religious and cultural outlooks differ radically from our own? This course explores the theoretical issues involved in interpretation and dialogue across cultural and historical divides by reading key texts within the study of religion, including anthropological, historical, and philosophical approaches.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG384H1', 'Pluralism and Toleration', '24L', 'This course traces the development of philosophical arguments in favor of toleration or pluralism that emerged first in response to bitter religious conflicts and then out of a growing recognition of the potential benefits of the normative diversity characteristic of modern societies. Typical philosophers to be studied are Bodin, Spinoza, Locke, Bayle, Lessing, Herder, and Mill.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG385H1', 'Becoming Modern: Institutions, Individuals, and the Dark Side of Modernity', '24L', 'What does it mean to be modern? Words like “modern,” “modernity,” and “modernism” are used to mark a fundamental boundary between our era and all that came before it (or lies outside of it); but most of us are hard-pressed to offer a solid account of what exactly this boundary is. This course examines the relationship between: a fundamental shift in the nature of daily experience; an order-of-magnitude expansion of the power of the State; a dramatic reorganization of religious experience and cultures; and a tremendous growth in the enterprise of Western science and technological production. We trace this reorientation over the last two centuries and examine its consequences using philosophical, literary, theological, and scientific sources, as well as recent scholarly work on the topic.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG386H1', 'Devotional Literature of Early Modern India', '24L', 'This class is an introduction to the devotional literature of early modern India (c. 1500-1800), but more importantly, it is about thinking critically and developing skills in close reading of texts. In addition to learning about historical, religious, and social contexts of various literary traditions in Brajbhasha, students will be expected to demonstrate their ability to analyze and interpret texts by actively participating in class discussions and by writing a well-argued final paper. The focus will be on the what of literary traditions but also on the how and why these traditions made sense to people in the past and are still relevant to us, today.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG387H1', 'Religion and Science', '24L', 'Course explores issues at the intersection of religion and science which may include such topics as evolution and the assessment of its religious significance by different traditions, conceptions of God held by scientists (theism, pantheism, panentheism), ethical issues raised by scientific or technological developments ( cloning or embryonic stem cell research), philosophical analysis of religious and scientific discourses.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG388H1', 'Special Topics I', '24L', 'This course offers an opportunity to explore a topic in the study of religion. Topics vary depending on the instructor. When offered, a detailed course description of the topic will be available on the Department for the Study of Religion website.', null, null, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG389H1', 'Special Topics II', '24L', 'This course offers an opportunity to explore a topic in the study of religion. Topics vary depending on the instructor. When offered, a detailed course description of the topic will be available on the Department for the Study of Religion website.', null, null, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG390H1', 'Thinking with Spirits', '24S', 'Possession, trance, communication with the spirits of the dead, visitations by gods, demons, or spectral presences from unseen, otherworldly realms are common features of human experience. What are the psychological, emotional and mental capacities that give rise to such ecstatic, extraordinary experiences? What is the role of unconscious fantasy and projection in such experiences and how do these ideas contribute to explanatory theories seeking to account for them? What contribution can psychoanalysis make to enriched, generous and non-pathologizing understandings of the wide variety of spirit encounters, communications and visions that have been reported throughout history and across cultures? This course will draw upon disciplines such as psychoanalysis, anthropology, neuropsychoanalysis and the study of religion in order to think deeply and sensitively about and with spirits.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG391H1', 'Modern Atheism and Critique of Religion: Hegel to Nietzsche', '24L', 'Examines select modern thinkers and their critical approaches to the nature and significance of religious beliefs and practices. Hegel, Feuerbach, Marx, and Nietzsche are among the major thinkers studied.', 'RLG310Y1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG392H1', 'The European Enlightenment and Religion', '24L', 'This course explores some of the major thinkers of the European Enlightenment and their philosophical inquiries into the meaning and significance of religion as a set of cultural institutions. Special attention is paid to the analysis of religious concepts and institutions along epistemological, ethical, and political lines.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG393H1', 'Graphic Religion: Myth and the Spiritual in Graphic Novels', '24L', 'Survey of themes connecting religious ideas, symbols, and representations with graphic novels and sequential art. The course will explore techniques of story-telling in mythic and visual representations in religious traditions and explore how these techniques and images are mirrored within popular comic-style (sequential) art.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG395H1', 'Is Religion Useful?', '24L', 'While some philosophers count truth and falsehood decisive when evaluating religion, others regard that focus as beside the most crucial point, namely, whether religion is good or bad for us. In other words, the reasons that they cite in favor of or against religious beliefs, rituals, associations, etc. are instead its social, ethical, or psychological utility or disutility. This course looks at these philosophical debates about whether and how religion might be useful to us in our individual and collective lives.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG396H1', 'The Soul of Food: Religion, Food, and the Construction of Community', '24L/12P', 'Food is an essential part of religion, but how does food - how it''s produced, prepared, and consumed - reveal the values and beliefs of religious communities? How do the material practices of food - including dietary laws, rituals, feasts, and fasts - construct religious identity and community? This course will challenge students to think about these questions through experiential learning opportunities, including a community-engaged research project and guided visits to local religious food sites. Through active learning, critical thinking, and reflective practice, students will examine the ways in which food has significant social and ethical implications for religious communities.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RLG398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('RLG398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('RLG399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('RLG399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('RLG400Y1', 'Independent Studies Abroad', null, 'Intensive programs of study including site visits and lectures in areas of religious significance abroad. Preparatory work expected, together with paper or assignments upon return.(Y1 course: 4 weeks minimum; H course: 2 weeks minimum) Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('RLG401H1', 'Independent Studies Abroad', null, 'Intensive programs of study including site visits and lectures in areas of religious significance abroad. Preparatory work expected, together with paper or assignments upon return.(Y1 course: 4 weeks minimum; H course: 2 weeks minimum) Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('RLG402H1', 'Independent Studies Abroad', null, 'Intensive programs of study including site visits and lectures in areas of religious significance abroad. Preparatory work expected, together with paper or assignments upon return.(Y1 course: 4 weeks minimum; H course: 2 weeks minimum) Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('RLG404H1', 'Departmental Capstone-Research', '24S', 'This seminar gives you the chance to explore the role of research in undergraduate education, and to construct a retrospective view of your and others'' experiences of studying religion in the university. Each student will also develop a research project and will examine a range of audiences for their research, from specialists in their field, to wider academic scholars, to an audience beyond the university. Interaction between students will be a central feature of the work of the seminar. Open to students in the Majors and Specialists of the Department for the Study of Religion.', null, null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}]}'::jsonb),
    ('RLG405H1', 'Departmental Capstone-Practical', '24S', 'A capstone seminar that emphasizes integration of the study of religion with contemporary public life in the development of a research project, locating a research specialization in relation to non-academic contexts, and communicating the process and results of a research project to non-academic audiences. Open to students in the Majors and Specialists of the Department for the Study of Religion.', null, null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}]}'::jsonb),
    ('RLG406H1', 'Constructing Religion', '24S', 'How have different researchers constructed ''religion'' as their object of study, and are some frameworks simply incompatible with each other? We discuss – but also provide critical assessments of -- different theoretical and methodological frameworks. Open to students in the Majors and Specialists of the Department for the Study of Religion.', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('RLG407H1', 'The World of "World Religion"', '24S', 'A seminar examining the development of western discourses of world religions. We shall explore the roots of these discourses and examine their implications in the academic study of religion in North America and in other parts of the world. Open to students in the Majors and Specialists of the Department for the Study of Religion.', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('RLG411H1', 'Advanced Topics in Religion', '24S', 'This course offers an opportunity to explore a specialized topic in the study of religion. Topics vary depending on the instructor. When offered, a detailed course description of the topic will be available on the Department for the Study of Religion website.', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('RLG412H1', 'Advanced Topics in Religion', '24S', 'This course offers an opportunity to explore a specialized topic in the study of religion. Topics vary depending on the instructor. When offered, a detailed course description of the topic will be available on the Department for the Study of Religion website.', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('RLG414H1', 'Comparing Religions', '24S', 'Few methods have been more foundational to the scholarly study of religion, or more subject to searching criticism, than the practice of comparison. This seminar offers an advanced introduction to comparative method through close study of 4-6 recent works, from ritual studies, philosophy of religion, comparative theology and/or ethnography.', null, 2, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}]}'::jsonb),
    ('RLG415H1', 'Performance, Gender, Religion', '24S', '“Performance, Gender, Religion” will explore gendered religious experience through the lens of performance and theories of performativity. Topics include: The inculcation of religious norms through required gender performance, the performative dimension of religious ritual, and performance culture within religious communities. We will not only consider the ways in which “manhood” and “womanhood” are performed, we will also consider performances that critique and confront these categories. Students will have the opportunity to engage in a research project on gender performance from a specific cultural context.', null, 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('RLG416H1', 'Topics in Religion and Gender', '24S', 'This course offers an opportunity to explore a topic focusing on the intersection of religion and gender. Topics vary depending on the instructor. When offered, a detailed course description of the topic will be available on the Department for the Study of Religion website.', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('RLG417H1', 'Radical Evil: Philosophical, Psychoanalytic and Religious  Perspective', '24S', 'Are people innately evil, or do they become evil due to negative life experiences? Can a universal internal moral imperative rooted in an innate good will exist independently of self-interest? Some argue that human beings are motivated by amoral internal forces that are only shaped into moral action through diverse cultural learning processes. These questions are discussed from philosophical, psychoanalytic and religious perspectives.', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('RLG418H1', 'Advanced Topics in the Philosophical Study of Religion', '24S', 'A seminar that explores a topic in the philosophical study of religion. Possible topics include: the nature of religious truth; the phenomenology of religion; descriptions of the holy; religion and the meaning of life; God-talk as literal or metaphorical language; naturalizing religious belief. When offered, a detailed course description of the topic will be available on the Department for the Study of Religion website.', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, "RLG209H1"]}'::jsonb),
    ('RLG419H1', 'Ghosts to Ancestors: Racialized Hauntings and Reparative Promise in Psychoanalysis', '24S', 'All forms of injustice disfigure both societies and psyches. Racist, sexist, and other unconscious fantasies of evil and persecuting ''others'' generate social injustice. At the same time, social injustice distorts the mind. This "dual track" process can drive human beings and their societies mad. Justice depends upon transformations of social structures and moral codes as well as changes within human minds. In order for psychoanalysis to realize its own potential for facilitating justice, it must confront its own historical contribution to injustice. Through a close reading of selected texts from Sigmund Freud and the activist psychiatrist Franz Fanon, this course explores the inherent tensions between colonizing and emancipatory themes within psychoanalytic discourses. Both Freud and Fanon contribute to a psychoanalytic critical theory that have influenced several contemporary ethnographic writers who explore the intricate ways in which social and cultural realities are internalized as unconscious hauntings and tormenting spirits across generations.', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["RLG211H1", "RLG301H1", "RLG302H1"]}]}'::jsonb),
    ('RLG420H1', 'Religion and Philosophy in the European Enlightenment', '24S', 'An advanced study of selected Enlightenment thinkers with a focus on their interpretations of religion. The main thinkers discussed are Spinoza, Hume, and Kant. Issues include the rational critique of traditional religion, the relations among religion, ethics and politics, and the pursuit of universal approaches to religion.', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["RLG310H1", "RLG392H1"]}]}'::jsonb),
    ('RLG421H1', 'Fragments of Redemption: Sigmund Freud and Theodor Adorno', '24S', 'This course will challenge the prevailing view that the thought of Sigmund Freud and Theodor Adorno is so deeply pessimistic as to be devoid of hope. Freud''s psychoanalytic theories are widely (mis)interpreted in the register of a crude pansexualism and biological determinism. Adorno''s critique of society and the individual is often (mis)interpreted as so ruthlessly pervasive that it forecloses on any possibility for emancipatory transformation. This is a distorted view of both thinkers, that misses the hopeful, utopian currents that motivate and shape psychoanalysis and critical theory. The course will explore the emancipatory currents in Freud and Adorno, and their implications for potentialities of individual, social and ecological transformation.', null, 2, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}]}'::jsonb),
    ('RLG422H1', 'Kant''s Theory of Religion', '24S', 'An advanced study of Immanuel Kant''s theory of religion, as developed in major writings such as Critique of Practical Reason and Religion within the Boundaries of Mere Reason. Emphasizes rational ethical criteria as the basis for analyzing the doctrines, symbols, and institutions of historical religions.', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["RLG310H1", "RLG392H1"]}]}'::jsonb),
    ('RLG423H1', 'Great Critics of Religion', '24S', 'An advanced study of the work of David Hume on the topic of religion. We explore Hume''s empiricist and skeptical methodologies as applied to religious concepts and doctrines, and we unravel the many literary devices he used to protect himself from persecution. Works studied include the Enquiry concerning Human Understanding, Natural History of Religion, and Dialogues concerning Natural Religion. Critics will vary by term and instructor.', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["RLG310H1", "RLG392H1"]}]}'::jsonb),
    ('RLG425H1', 'Hermeneutics and Religion', '24S', 'A study of how principles of textual interpretation and theories of language have been central to modern philosophy of religion. We begin with Schleiermacher, and then move to an in-depth treatment of the 20th century hermeneutical theories of Heidegger, Gadamer, and Ricoeur.', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["RLG310H1", "RLG392H1"]}]}'::jsonb),
    ('RLG426H1', 'Religion in the Public Sphere: Community-Engaged Learning', '24S', 'In a placement with a community partner, students are given an opportunity to learn about and reflect upon the ways that religion and religious diversity shape public life. How do individuals and organizations recognize and negotiate the intersections of religious diversity, culture, and public space in the context of engaging with public policy? Through critical classroom discussions, readings, reflections, and meaningful work for and with front-line community partners, community-engaged learning offers students the opportunity to integrate academic knowledge with experiences outside the classroom, to challenge themselves, and to explore their values and future directions. Application Process: Interested students must complete the online application form on the DSR website to indicate their interest in and expectations of community engaged learning, as well as any previous volunteer/co-op/internship experience they may have had. Following submission of student applications, the course instructor(s) will contact student applicants individually to conduct a brief informational interview. Interviews will be conducted, at which time students will be enrolled by the department.', null, null, null::jsonb),
    ('RLG428H1', 'Religion and Economy', '24S', 'This course introduces students to classical and contemporary social scientific work on the relation between religion and economy. It draws on classics such as Marx, Weber, and Mauss, as well as recent anthropological work. Topics may include sacrifice, the gift, commodity fetishism, prosperity gospel, neoliberalism, charity, and development.', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('RLG430H1', 'Advanced Topics in Judaism', '24S', 'This course offers an opportunity to explore a specialized topic in Judaism. Topics vary depending on the instructor. When offered, a detailed course description of the topic will be available on the Department for the Study of Religion website.', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, "RLG202H1"]}'::jsonb),
    ('RLG433H1', 'Maimonides and His Modern Interpreters', '24S', 'An introduction to The Guide of the Perplexed by Moses Maimonides, and to some of the basic themes in Jewish philosophical theology and religion. Among topics to be considered through close textual study of the Guide: divine attributes; biblical interpretation; creation versus eternity; prophecy; providence, theodicy, and evil; wisdom and human perfection. Also to be examined are leading modern interpreters of Maimonides.', 'POL421H1', 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('RLG434H1', 'Modern Jewish Thought', '24S', 'Close study of major themes, texts, and thinkers in modern Jewish thought. Focus put on the historical development of modern Judaism, with special emphasis on the Jewish religious and philosophical responses to the challenges of modernity. Among modern Jewish thinkers to be considered: Spinoza, Cohen, Rosenzweig, Buber, Scholem, Strauss, and Fackenheim.', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('RLG435H1', 'The Thought of Leo Strauss', '24S', 'The philosophic thought of Leo Strauss approached through his writings on modern Judaism. Primarily addressed will be the mutual relations between philosophy, theology, and politics. Among other topics to be dealt with: origins of modern Judaism, Zionism, liberal democracy, and biblical criticism; meaning of Jerusalem and Athens; cognitive value in the Hebrew Bible.', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('RLG441H1', 'Words and Worship in Christian Cultures', '24S', 'How are we to analyze the words that Christians use? And how are such words related to ritual forms? We explore techniques for the analysis of texts, while looking at forms of verbal discourse ranging from prayers, speaking in tongues, and citing the Bible to more informal narratives.', null, 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["RLG212H1", "ANT356H1"]}]}'::jsonb),
    ('RLG447H1', 'Magic and Miracle in Early Christianity', '24S', 'Magic, religion, astrology, alchemy, theurgy, miracle, divination: all of these phenomena characterize the context and practice of ancient Christianity. This course examines the constitution of these categories, the role and character of these phenomena in the Graeco-Roman world, and the interaction with and integration of these phenomena by ancient Christianity.', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["RLG203H1", "RLG241H1"]}]}'::jsonb),
    ('RLG448H1', 'Pseudepigraphy in Ancient Mediterranean Religion', '24S', 'A seminar examining the phenomenon of falsely claimed and/or attributed authorship in religions of the ancient Mediterranean, mainly Christianity and Judaism. The course examines understandings of authorship and other cultural forms that facilitate or inhibit ancient pseudepigraphy, ancient controversies over authorship, as well as specific pseudepigraphical writings.', null, 1, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}]}'::jsonb),
    ('RLG449H1', 'The Sources of the Gospels', '36S', 'Investigation of the history of solutions to the Synoptic Problem from the eighteenth century to the present paying special attention to the revival of the Griesbach hypothesis and recent advances in the Two-Document hypothesis.', null, 1, '{"operator": "AND", "items": ["RLG241H1", {"operator": "OR", "items": ["RLG320H1", "RLG321H1", "RLG322H1", "RLG323H1", "RLG324H1", "RLG325H1", "RLG326H1"]}]}'::jsonb),
    ('RLG451H1', 'The Parables of Jesus', '24S', 'Examination of the parables in the gospels and other early Christian writers, and major trends in the modern analyses of the parables. Special attention will be paid to the social and economic world presupposed by the parables.', null, 1, '{"operator": "AND", "items": ["RLG241H1", {"operator": "OR", "items": ["RLG320H1", "RLG321H1", "RLG322H1", "RLG323H1", "RLG324H1", "RLG325H1", "RLG326H1"]}]}'::jsonb),
    ('RLG452H1', 'The Death of Jesus', '24S', 'Examination of the accounts of the passion and death of Jesus in their original historical and literary contexts.', null, 3, '{"operator": "AND", "items": ["RLG241H1", {"operator": "OR", "items": ["RLG320H1", "RLG321H1", "RLG322H1", "RLG323H1", "RLG324H1", "RLG325H1", "RLG326H1"]}]}'::jsonb),
    ('RLG453H1', 'Christianity and Judaism in Colonial Context', '24S', 'Sets the study of early Christianity and Second Temple Judaism into relation with postcolonial historiography. Topics include hybridity, armed resistance, the intersection of gender and colonization, diaspora, acculturation, and the production of subaltern forms of knowledge. Comparative material and theories of comparison are also treated.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}]}'::jsonb),
    ('RLG454H1', 'Social History of the Jesus Movement', '24S', 'The social setting of the early Jesus movement in Roman Palestine and the cities of the Eastern Empire. Topics will include: rank and legal status; patronalia and clientalia; marriage and divorce; forms of association outside the family; slavery and manumission; loyalty to the empire and forms of resistance.', null, 3, '{"operator": "AND", "items": ["RLG241H1", {"operator": "OR", "items": ["RLG320H1", "RLG321H1", "RLG322H1", "RLG323H1", "RLG324H1", "RLG325H1", "RLG326H1"]}]}'::jsonb),
    ('RLG455H1', 'Heresy and Deviance in Early Christianity', '24S', 'A study of the construction of deviance or heresy within the literature of first and second century Christianity: tasks include a survey of sociological theory in its application to deviance in the ancient world and close readings of selected texts from first and second century Christian and pre-Christian communities.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}]}'::jsonb),
    ('RLG458H1', 'Advanced Topics in Islam', '24S', 'This course offers an opportunity to explore a specialized topic in Islam. Topics vary depending on the instructor. When offered, a detailed course description of the topic will be available on the Department for the Study of Religion website.', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["RLG204H1", "RLG355H1"]}]}'::jsonb),
    ('RLG460H1', 'Ramayana in Literature, Theology, and Political Imagination', '24S', 'This course explores how this conception is the result of a historical process by examining documentable transformations in the reception of the Ramayana. Our focus will be on the shift in the classification of the Ramayana from the inaugural work of Sanskrit literary culture (adi-kavya) in Sanskrit aesthetics to a work of tradition (smrti) in theological commentaries, the differences between the Ramayana''s ideal of divine kingship and medieval theistic approaches to Rama''s identification with Visnu, the rise of Rama worship, and the use of Rama''s divinity in contemporary political discourse.', null, 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('RLG461H1', 'Buddhism and Indigeneity', '24S', 'In dominant discourse, Buddhism travels and, upon its arrival, enlightens, reforms, improves, or civilizes whoever was there before. In this course we will ask how that view disagrees with people for whom Buddhism is not something that comes later but something that comes first, who say: “We have always been Buddhists.” Such an alternative vision of Buddhism is shared by communities who fight against caste discrimination, occupation by foreign powers, or the destruction of their world. In conversation with members of Indigenous communities visiting our class, we will ask what Buddhist Studies can contribute towards decolonization and Indigenous empowerment, particularly for Indigenous people in Canada.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('RLG462H1', 'Newar Religion', '24L/24T', 'An academic legend recounts that if you ask a Newar whether he is Hindu or Buddhist the answer is yes. The course deals with the problem of how to study religions which coexist and compete with each other creating shifting coordinates of religious identification from the perspective of one specific Nepalese community.', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('RLG463H1', 'Tibetan Buddhism', '24S', 'Close study of major themes, texts, and thinkers in Tibetan Buddhism. Themes and texts will vary by year; consult the departmental website for this year''s course description.', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('RLG465H1', 'Readings in Buddhist Texts', '24S', 'An advanced study of select Buddhist texts with a focus on issues of translation, interpretation, commentarial approaches, narrative strategies, as well as issues related to the production, circulation, and consumption of these works. Themes and texts will vary by year; consult the departmental website for this year''s course description.', null, 1, null::jsonb),
    ('RLG468H1', 'Special Topics in Buddhism', '24S', 'This course offers an opportunity to explore a specialized topic in Buddhism. Topics vary depending on the instructor. When offered, a detailed course description of the topic will be available on the Department for the Study of Religion website.', null, 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, "RLG206H1"]}'::jsonb),
    ('RLG471H1', 'Special Topics in Hinduism', '24S', 'This course offers an opportunity to explore a specialized topic in Hinduism. Topics vary depending on the instructor. When offered, a detailed course description of the topic will be available on the Department for the Study of Religion website.', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, "RLG205H1"]}'::jsonb),
    ('RLG474H1', 'Sanskrit Readings I', '24S', 'This course will have students read choice pieces of South Asian literature. While tackling a text in Sanskrit from a major literary tradition, Buddhist or Hindu, and discussing its content and context, students will learn strategies for translating and interpreting Sanskrit literature.', null, 1, '{"operator": "AND", "items": ["RLG359H1", "RLG360H1"]}'::jsonb),
    ('RLG476H1', 'Caste and its "Other"', '24S', 'This course focuses on works of South Asian fiction and non-fiction that deal with caste in Indian society. By looking at a range of texts from Classical Sanskrit literature in translation to contemporary radical Dalit perspective writings, we aim to arrive at an understanding of why, despite social and economic mobility, caste remains the indelible marker of modern Indian identity even today.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('RLG481H1', 'Islamic Intellectual Tradition', '24S', 'This seminar covers three main areas of the Islamic intellectual tradition: legal, theological and mystical. Each section will be covered by reading an original work translated into English with the aid of secondary literature. The seminar will develop the students'' knowledge of the classical Islamic tradition. Students will choose a research topic and develop and present to the class a synopsis of their research. The seminar culminates in writing a research paper on one aspect of the Islamic religious tradition.', null, 1, '{"operator": "OR", "items": ["RLG204H1", "RLG355H1"]}'::jsonb),
    ('RLG490Y1', 'Independent Studies', '48S', 'Student-initiated intensive research courses supervised by faculty members of the Department. The student must obtain both a Supervisor''s agreement and the Associate Chair''s approval and fill out the Independent Studies Course form in consultation with the Supervisor with information on the proposed course in order to register. The form is available on our website. The maximum number of Independent Studies courses one may take is 2.0 credits. Deadline for submitting applications to Department, including Supervisor''s approval, is the end of the first week of classes of the session. A 1.0 credit course may be compressed into a single session or spread through two sessions; a 0.5 credit course may similarly be done in either one session or across two sessions. These courses are open to RLG majors and specialists only. Not eligible for CR/NCR option. Please send completed forms and direct any questions to religion.undergrad@utoronto.ca.', null, null, null::jsonb),
    ('RLG491H1', 'Independent Studies', '24S', 'Student-initiated intensive research courses supervised by faculty members of the Department. The student must obtain both a Supervisor''s agreement and the Associate Chair''s approval and fill out the Independent Studies Course form in consultation with the Supervisor with information on the proposed course in order to register. The form is available on our website. The maximum number of Independent Studies courses one may take is 2.0 credits. Deadline for submitting applications to Department, including Supervisor''s approval, is the end of the first week of classes of the session. A full-course may be compressed into a single session or spread through two sessions; a half-course may similarly be done in either one session or across two sessions. These courses are open to RLG majors and specialists only. Not eligible for CR/NCR option. Please send completed forms and direct any questions to religion.undergrad@utoronto.ca.', null, null, null::jsonb),
    ('RLG492H1', 'Independent Studies', '24S', 'Student-initiated intensive research courses supervised by faculty members of the Department. The student must obtain both a Supervisor''s agreement and the Associate Chair''s approval and fill out the Independent Studies Course form in consultation with the Supervisor with information on the proposed course in order to register. The form is available on our website. The maximum number of Independent Studies courses one may take is 2.0 credits. Deadline for submitting applications to Department, including Supervisor''s approval, is the end of the first week of classes of the session. A 1.0 credit course may be compressed into a single session or spread through two sessions; a 0.5 credit course may similarly be done in either one session or across two sessions. These courses are open to RLG majors and specialists only. Not eligible for CR/NCR option. Please send completed forms and direct any questions to religion.undergrad@utoronto.ca.', null, null, null::jsonb),
    ('RLG493H1', 'Independent Studies', '24S', 'Student-initiated intensive research courses supervised by faculty members of the Department. The student must obtain both a Supervisor''s agreement and the Associate Chair''s approval and fill out the Independent Studies Course form in consultation with the Supervisor with information on the proposed course in order to register. The form is available on our website. The maximum number of Independent Studies courses one may take is 2.0 credits. Deadline for submitting applications to Department, including Supervisor''s approval, is the end of the first week of classes of the session. This 0.5 credit course may be done in either one session or across two sessions. These courses are open to RLG majors and specialists only. Not eligible for CR/NCR option. Please send completed forms and direct any questions to religion.undergrad@utoronto.ca.', null, null, null::jsonb),
    ('RLG494Y1', 'Independent Studies', '48S', 'Student-initiated intensive research courses supervised by faculty members of the Department. The student must obtain both a Supervisor''s agreement and the Associate Chair''s approval and fill out the Independent Studies Course form in consultation with the Supervisor with information on the proposed course in order to register. The form is available on our website. The maximum number of Independent Studies courses one may take is 2.0 credits. Deadline for submitting applications to Department, including Supervisor''s approval, is the end of the first week of classes of the session. A full-course may be compressed into a single session or spread through two sessions; a half-course may similarly be done in either one session or across two sessions. These courses are open to RLG majors and specialists only. Not eligible for CR/NCR option. Please send completed forms and direct any questions to religion.undergrad@utoronto.ca.', null, null, null::jsonb),
    ('RSM100H1', 'Introduction to Management', '24L', 'Introduction to management and its subdisciplines. Themes include business in a Canadian context, the nature of corporations, corporate governance, organizational behavior, operations, and strategy. Enrolment limited to students entering the University with an expressed interest in studying at Rotman Commerce.', 'MGT100H1,  RSM100Y1', 3, null::jsonb),
    ('RSM210H1', 'Special Topics in Management', '24L', 'Topics and Issues in Management. Content in any given year will depend on the instructor. See the Rotman Commerce website (www.rotmancommerce.utoronto.ca) for a full course description.', null, null, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RSM211H1', 'Special Topics in Management', '24L', 'Topics and Issues in Management. Content in any given year will depend on the instructor. See the Rotman Commerce website (www.rotmancommerce.utoronto.ca) for a full course description.', null, null, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RSM212H1', 'Special Topics in Management', '24L', 'Topics and Issues in Management. Content in any given year will depend on the instructor. See the Rotman Commerce website (www.rotmancommerce.utoronto.ca) for a full course description.', null, null, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RSM213H1', 'Special Topics in Management', '24L', 'Topics and Issues in Management. Content in any given year will depend on the instructor. See the Rotman Commerce website (www.rotmancommerce.utoronto.ca) for a full course description.', null, null, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('RSM219H1', 'Introduction to Financial Accounting', '24L/12T', 'Basic introduction to financial reporting and analysis. Emphasis is on decision-making and interpretation of financial statements and how they can be used to plan a firm''s overall business activities through the use of real-world companies. Coverage includes the use of accounting information to prepare a basic set of financial statements. Not eligible for CR/NCR option. Contact Rotman Commerce for details. Note: This course is normally taken in first year.', null, 3, null::jsonb),
    ('RSM220H1', 'Intermediate Financial Accounting I', '24L/12T', 'Foundations of financial reporting and analysis in Canada. Financial accounting topics are covered at an intermediate level, including both conceptual and technical aspects. Not eligible for CR/NCR option. Contact Rotman Commerce for details.', null, 3, '{"operator": "AND", "items": ["RSM219H1"]}'::jsonb),
    ('RSM221H1', 'Intermediate Financial Accounting II', '24L/12T', 'Covers topics such as income statement and balance sheet topics with an emphasis on quality of earnings. Not eligible for CR/NCR option. Contact Rotman Commerce for details.', null, 3, '{"operator": "AND", "items": ["RSM220H1"]}'::jsonb),
    ('RSM222H1', 'Management Accounting I', '24L/12T', 'Covers the conceptual and analytical foundations of management accounting and the applications of cost accounting information. Costing and control concepts are analyzed to equip students with tools for establishing costing systems, making business decisions, and evaluating management performance. Materials are designed to help students understand strategic cost management principles. Not eligible for CR/NCR option. Contact Rotman Commerce for details.', null, 3, '{"operator": "AND", "items": ["RSM219H1"]}'::jsonb),
    ('RSM225H1', 'Legal Environment of Business I', '24L', 'Introduces students to the Canadian legal system as it relates to business entities. The course focuses on general legal concepts, including sources of law and the court structure; business entity law (including corporate law), commercial law (contract) as well as the law of torts. Not eligible for CR/NCR option. Contact Rotman Commerce for details.', null, 3, null::jsonb),
    ('RSM230H1', 'Financial Markets', '24L', 'Introduction to Canadian and international financial markets. This course provides an overview of the major financial institutions, financial markets, financial securities, and an introduction to valuation and trading of securities. Securities discussed include stocks and bonds, as well as some content on derivatives. Not eligible for CR/NCR option. Contact Rotman Commerce for details. Note: This course is normally taken in first year.', 'MGT230H1', 3, null::jsonb),
    ('RSM250H1', 'Principles of Marketing', '24L', 'Students receive an introduction to the basic concepts, theories, and methods of contemporary marketing. The course offers a comprehensive framework to develop successful marketing efforts and allows students to create a marketing plan. Specific topics examined: market research, consumer behaviour, segmentation, product policy, pricing, distribution, communications, sales, and direct marketing. Not eligible for CR/NCR option. Contact Rotman Commerce for details. Note: This course is normally taken in first year.', 'MGT250H1', 2, null::jsonb),
    ('RSM260H1', 'Organizational Behaviour', '24L', 'Theoretical ideas and practical applications concerning the behaviour of individuals and groups in organizations. We explore relevant topics for management: motivation, personality, perception, decision-making, groups, and negotiation. A fee of $10 will be charged to your student account for a simulation handbook. Not eligible for CR/NCR option. Contact Rotman Commerce for details.', 'IRE260H1,  PSY332H1,  WDW260H1', 2, null::jsonb),
    ('RSM270H1', 'Operations Management', '24L', 'Introduction to the management of business processes that convert inputs (labor, material, equipment) into outputs (goods and services) for internal and external markets. Topics include aggregate planning, inventory processes, supply chain management and service operations management. Presents modern quantitative and computing tools necessary for in-depth operational design and analysis. Not eligible for CR/NCR option. Contact Rotman Commerce for details.', null, 5, null::jsonb),
    ('RSM295Y0', 'Special Topics', '24L', 'The areas of concentration depend on the instructor teaching the course. (Offered only during the summer session through the Summer Abroad Program). Not eligible for CR/NCR option. Contact Rotman Commerce for details.', null, null, null::jsonb),
    ('RSM296Y0', 'Special Topics', '24L', 'The areas of concentration depend on the instructor teaching the course. (Offered only during the Summer Session through the Summer Abroad Program). Not eligible for CR/NCR option. Contact Rotman Commerce for details.', null, null, null::jsonb),
    ('RSM297Y0', 'Special Topics', '24L', 'The areas of concentration and location depend on the instructor teaching the course. (Offered only during the Summer Session through the Summer Abroad Program). Not eligible for CR/NCR option. Contact Rotman Commerce for details.', null, null, null::jsonb),
    ('RSM301H1', 'Independent Study', null, 'Open when a faculty member is willing and able to supervise. Students must obtain the approval of the Director of Rotman Commerce and the supervising faculty member before enrolling. Enrolment is restricted to Rotman Commerce students. Consult the Rotman Commerce Office for details. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
